// Fragen fürs Forscher-Quiz. Nicht von Hand ändern: Vorlage in tools/quiz/*.json,
// neu erzeugen mit: python3 tools/make_quiz_bank.py
import { Lang } from './i18n';

export type BankText = { q: string; a: string[]; x: string };
export type BankQuestion = {
  id: string;
  lvl: 1 | 2 | 3; // 1 mittel, 2 schwer, 3 sehr schwer
  type: 'text' | 'tf' | 'pic' | 'duel' | 'rank'; // pic: ein großes Bild, duel: zwei gegeneinander, rank: Rangliste
  right: number; // rank: immer 10123 (richtige Reihenfolge)
  img?: string[]; // pic: Bild aus QuizArt
  t: Record<Lang, BankText>;
};

export const BANK: BankQuestion[] = [
  { id: "f01", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer hält hohes Tempo länger durch?", a: ["Gabelbock", "Gepard"], x: "Der Gepard ist zwar schneller, sprintet aber nur wenige hundert Meter. Der Gabelbock hält über 50 km/h kilometerweit durch." }, en: { q: "Who can keep up a high speed for longer?", a: ["Pronghorn", "Cheetah"], x: "The cheetah is faster but only sprints a few hundred metres. The pronghorn can keep up over 50 km/h for kilometres." }, fr: { q: "Qui tient une grande vitesse le plus longtemps ?", a: ["Antilope d’Amérique", "Guépard"], x: "Le guépard est plus rapide, mais ne sprinte que quelques centaines de mètres. L’antilope d’Amérique tient plus de 50 km/h sur des kilomètres." }, es: { q: "¿Quién aguanta más tiempo a gran velocidad?", a: ["Berrendo", "Guepardo"], x: "El guepardo es más rápido, pero solo esprinta unos cientos de metros. El berrendo mantiene más de 50 km/h durante kilómetros." } } },
  { id: "f02", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer ist das größte Raubtier an Land?", a: ["Eisbär", "Sibirischer Tiger"], x: "Eisbär-Männchen wiegen 400 bis 700 kg und sind damit die größten Landraubtiere. Sibirische Tiger erreichen etwa 300 kg." }, en: { q: "Who is the largest land carnivore?", a: ["Polar bear", "Siberian tiger"], x: "Male polar bears weigh 400 to 700 kg, making them the largest land carnivores. Siberian tigers reach about 300 kg." }, fr: { q: "Qui est le plus grand carnivore terrestre ?", a: ["Ours polaire", "Tigre de Sibérie"], x: "L’ours polaire mâle pèse 400 à 700 kg : c’est le plus grand carnivore terrestre. Le tigre de Sibérie atteint environ 300 kg." }, es: { q: "¿Quién es el mayor carnívoro terrestre?", a: ["Oso polar", "Tigre siberiano"], x: "El oso polar macho pesa de 400 a 700 kg y es el mayor carnívoro terrestre. El tigre siberiano llega a unos 300 kg." } } },
  { id: "f03", lvl: 3, type: "duel", right: 1, t: { de: { q: "Wer ist näher mit dem Hund verwandt?", a: ["Tüpfelhyäne", "Seehund"], x: "Robben gehören zu den „hundeartigen“ Raubtieren, wie Bären und Marder. Hyänen sehen zwar hundeähnlich aus, sind aber näher mit Katzen verwandt." }, en: { q: "Who is more closely related to the dog?", a: ["Spotted hyena", "Harbour seal"], x: "Seals belong to the “dog-like” carnivores, along with bears and weasels. Hyenas look like dogs but are more closely related to cats." }, fr: { q: "Qui est le plus proche parent du chien ?", a: ["Hyène tachetée", "Phoque veau-marin"], x: "Les phoques font partie des carnivores « caniformes », comme les ours et les martres. La hyène ressemble à un chien mais est plus proche des chats." }, es: { q: "¿Quién es pariente más cercano del perro?", a: ["Hiena manchada", "Foca común"], x: "Las focas pertenecen a los carnívoros «caniformes», como osos y mustélidos. La hiena parece un perro, pero está más emparentada con los gatos." } } },
  { id: "f04", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer kann rückwärts fliegen?", a: ["Spatz", "Kolibri"], x: "Kolibris schlagen ihre Flügel bis zu 80-mal pro Sekunde in Achterform. So können sie in der Luft stehen und sogar rückwärts fliegen." }, en: { q: "Who can fly backwards?", a: ["Sparrow", "Hummingbird"], x: "Hummingbirds beat their wings up to 80 times a second in a figure of eight. That lets them hover and even fly backwards." }, fr: { q: "Qui peut voler en arrière ?", a: ["Moineau", "Colibri"], x: "Le colibri bat des ailes jusqu’à 80 fois par seconde en forme de huit. Il peut ainsi faire du sur-place et même voler en arrière." }, es: { q: "¿Quién puede volar hacia atrás?", a: ["Gorrión", "Colibrí"], x: "El colibrí bate las alas hasta 80 veces por segundo en forma de ocho. Así puede quedarse quieto en el aire e incluso volar hacia atrás." } } },
  { id: "f05", lvl: 3, type: "duel", right: 1, t: { de: { q: "Wer ist näher mit dem Pferd verwandt?", a: ["Kuh", "Nashorn"], x: "Pferde, Nashörner und Tapire sind Unpaarhufer. Kühe sind Paarhufer – und damit näher mit Walen verwandt als mit Pferden." }, en: { q: "Who is more closely related to the horse?", a: ["Cow", "Rhino"], x: "Horses, rhinos and tapirs are odd-toed ungulates. Cows are even-toed – and so more closely related to whales than to horses." }, fr: { q: "Qui est le plus proche parent du cheval ?", a: ["Vache", "Rhinocéros"], x: "Chevaux, rhinocéros et tapirs sont des périssodactyles. La vache est un artiodactyle – plus proche des baleines que du cheval." }, es: { q: "¿Quién es pariente más cercano del caballo?", a: ["Vaca", "Rinoceronte"], x: "Caballos, rinocerontes y tapires son perisodáctilos. La vaca es un artiodáctilo, más emparentada con las ballenas que con el caballo." } } },
  { id: "f06", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer hat mehr Knochen?", a: ["Ein Erwachsener", "Ein Neugeborenes"], x: "Babys kommen mit rund 300 Knochen zur Welt. Viele davon wachsen später zusammen – Erwachsene haben 206." }, en: { q: "Who has more bones?", a: ["An adult", "A newborn baby"], x: "Babies are born with around 300 bones. Many of them fuse later – adults have 206." }, fr: { q: "Qui a le plus d’os ?", a: ["Un adulte", "Un nouveau-né"], x: "Le bébé naît avec environ 300 os. Beaucoup se soudent ensuite – l’adulte en a 206." }, es: { q: "¿Quién tiene más huesos?", a: ["Un adulto", "Un recién nacido"], x: "Los bebés nacen con unos 300 huesos. Muchos se fusionan después: un adulto tiene 206." } } },
  { id: "f07", lvl: 3, type: "duel", right: 1, t: { de: { q: "Wer kommt länger ohne zu trinken aus?", a: ["Dromedar", "Kängururatte"], x: "Die Kängururatte aus den Wüsten Nordamerikas trinkt oft ihr ganzes Leben lang nicht – sie gewinnt Wasser aus trockenen Samen. Dromedare halten etwa zwei Wochen durch." }, en: { q: "Who can go longer without drinking?", a: ["Dromedary camel", "Kangaroo rat"], x: "The kangaroo rat of North American deserts often never drinks in its whole life – it gets water from dry seeds. Camels last about two weeks." }, fr: { q: "Qui tient le plus longtemps sans boire ?", a: ["Dromadaire", "Rat-kangourou"], x: "Le rat-kangourou des déserts d’Amérique du Nord ne boit souvent jamais de sa vie : il tire l’eau des graines sèches. Le dromadaire tient environ deux semaines." }, es: { q: "¿Quién aguanta más sin beber?", a: ["Dromedario", "Rata canguro"], x: "La rata canguro de los desiertos de Norteamérica a menudo no bebe en toda su vida: saca el agua de semillas secas. El dromedario aguanta unas dos semanas." } } },
  { id: "f08", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer frisst einen Teil seines Kots absichtlich noch einmal?", a: ["Reh", "Wildkaninchen"], x: "Kaninchen fressen weiche Kotkügelchen direkt wieder auf. So holen sie beim zweiten Durchgang die Vitamine und Nährstoffe aus der schwer verdaulichen Pflanzenkost." }, en: { q: "Who eats some of its own droppings on purpose?", a: ["Roe deer", "Wild rabbit"], x: "Rabbits eat soft droppings straight away. On the second pass they get the vitamins and nutrients out of their hard-to-digest plant food." }, fr: { q: "Qui mange exprès une partie de ses crottes ?", a: ["Chevreuil", "Lapin de garenne"], x: "Le lapin mange tout de suite certaines crottes molles. Au second passage, il tire vitamines et nutriments de sa nourriture végétale difficile à digérer." }, es: { q: "¿Quién se come a propósito parte de sus excrementos?", a: ["Corzo", "Conejo silvestre"], x: "El conejo se come enseguida unas bolitas blandas. En la segunda pasada saca las vitaminas y nutrientes de su comida vegetal, difícil de digerir." } } },
  { id: "f09", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer schluckt absichtlich Steine?", a: ["Löwe", "Krokodil"], x: "Krokodile schlucken Steine. Im Magen helfen sie beim Zerkleinern der Nahrung und vielleicht auch beim Tauchen als Ballast." }, en: { q: "Who swallows stones on purpose?", a: ["Lion", "Crocodile"], x: "Crocodiles swallow stones. In the stomach they help grind up food and perhaps act as ballast for diving." }, fr: { q: "Qui avale des pierres exprès ?", a: ["Lion", "Crocodile"], x: "Le crocodile avale des pierres. Dans l’estomac, elles aident à broyer la nourriture et servent peut-être de lest pour plonger." }, es: { q: "¿Quién se traga piedras a propósito?", a: ["León", "Cocodrilo"], x: "Los cocodrilos tragan piedras. En el estómago ayudan a triturar la comida y quizá sirven de lastre para bucear." } } },
  { id: "f10", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer kann im Stehen dösen?", a: ["Pferd", "Hund"], x: "Pferde können ihre Beingelenke einrasten lassen und so im Stehen dösen. Für den Tiefschlaf legen aber auch sie sich hin." }, en: { q: "Who can doze while standing up?", a: ["Horse", "Dog"], x: "Horses can lock their leg joints and doze standing up. For deep sleep, though, they lie down too." }, fr: { q: "Qui peut somnoler debout ?", a: ["Cheval", "Chien"], x: "Le cheval peut bloquer ses articulations et somnoler debout. Pour le sommeil profond, il se couche quand même." }, es: { q: "¿Quién puede dormitar de pie?", a: ["Caballo", "Perro"], x: "El caballo puede bloquear las articulaciones de las patas y dormitar de pie. Para el sueño profundo, también se tumba." } } },
  { id: "f11", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer trägt sein Junges in einem Beutel?", a: ["Koala", "Faultier"], x: "Koalas sind Beuteltiere. Das Junge ist bei der Geburt nur so groß wie eine Bohne und wächst im Beutel monatelang weiter." }, en: { q: "Who carries its baby in a pouch?", a: ["Koala", "Sloth"], x: "Koalas are marsupials. At birth the baby is only the size of a bean and keeps growing in the pouch for months." }, fr: { q: "Qui porte son petit dans une poche ?", a: ["Koala", "Paresseux"], x: "Le koala est un marsupial. À la naissance, le petit est grand comme un haricot et grandit des mois dans la poche." }, es: { q: "¿Quién lleva a su cría en una bolsa?", a: ["Koala", "Perezoso"], x: "El koala es un marsupial. Al nacer, la cría es del tamaño de una judía y sigue creciendo en la bolsa durante meses." } } },
  { id: "f12", lvl: 1, type: "duel", right: 0, t: { de: { q: "Welches Säugetier legt Eier?", a: ["Ameisenigel", "Igel"], x: "Der Ameisenigel aus Australien legt Eier und brütet sie in einer Bauchtasche aus. Trotz Stacheln ist er nicht mit unserem Igel verwandt, der lebende Junge bekommt." }, en: { q: "Which mammal lays eggs?", a: ["Echidna", "Hedgehog"], x: "The Australian echidna lays eggs and incubates them in a belly pouch. Despite its spines, it isn’t related to the hedgehog, which gives birth to live young." }, fr: { q: "Quel mammifère pond des œufs ?", a: ["Échidné", "Hérisson"], x: "L’échidné d’Australie pond des œufs et les couve dans une poche ventrale. Malgré ses piquants, il n’est pas parent du hérisson, qui met au monde des petits vivants." }, es: { q: "¿Qué mamífero pone huevos?", a: ["Equidna", "Erizo"], x: "El equidna australiano pone huevos y los incuba en una bolsa del vientre. Pese a sus púas, no es pariente del erizo, que pare crías vivas." } } },
  { id: "f13", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer ist giftig?", a: ["Schnabeltier-Männchen", "Biber"], x: "Männliche Schnabeltiere haben an den Hinterbeinen einen Giftsporn. Der Stich ist für Menschen extrem schmerzhaft, aber nicht tödlich." }, en: { q: "Who is venomous?", a: ["Male platypus", "Beaver"], x: "Male platypuses have a venomous spur on their hind legs. The sting is extremely painful for humans, but not deadly." }, fr: { q: "Qui est venimeux ?", a: ["Ornithorynque mâle", "Castor"], x: "L’ornithorynque mâle a un ergot venimeux aux pattes arrière. La piqûre est extrêmement douloureuse pour l’humain, mais pas mortelle." }, es: { q: "¿Quién es venenoso?", a: ["Ornitorrinco macho", "Castor"], x: "El ornitorrinco macho tiene un espolón venenoso en las patas traseras. Su picadura es muy dolorosa para los humanos, pero no mortal." } } },
  { id: "f14", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer hat Fingerabdrücke wie wir?", a: ["Koala", "Hund"], x: "Koala-Fingerabdrücke sehen unseren so ähnlich, dass man sie selbst unter dem Mikroskop kaum unterscheiden kann – obwohl Koalas gar nicht eng mit uns verwandt sind." }, en: { q: "Who has fingerprints like ours?", a: ["Koala", "Dog"], x: "Koala fingerprints look so much like ours that they’re hard to tell apart even under a microscope – although koalas aren’t closely related to us at all." }, fr: { q: "Qui a des empreintes digitales comme les nôtres ?", a: ["Koala", "Chien"], x: "Les empreintes du koala ressemblent tant aux nôtres qu’on les distingue à peine au microscope – alors qu’il n’est pas proche parent de l’humain." }, es: { q: "¿Quién tiene huellas dactilares como las nuestras?", a: ["Koala", "Perro"], x: "Las huellas del koala se parecen tanto a las nuestras que cuesta distinguirlas incluso al microscopio, aunque no es pariente cercano nuestro." } } },
  { id: "f15", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer schwitzt am ganzen Körper?", a: ["Pferd", "Hund"], x: "Pferde schwitzen wie wir am ganzen Körper. Hunde haben Schweißdrüsen fast nur an den Pfoten und kühlen sich durch Hecheln." }, en: { q: "Who sweats all over its body?", a: ["Horse", "Dog"], x: "Horses sweat all over their body like we do. Dogs have sweat glands almost only on their paws and cool down by panting." }, fr: { q: "Qui transpire de tout son corps ?", a: ["Cheval", "Chien"], x: "Le cheval transpire de tout son corps, comme nous. Le chien n’a des glandes sudoripares presque qu’aux coussinets et se rafraîchit en haletant." }, es: { q: "¿Quién suda por todo el cuerpo?", a: ["Caballo", "Perro"], x: "El caballo suda por todo el cuerpo como nosotros. El perro casi solo tiene glándulas sudoríparas en las almohadillas y se refresca jadeando." } } },
  { id: "f16", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer bleibt länger unter Wasser?", a: ["See-Elefant", "Seelöwe"], x: "See-Elefanten tauchen bis etwa 2 Stunden und über 1.000 m tief. Seelöwen bleiben meist nur wenige Minuten unten." }, en: { q: "Who stays underwater longer?", a: ["Elephant seal", "Sea lion"], x: "Elephant seals dive for up to about 2 hours and over 1,000 m deep. Sea lions usually stay down only a few minutes." }, fr: { q: "Qui reste le plus longtemps sous l’eau ?", a: ["Éléphant de mer", "Otarie"], x: "L’éléphant de mer plonge jusqu’à environ 2 heures et à plus de 1 000 m. L’otarie ne reste en général que quelques minutes." }, es: { q: "¿Quién aguanta más bajo el agua?", a: ["Elefante marino", "León marino"], x: "El elefante marino bucea hasta unas 2 horas y a más de 1.000 m. El león marino suele quedarse solo unos minutos." } } },
  { id: "f17", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer fliegt schneller?", a: ["Libelle", "Honigbiene"], x: "Große Libellen erreichen über 50 km/h und fangen ihre Beute im Flug. Honigbienen fliegen etwa 25 bis 30 km/h." }, en: { q: "Who flies faster?", a: ["Dragonfly", "Honeybee"], x: "Large dragonflies reach over 50 km/h and catch their prey in flight. Honeybees fly at about 25 to 30 km/h." }, fr: { q: "Qui vole le plus vite ?", a: ["Libellule", "Abeille"], x: "Les grandes libellules dépassent 50 km/h et attrapent leurs proies en vol. L’abeille vole à environ 25 à 30 km/h." }, es: { q: "¿Quién vuela más rápido?", a: ["Libélula", "Abeja"], x: "Las libélulas grandes superan los 50 km/h y cazan en pleno vuelo. La abeja vuela a unos 25-30 km/h." } } },
  { id: "f18", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer ist näher mit dem Hai verwandt?", a: ["Delfin", "Rochen"], x: "Rochen sind im Grunde platte Haie – ebenfalls mit Knorpelskelett. Delfine sind Säugetiere und atmen Luft." }, en: { q: "Who is more closely related to the shark?", a: ["Dolphin", "Ray"], x: "Rays are basically flattened sharks – also with a cartilage skeleton. Dolphins are mammals and breathe air." }, fr: { q: "Qui est le plus proche parent du requin ?", a: ["Dauphin", "Raie"], x: "La raie est en somme un requin aplati – elle aussi à squelette de cartilage. Le dauphin est un mammifère qui respire de l’air." }, es: { q: "¿Quién es pariente más cercano del tiburón?", a: ["Delfín", "Raya"], x: "La raya es básicamente un tiburón aplanado, también con esqueleto de cartílago. El delfín es un mamífero y respira aire." } } },
  { id: "f19", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer hat mehr Arten von Farb-Sinneszellen im Auge?", a: ["Fangschreckenkrebs", "Mensch"], x: "Fangschreckenkrebse haben 12 Sorten Farbrezeptoren, wir nur 3. Trotzdem unterscheiden sie Farben eher schlechter – ihr Gehirn wertet sie anders aus." }, en: { q: "Who has more kinds of colour receptors in its eyes?", a: ["Mantis shrimp", "Human"], x: "Mantis shrimps have 12 kinds of colour receptors, we have only 3. Even so, they’re actually worse at telling colours apart – their brain processes them differently." }, fr: { q: "Qui a le plus de types de cellules des couleurs dans l’œil ?", a: ["Crevette-mante", "Humain"], x: "La crevette-mante a 12 sortes de récepteurs de couleur, nous seulement 3. Pourtant, elle distingue plutôt moins bien les couleurs – son cerveau les traite autrement." }, es: { q: "¿Quién tiene más tipos de células del color en el ojo?", a: ["Camarón mantis", "Humano"], x: "El camarón mantis tiene 12 tipos de receptores de color y nosotros solo 3. Aun así, distingue peor los colores: su cerebro los procesa de otra forma." } } },
  { id: "f20", lvl: 3, type: "duel", right: 1, t: { de: { q: "Was wiegt zusammen mehr?", a: ["Alle Ameisen", "Alle Menschen"], x: "Eine Studie von 2022 schätzt: Alle Ameisen der Welt wiegen zusammen etwa ein Fünftel so viel wie alle Menschen. Es sind zwar 20 Billiarden – aber jede ist winzig." }, en: { q: "What weighs more in total?", a: ["All ants", "All humans"], x: "A 2022 study estimated that all the ants in the world together weigh about a fifth as much as all humans. There are 20 quadrillion of them – but each one is tiny." }, fr: { q: "Qu’est-ce qui pèse le plus au total ?", a: ["Toutes les fourmis", "Tous les humains"], x: "Une étude de 2022 estime que toutes les fourmis du monde pèsent ensemble environ un cinquième du poids de tous les humains. Elles sont 20 millions de milliards – mais minuscules." }, es: { q: "¿Qué pesa más en total?", a: ["Todas las hormigas", "Todos los humanos"], x: "Un estudio de 2022 calcula que todas las hormigas del mundo juntas pesan una quinta parte que todos los humanos. Son 20.000 billones, pero cada una es diminuta." } } },
  { id: "f21", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer brütet beim Kaiserpinguin das Ei aus?", a: ["Das Männchen", "Das Weibchen"], x: "Das Männchen hält das Ei zwei Monate lang auf den Füßen unter einer Bauchfalte – im antarktischen Winter, ohne zu fressen. Das Weibchen ist so lange auf dem Meer." }, en: { q: "Who incubates the egg in emperor penguins?", a: ["The male", "The female"], x: "The male holds the egg on his feet under a fold of belly skin for two months – in the Antarctic winter, without eating. The female is out at sea all that time." }, fr: { q: "Qui couve l’œuf chez le manchot empereur ?", a: ["Le mâle", "La femelle"], x: "Le mâle garde l’œuf deux mois sur ses pattes, sous un repli du ventre – en plein hiver antarctique, sans manger. La femelle est en mer pendant ce temps." }, es: { q: "¿Quién incuba el huevo en el pingüino emperador?", a: ["El macho", "La hembra"], x: "El macho sostiene el huevo dos meses sobre las patas bajo un pliegue del vientre, en pleno invierno antártico y sin comer. La hembra está mientras tanto en el mar." } } },
  { id: "f22", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer ist näher mit uns Menschen verwandt?", a: ["Seestern", "Tintenfisch"], x: "Kaum zu glauben: Seesterne und Seeigel gehören zu derselben großen Tiergruppe wie die Wirbeltiere. Tintenfische sind Weichtiere und stehen uns ferner." }, en: { q: "Who is more closely related to us humans?", a: ["Starfish", "Squid"], x: "Hard to believe: starfish and sea urchins belong to the same big animal group as vertebrates. Squids are molluscs and further from us." }, fr: { q: "Qui est le plus proche parent de l’être humain ?", a: ["Étoile de mer", "Calmar"], x: "Incroyable : étoiles de mer et oursins font partie du même grand groupe que les vertébrés. Le calmar est un mollusque, plus éloigné de nous." }, es: { q: "¿Quién es pariente más cercano de los humanos?", a: ["Estrella de mar", "Calamar"], x: "Aunque cueste creerlo, estrellas y erizos de mar pertenecen al mismo gran grupo que los vertebrados. El calamar es un molusco, más lejano a nosotros." } } },
  { id: "f23", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer schläft mit einer Gehirnhälfte?", a: ["Delfin", "Hund"], x: "Delfine schlafen abwechselnd mit einer Gehirnhälfte. Die andere bleibt wach – so atmen sie weiter und achten auf Gefahren." }, en: { q: "Who sleeps with half its brain?", a: ["Dolphin", "Dog"], x: "Dolphins sleep with one half of their brain at a time. The other half stays awake – so they keep breathing and watch for danger." }, fr: { q: "Qui dort avec une moitié de cerveau ?", a: ["Dauphin", "Chien"], x: "Le dauphin dort avec une moitié du cerveau à la fois. L’autre reste éveillée – il continue ainsi à respirer et à guetter le danger." }, es: { q: "¿Quién duerme con medio cerebro?", a: ["Delfín", "Perro"], x: "El delfín duerme con una mitad del cerebro cada vez. La otra sigue despierta, así sigue respirando y vigila los peligros." } } },
  { id: "f24", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer kann über das Wasser rennen?", a: ["Grüner Leguan", "Stirnlappenbasilisk"], x: "Der Basilisk rennt auf den Hinterbeinen übers Wasser: Er schlägt die Füße so schnell auf, dass er nicht einsinkt. Leguane schwimmen." }, en: { q: "Who can run across water?", a: ["Green iguana", "Plumed basilisk"], x: "The basilisk runs across water on its hind legs: it slaps its feet down so fast that it doesn’t sink. Iguanas swim." }, fr: { q: "Qui peut courir sur l’eau ?", a: ["Iguane vert", "Basilic vert"], x: "Le basilic court sur l’eau sur ses pattes arrière : il frappe la surface si vite qu’il ne s’enfonce pas. L’iguane, lui, nage." }, es: { q: "¿Quién puede correr sobre el agua?", a: ["Iguana verde", "Basilisco verde"], x: "El basilisco corre sobre el agua con las patas traseras: golpea la superficie tan rápido que no se hunde. La iguana nada." } } },
  { id: "f25", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer bleibt meist ein Leben lang beim selben Partner?", a: ["Höckerschwan", "Stockente"], x: "Schwanenpaare bleiben meist zusammen, solange beide leben. Stockenten suchen sich jedes Jahr einen neuen Partner." }, en: { q: "Who usually stays with the same partner for life?", a: ["Mute swan", "Mallard"], x: "Swan pairs usually stay together as long as both are alive. Mallards find a new partner every year." }, fr: { q: "Qui reste en général avec le même partenaire toute sa vie ?", a: ["Cygne tuberculé", "Canard colvert"], x: "Les couples de cygnes restent en général ensemble toute leur vie. Le colvert change de partenaire chaque année." }, es: { q: "¿Quién suele quedarse con la misma pareja toda la vida?", a: ["Cisne vulgar", "Ánade real"], x: "Las parejas de cisnes suelen seguir juntas mientras viven. El ánade real busca pareja nueva cada año." } } },
  { id: "f26", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer hat ein drittes Augenlid?", a: ["Mensch", "Katze"], x: "Katzen haben eine Nickhaut, die quer übers Auge wischt und es schützt. Bei uns ist davon nur ein kleiner Rest im Augenwinkel übrig." }, en: { q: "Who has a third eyelid?", a: ["Human", "Cat"], x: "Cats have a nictitating membrane that sweeps across the eye to protect it. In us, only a tiny remnant is left in the corner of the eye." }, fr: { q: "Qui a une troisième paupière ?", a: ["Humain", "Chat"], x: "Le chat a une membrane nictitante qui balaie l’œil pour le protéger. Chez nous, il n’en reste qu’un petit vestige au coin de l’œil." }, es: { q: "¿Quién tiene un tercer párpado?", a: ["Humano", "Gato"], x: "El gato tiene una membrana nictitante que barre el ojo para protegerlo. A nosotros solo nos queda un pequeño resto en el rabillo del ojo." } } },
  { id: "e01", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer ist schneller?", a: ["Adler", "Papagei"], x: "Im Sturzflug erreichen Steinadler über 200 km/h. Papageien fliegen meist mit 30 bis 60 km/h." }, en: { q: "Who is faster?", a: ["Eagle", "Parrot"], x: "Golden eagles reach over 200 km/h in a dive. Parrots usually fly at 30 to 60 km/h." }, fr: { q: "Qui est le plus rapide ?", a: ["Aigle", "Perroquet"], x: "En piqué, l’aigle royal dépasse les 200 km/h. Les perroquets volent en général à 30 à 60 km/h." }, es: { q: "¿Quién es más rápido?", a: ["Águila", "Loro"], x: "En picado, el águila real supera los 200 km/h. Los loros suelen volar a 30 a 60 km/h." } } },
  { id: "e02", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer schläft mehr am Tag?", a: ["Giraffe", "Tiger"], x: "Tiger dösen 16 bis 20 Stunden am Tag. Giraffen schlafen nur wenige Stunden, oft im Stehen und in kurzen Nickerchen." }, en: { q: "Who sleeps more each day?", a: ["Giraffe", "Tiger"], x: "Tigers doze 16 to 20 hours a day. Giraffes sleep only a few hours, often standing and in short naps." }, fr: { q: "Qui dort le plus par jour ?", a: ["Girafe", "Tigre"], x: "Le tigre somnole 16 à 20 heures par jour. La girafe ne dort que quelques heures, souvent debout et par petites siestes." }, es: { q: "¿Quién duerme más al día?", a: ["Jirafa", "Tigre"], x: "Los tigres dormitan de 16 a 20 horas al día. Las jirafas solo duermen unas pocas horas, a menudo de pie y en siestas cortas." } } },
  { id: "e06", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer ist näher mit den Vögeln verwandt?", a: ["Schildkröte", "Eidechse"], x: "Erbgut-Vergleiche zeigen: Schildkröten sind näher mit Vögeln und Krokodilen verwandt als mit Eidechsen und Schlangen." }, en: { q: "Who is more closely related to birds?", a: ["Turtle", "Lizard"], x: "DNA comparisons show that turtles are more closely related to birds and crocodiles than to lizards and snakes." }, fr: { q: "Qui est le plus proche parent des oiseaux ?", a: ["Tortue", "Lézard"], x: "L’ADN le montre : les tortues sont plus proches des oiseaux et des crocodiles que des lézards et des serpents." }, es: { q: "¿Quién es pariente más cercano de las aves?", a: ["Tortuga", "Lagartija"], x: "Las comparaciones de ADN lo muestran: las tortugas están más emparentadas con aves y cocodrilos que con lagartijas y serpientes." } } },
  { id: "e08", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer ist näher mit den Insekten verwandt?", a: ["Krabbe", "Schnecke"], x: "Krabben und Insekten sind Gliederfüßer mit Panzer und gegliederten Beinen. Insekten haben sich sogar aus Krebstieren entwickelt." }, en: { q: "Who is more closely related to insects?", a: ["Crab", "Snail"], x: "Crabs and insects are arthropods with an armour and jointed legs. Insects even evolved from crustaceans." }, fr: { q: "Qui est le plus proche parent des insectes ?", a: ["Crabe", "Escargot"], x: "Crabes et insectes sont des arthropodes, avec carapace et pattes articulées. Les insectes descendent même des crustacés." }, es: { q: "¿Quién es pariente más cercano de los insectos?", a: ["Cangrejo", "Caracol"], x: "Cangrejos e insectos son artrópodos con caparazón y patas articuladas. Los insectos incluso evolucionaron a partir de crustáceos." } } },
  { id: "e10", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer frisst mehr Kilo Futter am Tag?", a: ["Panda", "Tiger"], x: "Ein Panda frisst täglich 12 bis 38 kg Bambus, weil der kaum Energie liefert. Ein Tiger kommt im Schnitt mit 5 bis 7 kg Fleisch am Tag aus." }, en: { q: "Who eats more kilos of food a day?", a: ["Panda", "Tiger"], x: "A panda eats 12 to 38 kg of bamboo a day because it provides so little energy. A tiger gets by on 5 to 7 kg of meat a day on average." }, fr: { q: "Qui mange le plus de kilos par jour ?", a: ["Panda", "Tigre"], x: "Un panda mange 12 à 38 kg de bambou par jour, car il apporte très peu d’énergie. Un tigre se contente en moyenne de 5 à 7 kg de viande par jour." }, es: { q: "¿Quién come más kilos al día?", a: ["Panda", "Tigre"], x: "Un panda come de 12 a 38 kg de bambú al día, porque aporta muy poca energía. Un tigre se arregla con 5 a 7 kg de carne al día de media." } } },
  { id: "e12", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer riecht mit der Zunge?", a: ["Eidechse", "Frosch"], x: "Eidechsen züngeln, um Duftteilchen aufzunehmen, und bringen sie zu einem Riechorgan im Gaumen. Frösche fangen mit der Zunge nur Beute." }, en: { q: "Who smells with its tongue?", a: ["Lizard", "Frog"], x: "Lizards flick their tongue to pick up scent particles and carry them to a smell organ in the roof of the mouth. Frogs only use their tongue to catch prey." }, fr: { q: "Qui sent avec sa langue ?", a: ["Lézard", "Grenouille"], x: "Le lézard sort la langue pour capter des odeurs et les porte à un organe olfactif dans le palais. La grenouille ne s’en sert que pour attraper ses proies." }, es: { q: "¿Quién huele con la lengua?", a: ["Lagartija", "Rana"], x: "Las lagartijas sacan la lengua para captar olores y los llevan a un órgano olfativo en el paladar. Las ranas solo la usan para cazar." } } },
  { id: "e13", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer atmet auch durch die Haut?", a: ["Frosch", "Eidechse"], x: "Frösche nehmen über ihre dünne, feuchte Haut Sauerstoff auf – im Winter am Teichgrund fast nur so. Eidechsen haben trockene Schuppenhaut." }, en: { q: "Who also breathes through its skin?", a: ["Frog", "Lizard"], x: "Frogs take in oxygen through their thin, moist skin – in winter at the bottom of a pond almost only this way. Lizards have dry, scaly skin." }, fr: { q: "Qui respire aussi par la peau ?", a: ["Grenouille", "Lézard"], x: "La grenouille absorbe de l’oxygène par sa peau fine et humide – en hiver, au fond de la mare, presque uniquement ainsi. Le lézard a une peau sèche à écailles." }, es: { q: "¿Quién respira también por la piel?", a: ["Rana", "Lagartija"], x: "Las ranas absorben oxígeno por su piel fina y húmeda; en invierno, en el fondo del estanque, casi solo así. Las lagartijas tienen piel seca con escamas." } } },
  { id: "e15", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer sieht ultraviolettes Licht?", a: ["Braunbär", "Biene"], x: "Bienen sehen UV-Licht. Viele Blüten haben UV-Muster, die wie Landebahnen zum Nektar führen – für uns unsichtbar." }, en: { q: "Who can see ultraviolet light?", a: ["Brown bear", "Bee"], x: "Bees see UV light. Many flowers have UV patterns that lead to the nectar like runways – invisible to us." }, fr: { q: "Qui voit la lumière ultraviolette ?", a: ["Ours brun", "Abeille"], x: "Les abeilles voient les UV. Beaucoup de fleurs ont des motifs UV qui mènent au nectar comme des pistes d’atterrissage – invisibles pour nous." }, es: { q: "¿Quién ve la luz ultravioleta?", a: ["Oso pardo", "Abeja"], x: "Las abejas ven la luz UV. Muchas flores tienen dibujos UV que llevan al néctar como pistas de aterrizaje, invisibles para nosotros." } } },
  { id: "e16", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer hat mehr Augen?", a: ["Biene", "Krabbe"], x: "Bienen haben zwei große Facettenaugen und drei kleine Punktaugen oben auf dem Kopf – zusammen fünf. Krabben haben zwei Stielaugen." }, en: { q: "Who has more eyes?", a: ["Bee", "Crab"], x: "Bees have two large compound eyes and three small simple eyes on top of the head – five in total. Crabs have two eyes on stalks." }, fr: { q: "Qui a le plus d’yeux ?", a: ["Abeille", "Crabe"], x: "L’abeille a deux grands yeux à facettes et trois petits ocelles sur le dessus de la tête – cinq en tout. Le crabe a deux yeux pédonculés." }, es: { q: "¿Quién tiene más ojos?", a: ["Abeja", "Cangrejo"], x: "Las abejas tienen dos grandes ojos compuestos y tres ojillos simples en lo alto de la cabeza: cinco en total. Los cangrejos tienen dos ojos con pedúnculo." } } },
  { id: "e17", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer legt mehr Eier auf einmal?", a: ["Krake", "Schildkröte"], x: "Ein Krakenweibchen legt bis zu Hunderttausende Eier und bewacht sie wochenlang, ohne zu fressen. Meeresschildkröten legen etwa 100 Eier pro Gelege." }, en: { q: "Who lays more eggs at once?", a: ["Octopus", "Turtle"], x: "A female octopus lays up to hundreds of thousands of eggs and guards them for weeks without eating. Sea turtles lay about 100 eggs per clutch." }, fr: { q: "Qui pond le plus d’œufs en une fois ?", a: ["Pieuvre", "Tortue"], x: "Une pieuvre femelle pond jusqu’à des centaines de milliers d’œufs et les garde des semaines sans manger. Les tortues marines pondent environ 100 œufs par ponte." }, es: { q: "¿Quién pone más huevos de una vez?", a: ["Pulpo", "Tortuga"], x: "Una hembra de pulpo pone hasta cientos de miles de huevos y los vigila durante semanas sin comer. Las tortugas marinas ponen unos 100 huevos por puesta." } } },
  { id: "e18", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer wird älter?", a: ["Grönlandhai", "Papagei"], x: "Grönlandhaie können mehrere hundert Jahre alt werden – sie sind die ältesten bekannten Wirbeltiere. Große Papageien schaffen 60 bis 80 Jahre." }, en: { q: "Who lives longer?", a: ["Greenland shark", "Parrot"], x: "Greenland sharks can live several hundred years – the oldest known vertebrates. Large parrots reach 60 to 80 years." }, fr: { q: "Qui vit le plus longtemps ?", a: ["Requin du Groenland", "Perroquet"], x: "Le requin du Groenland peut vivre plusieurs centaines d’années – c’est le plus vieux vertébré connu. Les grands perroquets atteignent 60 à 80 ans." }, es: { q: "¿Quién vive más?", a: ["Tiburón de Groenlandia", "Loro"], x: "El tiburón de Groenlandia puede vivir varios cientos de años: es el vertebrado más longevo conocido. Los loros grandes llegan a 60 u 80 años." } } },
  { id: "e19", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wen gab es zuerst auf der Erde?", a: ["Hai", "Schildkröte"], x: "Haie gibt es seit über 400 Millionen Jahren – länger als Bäume. Schildkröten erst seit etwa 220 Millionen Jahren." }, en: { q: "Who was on Earth first?", a: ["Shark", "Turtle"], x: "Sharks have existed for over 400 million years – longer than trees. Turtles only for about 220 million years." }, fr: { q: "Qui était sur Terre en premier ?", a: ["Requin", "Tortue"], x: "Les requins existent depuis plus de 400 millions d’années – plus longtemps que les arbres. Les tortues seulement depuis environ 220 millions d’années." }, es: { q: "¿Quién llegó antes a la Tierra?", a: ["Tiburón", "Tortuga"], x: "Los tiburones existen desde hace más de 400 millones de años, más que los árboles. Las tortugas, solo desde hace unos 220 millones." } } },
  { id: "e21", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer schwimmt schneller?", a: ["Fischotter", "Pinguin"], x: "Eselspinguine erreichen unter Wasser rund 35 km/h – schneller als jeder andere Vogel im Wasser. Ein Fischotter schwimmt gut 10 km/h." }, en: { q: "Who swims faster?", a: ["Otter", "Penguin"], x: "Gentoo penguins reach about 35 km/h underwater – faster than any other bird in water. An otter swims a little over 10 km/h." }, fr: { q: "Qui nage le plus vite ?", a: ["Loutre", "Manchot"], x: "Le manchot papou atteint environ 35 km/h sous l’eau – plus vite que tout autre oiseau dans l’eau. La loutre nage à un peu plus de 10 km/h." }, es: { q: "¿Quién nada más rápido?", a: ["Nutria", "Pingüino"], x: "El pingüino papúa alcanza unos 35 km/h bajo el agua, más que cualquier otra ave en el agua. La nutria nada a algo más de 10 km/h." } } },
  { id: "e22", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer übersteht es, fast ganz einzufrieren?", a: ["Igel", "Frosch"], x: "Der nordamerikanische Waldfrosch friert im Winter zu zwei Dritteln ein, Herz und Atmung stehen still. Zucker in den Zellen schützt ihn, im Frühling taut er auf. Der Igel braucht ein frostfreies Nest." }, en: { q: "Who can survive being almost frozen solid?", a: ["Hedgehog", "Frog"], x: "The North American wood frog freezes two-thirds solid in winter; its heart and breathing stop. Sugar in its cells protects it, and it thaws in spring. A hedgehog needs a frost-free nest." }, fr: { q: "Qui survit en gelant presque entièrement ?", a: ["Hérisson", "Grenouille"], x: "La grenouille des bois d’Amérique du Nord gèle aux deux tiers en hiver : son cœur et sa respiration s’arrêtent. Du sucre protège ses cellules et elle dégèle au printemps. Le hérisson a besoin d’un nid hors gel." }, es: { q: "¿Quién sobrevive a congelarse casi por completo?", a: ["Erizo", "Rana"], x: "La rana de bosque norteamericana se congela en dos tercios en invierno: su corazón y su respiración se detienen. El azúcar protege sus células y en primavera se descongela. El erizo necesita un nido sin heladas." } } },
  { id: "e23", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer stammt von den Dinosauriern ab?", a: ["Eidechse", "Papagei"], x: "Vögel sind die heute lebenden Dinosaurier. Eidechsen sehen urzeitlich aus, sind aber nur entfernte Verwandte." }, en: { q: "Who descends from dinosaurs?", a: ["Lizard", "Parrot"], x: "Birds are the dinosaurs living today. Lizards look prehistoric but are only distant relatives." }, fr: { q: "Qui descend des dinosaures ?", a: ["Lézard", "Perroquet"], x: "Les oiseaux sont les dinosaures d’aujourd’hui. Les lézards ont l’air préhistoriques mais ne sont que des cousins éloignés." }, es: { q: "¿Quién desciende de los dinosaurios?", a: ["Lagartija", "Loro"], x: "Las aves son los dinosaurios que viven hoy. Las lagartijas parecen prehistóricas, pero solo son parientes lejanas." } } },
  { id: "e25", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer ist an Land schneller?", a: ["Tiger", "Panda"], x: "Tiger sprinten kurz 50 bis 65 km/h. Pandas schaffen im Notfall etwa 30 km/h." }, en: { q: "Who is faster on land?", a: ["Tiger", "Panda"], x: "Tigers sprint at 50 to 65 km/h for short distances. Pandas manage about 30 km/h when they have to." }, fr: { q: "Qui est le plus rapide sur terre ?", a: ["Tigre", "Panda"], x: "Le tigre sprinte à 50 à 65 km/h sur de courtes distances. Le panda atteint environ 30 km/h en cas d’urgence." }, es: { q: "¿Quién es más rápido en tierra?", a: ["Tigre", "Panda"], x: "El tigre esprinta a 50 o 65 km/h en distancias cortas. El panda llega a unos 30 km/h si hace falta." } } },
  { id: "e26", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer trägt seine Eier im Maul, bis die Jungen schlüpfen?", a: ["Maulbrüter-Buntbarsch", "Karpfen"], x: "Bei vielen Buntbarschen nimmt ein Elternteil die Eier ins Maul und frisst so lange nichts. Auch die Jungen flüchten bei Gefahr noch zurück ins Maul. Karpfen legen ihre Eier einfach an Pflanzen ab." }, en: { q: "Who carries its eggs in its mouth until the young hatch?", a: ["Mouthbrooding cichlid", "Carp"], x: "In many cichlids one parent takes the eggs into its mouth and eats nothing all that time. Even the young flee back into the mouth when there’s danger. Carp simply lay their eggs on plants." }, fr: { q: "Qui garde ses œufs dans la bouche jusqu’à l’éclosion ?", a: ["Cichlidé incubateur buccal", "Carpe"], x: "Chez beaucoup de cichlidés, un parent garde les œufs dans la bouche sans rien manger. Même les petits s’y réfugient en cas de danger. La carpe pond simplement sur les plantes." }, es: { q: "¿Quién lleva sus huevos en la boca hasta que nacen las crías?", a: ["Cíclido incubador bucal", "Carpa"], x: "En muchos cíclidos, uno de los padres guarda los huevos en la boca sin comer nada. Las crías incluso vuelven a la boca si hay peligro. La carpa simplemente pone sus huevos en las plantas." } } },
  { id: "e30", lvl: 3, type: "duel", right: 1, t: { de: { q: "Bei wem steckt der Großteil der Nervenzellen in den Armen?", a: ["Papagei", "Krake"], x: "Rund zwei Drittel der Nervenzellen eines Kraken sitzen in seinen Armen. Jeder Arm kann so tasten, schmecken und greifen, fast wie mit eigenem Kopf." }, en: { q: "Who has most of its nerve cells in its arms?", a: ["Parrot", "Octopus"], x: "About two-thirds of an octopus’s nerve cells are in its arms. Each arm can feel, taste and grab almost as if it had a mind of its own." }, fr: { q: "Qui a la plupart de ses neurones dans les bras ?", a: ["Perroquet", "Pieuvre"], x: "Environ deux tiers des neurones de la pieuvre se trouvent dans ses bras. Chaque bras peut toucher, goûter et saisir presque comme s’il avait sa propre tête." }, es: { q: "¿Quién tiene la mayoría de sus neuronas en los brazos?", a: ["Loro", "Pulpo"], x: "Unos dos tercios de las neuronas del pulpo están en sus brazos. Cada brazo puede tocar, saborear y agarrar casi como si tuviera cabeza propia." } } },
  { id: "e31", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer ist schwerer?", a: ["Giraffe", "Braunbär"], x: "Eine ausgewachsene Giraffe wiegt 800 bis 1.200 kg. Selbst sehr große Braunbären bringen meist deutlich weniger auf die Waage." }, en: { q: "Who is heavier?", a: ["Giraffe", "Brown bear"], x: "An adult giraffe weighs 800 to 1,200 kg. Even very big brown bears usually weigh a lot less." }, fr: { q: "Qui est le plus lourd ?", a: ["Girafe", "Ours brun"], x: "Une girafe adulte pèse 800 à 1 200 kg. Même les très grands ours bruns pèsent en général bien moins." }, es: { q: "¿Quién pesa más?", a: ["Jirafa", "Oso pardo"], x: "Una jirafa adulta pesa de 800 a 1.200 kg. Incluso los osos pardos muy grandes suelen pesar bastante menos." } } },
  { id: "e32", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer lebt in einem Volk mit Tausenden Geschwistern?", a: ["Marienkäfer", "Biene"], x: "Ein Honigbienenvolk hat im Sommer 30.000 bis 50.000 Bienen, fast alle Töchter der einen Königin. Marienkäfer leben allein." }, en: { q: "Who lives in a colony with thousands of siblings?", a: ["Ladybird", "Bee"], x: "In summer, a honeybee colony has 30,000 to 50,000 bees, almost all daughters of the one queen. Ladybirds live alone." }, fr: { q: "Qui vit dans une colonie avec des milliers de frères et sœurs ?", a: ["Coccinelle", "Abeille"], x: "En été, une colonie d’abeilles compte 30 000 à 50 000 abeilles, presque toutes filles de l’unique reine. La coccinelle vit seule." }, es: { q: "¿Quién vive en una colonia con miles de hermanas?", a: ["Mariquita", "Abeja"], x: "En verano, una colmena tiene de 30.000 a 50.000 abejas, casi todas hijas de la única reina. Las mariquitas viven solas." } } },
  { id: "e33", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wessen Herz schlägt schneller?", a: ["Braunbär", "Igel"], x: "Kleine Tiere haben ein schnelles Herz: Beim wachen Igel schlägt es rund 200-mal pro Minute, beim Bären nur etwa 40- bis 50-mal." }, en: { q: "Whose heart beats faster?", a: ["Brown bear", "Hedgehog"], x: "Small animals have fast hearts: an awake hedgehog’s heart beats about 200 times a minute, a bear’s only about 40 to 50 times." }, fr: { q: "Quel cœur bat le plus vite ?", a: ["Ours brun", "Hérisson"], x: "Les petits animaux ont un cœur rapide : celui du hérisson éveillé bat environ 200 fois par minute, celui de l’ours seulement 40 à 50 fois." }, es: { q: "¿Qué corazón late más rápido?", a: ["Oso pardo", "Erizo"], x: "Los animales pequeños tienen el corazón rápido: el del erizo despierto late unas 200 veces por minuto; el del oso, solo unas 40 o 50." } } },
  { id: "e34", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer sieht in der Dämmerung besser?", a: ["Eule", "Adler"], x: "Eulenaugen haben besonders viele Stäbchen – Sinneszellen für schwaches Licht. Adler sehen dafür am Tag schärfer." }, en: { q: "Who sees better at dusk?", a: ["Owl", "Eagle"], x: "Owl eyes have a great many rods – sensory cells for dim light. Eagles, on the other hand, see more sharply by day." }, fr: { q: "Qui voit le mieux au crépuscule ?", a: ["Chouette", "Aigle"], x: "Les yeux de la chouette ont énormément de bâtonnets – des cellules pour la faible lumière. L’aigle, lui, voit plus net le jour." }, es: { q: "¿Quién ve mejor al anochecer?", a: ["Búho", "Águila"], x: "Los ojos del búho tienen muchísimos bastones, células para la luz tenue. El águila, en cambio, ve con más nitidez de día." } } },
  { id: "e35", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer wird älter?", a: ["Schildkröte", "Braunbär"], x: "Viele Landschildkröten werden 50 bis über 100 Jahre alt. Braunbären erreichen in freier Natur meist 20 bis 30 Jahre." }, en: { q: "Who lives longer?", a: ["Turtle", "Brown bear"], x: "Many tortoises live 50 to over 100 years. Brown bears in the wild usually reach 20 to 30 years." }, fr: { q: "Qui vit le plus longtemps ?", a: ["Tortue", "Ours brun"], x: "Beaucoup de tortues terrestres vivent de 50 à plus de 100 ans. L’ours brun atteint en général 20 à 30 ans dans la nature." }, es: { q: "¿Quién vive más?", a: ["Tortuga", "Oso pardo"], x: "Muchas tortugas terrestres viven de 50 a más de 100 años. Los osos pardos en libertad suelen llegar a 20 o 30 años." } } },
  { id: "e36", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer kann blitzschnell seine Farbe wechseln?", a: ["Papagei", "Krake"], x: "Kraken haben Tausende Farbzellen in der Haut, die sie in Sekundenbruchteilen öffnen und schließen – zum Tarnen und um Stimmung zu zeigen." }, en: { q: "Who can change colour in a flash?", a: ["Parrot", "Octopus"], x: "Octopuses have thousands of colour cells in their skin that they open and close in a fraction of a second – to hide and to show their mood." }, fr: { q: "Qui peut changer de couleur en un éclair ?", a: ["Perroquet", "Pieuvre"], x: "La pieuvre a des milliers de cellules colorées dans la peau qu’elle ouvre et ferme en une fraction de seconde – pour se camoufler et montrer son humeur." }, es: { q: "¿Quién cambia de color en un instante?", a: ["Loro", "Pulpo"], x: "El pulpo tiene miles de células de color en la piel que abre y cierra en una fracción de segundo, para camuflarse y mostrar su humor." } } },
  { id: "b01", lvl: 2, type: "text", right: 2, t: { de: { q: "Wie überwintert der Zitronenfalter?", a: ["Als Raupe im Boden", "Als Puppe an einem Zweig", "Als Falter frei im Gebüsch", "Er zieht in den Süden"], x: "Er überwintert ungeschützt zwischen Blättern. Ein körpereigenes Frostschutzmittel bewahrt ihn vor dem Erfrieren." }, en: { q: "How does the brimstone butterfly survive winter?", a: ["As a caterpillar in the soil", "As a pupa on a twig", "As an adult, unsheltered in shrubs", "It migrates south"], x: "It overwinters unprotected among leaves. A natural antifreeze in its body keeps it from freezing." }, fr: { q: "Comment le papillon Citron passe-t-il l'hiver ?", a: ["En chenille dans le sol", "En chrysalide sur une branche", "En papillon, à découvert", "Il migre vers le sud"], x: "Il hiverne sans abri parmi les feuilles. Un antigel naturel dans son corps l'empêche de geler." }, es: { q: "¿Cómo pasa el invierno la mariposa limonera?", a: ["Como oruga en el suelo", "Como crisálida en una rama", "Como adulta, al aire libre", "Migra hacia el sur"], x: "Hiberna sin refugio entre las hojas. Un anticongelante natural en su cuerpo evita que se congele." } } },
  { id: "b02", lvl: 1, type: "text", right: 1, t: { de: { q: "Wie lange leben Maikäfer-Larven (Engerlinge) im Boden?", a: ["Etwa 2 Wochen", "Mehrere Jahre", "Nur einen Sommer", "Rund 20 Jahre"], x: "Je nach Klima fressen Engerlinge 3 bis 5 Jahre lang Wurzeln. Der fertige Käfer lebt dann nur wenige Wochen." }, en: { q: "How long do cockchafer larvae (grubs) live in the soil?", a: ["About 2 weeks", "Several years", "Just one summer", "Around 20 years"], x: "Depending on climate, grubs feed on roots for 3 to 5 years. The adult beetle then lives only a few weeks." }, fr: { q: "Combien de temps les larves de hanneton (vers blancs) vivent-elles dans le sol ?", a: ["Environ 2 semaines", "Plusieurs années", "Un seul été", "Environ 20 ans"], x: "Selon le climat, les vers blancs mangent des racines pendant 3 à 5 ans. L'adulte ne vit ensuite que quelques semaines." }, es: { q: "¿Cuánto tiempo viven en el suelo las larvas del escarabajo de mayo?", a: ["Unas 2 semanas", "Varios años", "Solo un verano", "Unos 20 años"], x: "Según el clima, las larvas comen raíces durante 3 a 5 años. El escarabajo adulto vive después solo unas semanas." } } },
  { id: "b03", lvl: 1, type: "tf", right: 1, t: { de: { q: "Zecken lassen sich meist von Bäumen auf Menschen und Tiere fallen.", a: ["Wahr", "Falsch"], x: "Ein Mythos: Zecken lauern meist in Gras und Büschen bis etwa 1 m Höhe und werden im Vorbeigehen abgestreift." }, en: { q: "Ticks usually drop onto people and animals from trees.", a: ["True", "False"], x: "A myth: ticks usually wait in grass and shrubs up to about 1 m high and get brushed off as you pass." }, fr: { q: "Les tiques se laissent généralement tomber des arbres sur les humains et les animaux.", a: ["Vrai", "Faux"], x: "Un mythe : les tiques attendent surtout dans l'herbe et les buissons jusqu'à 1 m environ et s'accrochent au passage." }, es: { q: "Las garrapatas suelen dejarse caer desde los árboles sobre personas y animales.", a: ["Verdadero", "Falso"], x: "Es un mito: suelen esperar en la hierba y los arbustos hasta 1 m de altura y se enganchan al pasar." } } },
  { id: "b04", lvl: 1, type: "text", right: 3, t: { de: { q: "Welches dieser Tiere ist KEIN Insekt?", a: ["Ohrwurm", "Silberfischchen", "Wasserläufer", "Kellerassel"], x: "Asseln sind Krebstiere, die an Land leben. Sie haben 14 Beine und brauchen feuchte Verstecke." }, en: { q: "Which of these animals is NOT an insect?", a: ["Earwig", "Silverfish", "Pond skater", "Woodlouse"], x: "Woodlice are crustaceans that live on land. They have 14 legs and need damp hiding places." }, fr: { q: "Lequel de ces animaux n'est PAS un insecte ?", a: ["Perce-oreille", "Poisson d'argent", "Gerris", "Cloporte"], x: "Les cloportes sont des crustacés terrestres. Ils ont 14 pattes et ont besoin de cachettes humides." }, es: { q: "¿Cuál de estos animales NO es un insecto?", a: ["Tijereta", "Pececillo de plata", "Zapatero (Gerris)", "Cochinilla de humedad"], x: "Las cochinillas de humedad son crustáceos terrestres. Tienen 14 patas y necesitan escondites húmedos." } } },
  { id: "b05", lvl: 1, type: "text", right: 0, t: { de: { q: "Was ist eine Blindschleiche?", a: ["Eine Eidechse ohne Beine", "Eine kleine Schlange", "Ein großer Regenwurm", "Ein Lurch wie der Molch"], x: "Sie ist eine beinlose Echse: Sie hat Augenlider, kann den Schwanz abwerfen – und blind ist sie auch nicht." }, en: { q: "What is a slow worm?", a: ["A legless lizard", "A small snake", "A large earthworm", "An amphibian like a newt"], x: "It is a legless lizard: it has eyelids and can shed its tail, just like other lizards." }, fr: { q: "Qu'est-ce qu'un orvet ?", a: ["Un lézard sans pattes", "Un petit serpent", "Un gros ver de terre", "Un amphibien comme le triton"], x: "C'est un lézard sans pattes : il a des paupières et peut perdre sa queue, comme les autres lézards." }, es: { q: "¿Qué es un lución?", a: ["Un lagarto sin patas", "Una pequeña serpiente", "Una lombriz grande", "Un anfibio como el tritón"], x: "Es un lagarto sin patas: tiene párpados y puede soltar la cola, como otros lagartos." } } },
  { id: "b06", lvl: 2, type: "text", right: 3, t: { de: { q: "Wovon ernähren sich erwachsene Eintagsfliegen?", a: ["Von Blütennektar", "Von kleinen Mücken", "Von Algen", "Von gar nichts"], x: "Ihre Mundwerkzeuge sind verkümmert. Erwachsene leben nur Stunden bis wenige Tage – allein zur Fortpflanzung." }, en: { q: "What do adult mayflies eat?", a: ["Flower nectar", "Small midges", "Algae", "Nothing at all"], x: "Their mouthparts are non-functional. Adults live only hours to a few days – just to reproduce." }, fr: { q: "De quoi se nourrissent les éphémères adultes ?", a: ["De nectar", "De petits moucherons", "D'algues", "De rien du tout"], x: "Leurs pièces buccales sont atrophiées. Les adultes vivent de quelques heures à quelques jours, juste pour se reproduire." }, es: { q: "¿De qué se alimentan las efímeras adultas?", a: ["De néctar", "De mosquitos pequeños", "De algas", "De nada"], x: "Sus piezas bucales están atrofiadas. Los adultos viven de horas a pocos días, solo para reproducirse." } } },
  { id: "b07", lvl: 1, type: "tf", right: 0, t: { de: { q: "Nur die Weibchen der Stechmücken stechen.", a: ["Wahr", "Falsch"], x: "Sie brauchen Blut, damit sich ihre Eier entwickeln. Männchen saugen nur Pflanzensäfte und Nektar." }, en: { q: "Only female mosquitoes bite.", a: ["True", "False"], x: "They need blood for their eggs to develop. Males only feed on plant juices and nectar." }, fr: { q: "Seules les femelles moustiques piquent.", a: ["Vrai", "Faux"], x: "Elles ont besoin de sang pour que leurs œufs se développent. Les mâles se nourrissent de nectar et de sève." }, es: { q: "Solo las hembras de mosquito pican.", a: ["Verdadero", "Falso"], x: "Necesitan sangre para que se desarrollen sus huevos. Los machos solo toman néctar y jugos vegetales." } } },
  { id: "b08", lvl: 2, type: "text", right: 0, t: { de: { q: "Wo nisten die meisten Wildbienenarten in Deutschland?", a: ["Im Erdboden", "In hohlen Pflanzenstängeln", "In Bohrlöchern im Totholz", "In leeren Schneckenhäusern"], x: "Mehr als die Hälfte nistet im Boden. Offene, sonnige Erdstellen im Garten helfen oft mehr als ein Insektenhotel." }, en: { q: "Where do most wild bee species in Germany nest?", a: ["In the ground", "In hollow plant stems", "In holes in dead wood", "In empty snail shells"], x: "More than half nest in the ground. Bare, sunny patches of soil often help more than a bee hotel." }, fr: { q: "Où nichent la plupart des espèces d'abeilles sauvages en Allemagne ?", a: ["Dans le sol", "Dans des tiges creuses", "Dans des trous de bois mort", "Dans des coquilles d'escargot"], x: "Plus de la moitié nichent dans le sol. Des zones de terre nue et ensoleillée aident souvent plus qu'un hôtel à insectes." }, es: { q: "¿Dónde anidan la mayoría de las abejas silvestres en Alemania?", a: ["En el suelo", "En tallos huecos", "En agujeros de madera muerta", "En conchas de caracol vacías"], x: "Más de la mitad anida en el suelo. Zonas de tierra desnuda y soleada ayudan a menudo más que un hotel de insectos." } } },
  { id: "b09", lvl: 2, type: "text", right: 2, t: { de: { q: "Wie pflanzt sich der Feuersalamander bei uns fort?", a: ["Er legt Laichballen in Teiche", "Er vergräbt Eier in feuchter Erde", "Das Weibchen setzt Larven in Bächen ab", "Das Männchen trägt die Eier"], x: "Die Eier entwickeln sich im Mutterleib. Im Frühjahr setzt das Weibchen Larven mit Kiemen in kühle Bäche." }, en: { q: "How does the fire salamander reproduce in Central Europe?", a: ["It lays egg clumps in ponds", "It buries eggs in damp soil", "Females release larvae into streams", "The male carries the eggs"], x: "The eggs develop inside the mother. In spring she releases larvae with gills into cool streams." }, fr: { q: "Comment la salamandre tachetée se reproduit-elle chez nous ?", a: ["Elle pond des amas d'œufs en mare", "Elle enterre ses œufs", "La femelle dépose des larves en ruisseau", "Le mâle porte les œufs"], x: "Les œufs se développent dans le corps de la mère. Au printemps, elle dépose des larves à branchies dans des ruisseaux frais." }, es: { q: "¿Cómo se reproduce la salamandra común en Centroeuropa?", a: ["Pone masas de huevos en charcas", "Entierra huevos en tierra húmeda", "La hembra suelta larvas en arroyos", "El macho lleva los huevos"], x: "Los huevos se desarrollan dentro de la madre. En primavera suelta larvas con branquias en arroyos frescos." } } },
  { id: "b10", lvl: 3, type: "text", right: 3, t: { de: { q: "Wie lange ist ein Alpensalamander-Weibchen trächtig?", a: ["Etwa 3 Wochen", "Etwa 3 Monate", "Genau 1 Jahr", "2 bis 4 Jahre"], x: "Je nach Höhenlage 2 bis 4 Jahre. Die Jungen kommen fertig verwandelt zur Welt – ganz ohne Wasser." }, en: { q: "How long is a female Alpine salamander pregnant?", a: ["About 3 weeks", "About 3 months", "Exactly 1 year", "2 to 4 years"], x: "Depending on altitude, 2 to 4 years. The young are born fully developed – no water needed." }, fr: { q: "Combien de temps dure la gestation de la salamandre noire (alpine) ?", a: ["Environ 3 semaines", "Environ 3 mois", "Exactement 1 an", "De 2 à 4 ans"], x: "Selon l'altitude, 2 à 4 ans. Les petits naissent entièrement formés, sans passer par l'eau." }, es: { q: "¿Cuánto dura la gestación de la salamandra alpina?", a: ["Unas 3 semanas", "Unos 3 meses", "Exactamente 1 año", "De 2 a 4 años"], x: "Según la altitud, de 2 a 4 años. Las crías nacen ya transformadas, sin necesidad de agua." } } },
  { id: "b11", lvl: 1, type: "tf", right: 0, t: { de: { q: "Erdkröten wandern im Frühjahr meist zu dem Gewässer zurück, in dem sie selbst aufgewachsen sind.", a: ["Wahr", "Falsch"], x: "Dabei überqueren sie oft Straßen. Krötenzäune und Amphibientunnel retten jedes Jahr viele Tiere." }, en: { q: "In spring, common toads usually return to the pond where they grew up.", a: ["True", "False"], x: "On the way they often cross roads. Toad fences and tunnels save many animals every year." }, fr: { q: "Au printemps, les crapauds communs retournent généralement à la mare où ils ont grandi.", a: ["Vrai", "Faux"], x: "En chemin, ils traversent souvent des routes. Barrières et crapauducs sauvent beaucoup d'animaux chaque année." }, es: { q: "En primavera, los sapos comunes suelen volver a la charca donde crecieron.", a: ["Verdadero", "Falso"], x: "En el camino cruzan a menudo carreteras. Vallas y pasos para anfibios salvan a muchos cada año." } } },
  { id: "b12", lvl: 1, type: "text", right: 1, t: { de: { q: "Was sind die geringelten Sandhäufchen im Wattenmeer?", a: ["Eier von Strandkrabben", "Kot des Wattwurms", "Nester von Muscheln", "Bauten von Sandflöhen"], x: "Der Wattwurm frisst Sand, verdaut die Kleinstlebewesen darin und scheidet den Sand als Kringel wieder aus." }, en: { q: "What are the coiled little sand piles on the Wadden Sea mudflats?", a: ["Shore crab eggs", "Lugworm droppings", "Mussel nests", "Sand hopper burrows"], x: "The lugworm swallows sand, digests the tiny organisms in it and pushes the sand back out as coils." }, fr: { q: "Que sont les petits tortillons de sable sur les vasières de la mer des Wadden ?", a: ["Des œufs de crabe", "Les excréments de l'arénicole", "Des nids de moules", "Des terriers de puces de mer"], x: "L'arénicole avale du sable, digère les petits organismes qu'il contient et rejette le sable en tortillons." }, es: { q: "¿Qué son los montoncitos de arena enrollada en las marismas del mar de Wadden?", a: ["Huevos de cangrejo", "Excrementos del gusano Arenicola", "Nidos de mejillones", "Madrigueras de pulgas de mar"], x: "El gusano Arenicola traga arena, digiere los diminutos organismos que contiene y expulsa la arena en forma de rollitos." } } },
  { id: "b13", lvl: 2, type: "text", right: 0, t: { de: { q: "Wo legt die Gelbbauchunke am liebsten ihren Laich ab?", a: ["In flachen Pfützen und Fahrspuren", "In tiefen Seen", "In schnellen Bergbächen", "Im Brackwasser der Küste"], x: "Sie nutzt kleine, sonnige Tümpel – sogar wassergefüllte Reifenspuren. Dort gibt es kaum Fische oder andere Fressfeinde." }, en: { q: "Where does the yellow-bellied toad prefer to spawn?", a: ["In shallow puddles and ruts", "In deep lakes", "In fast mountain streams", "In brackish coastal water"], x: "It uses small, sunny pools – even water-filled tyre ruts. There are hardly any fish or other predators there." }, fr: { q: "Où le sonneur à ventre jaune pond-il de préférence ?", a: ["Dans des flaques et ornières", "Dans des lacs profonds", "Dans des torrents de montagne", "Dans l'eau saumâtre côtière"], x: "Il utilise de petites mares ensoleillées, même des ornières pleines d'eau. On n'y trouve presque pas de poissons ni de prédateurs." }, es: { q: "¿Dónde prefiere desovar el sapillo de vientre amarillo?", a: ["En charcos y rodadas poco hondos", "En lagos profundos", "En torrentes de montaña", "En aguas salobres costeras"], x: "Usa charcas pequeñas y soleadas, incluso rodadas de neumáticos con agua. Allí casi no hay peces ni depredadores." } } },
  { id: "b14", lvl: 3, type: "tf", right: 0, t: { de: { q: "In Deutschland leben zwei heimische Giftschlangenarten.", a: ["Wahr", "Falsch"], x: "Die Kreuzotter und die seltene Aspisviper, die bei uns nur im Südschwarzwald vorkommt." }, en: { q: "Germany has two native species of venomous snake.", a: ["True", "False"], x: "The common adder and the rare asp viper, which in Germany is found only in the southern Black Forest." }, fr: { q: "L'Allemagne compte deux espèces indigènes de serpents venimeux.", a: ["Vrai", "Faux"], x: "La vipère péliade et la rare vipère aspic, qui en Allemagne ne vit que dans le sud de la Forêt-Noire." }, es: { q: "En Alemania viven dos especies autóctonas de serpientes venenosas.", a: ["Verdadero", "Falso"], x: "La víbora común europea y la rara víbora áspid, que en Alemania solo vive en el sur de la Selva Negra." } } },
  { id: "b15", lvl: 1, type: "text", right: 3, t: { de: { q: "Woran erkennt man eine Ringelnatter meist?", a: ["Ein Zickzackband auf dem Rücken", "Eine Rassel am Schwanz", "Senkrechte Schlitzpupillen", "Gelbe Halbmondflecken am Hinterkopf"], x: "Die ungiftige Ringelnatter hat runde Pupillen und schwimmt gern. Bei Gefahr stellt sie sich oft tot." }, en: { q: "How can you usually recognise a grass snake?", a: ["A zigzag band on its back", "A rattle on its tail", "Vertical slit pupils", "Yellow crescents behind the head"], x: "The harmless grass snake has round pupils and loves to swim. When threatened, it often plays dead." }, fr: { q: "À quoi reconnaît-on généralement la couleuvre à collier ?", a: ["Une bande en zigzag sur le dos", "Une crécelle au bout de la queue", "Des pupilles verticales en fente", "Des croissants jaunes sur la nuque"], x: "Inoffensive, elle a des pupilles rondes et nage volontiers. En cas de danger, elle fait souvent la morte." }, es: { q: "¿Cómo se reconoce normalmente una culebra de collar?", a: ["Una banda en zigzag en el lomo", "Un cascabel en la cola", "Pupilas verticales en rendija", "Medias lunas amarillas en la nuca"], x: "Esta culebra inofensiva tiene pupilas redondas y nada muy bien. Ante el peligro, a menudo se hace la muerta." } } },
  { id: "b16", lvl: 3, type: "text", right: 1, t: { de: { q: "Was ist beim nachgewachsenen Schwanz einer Eidechse anders?", a: ["Er hat doppelt so viele Wirbel", "Statt Wirbeln stützt ihn ein Knorpelstab", "Er ist immer länger als vorher", "Er enthält eine Giftdrüse"], x: "Der neue Schwanz hat keine Wirbelknochen mehr, nur einen Knorpelstab. Er ist meist kürzer und anders gefärbt." }, en: { q: "What is different about a lizard's regrown tail?", a: ["It has twice as many vertebrae", "A cartilage rod replaces the vertebrae", "It is always longer than before", "It contains a venom gland"], x: "The new tail has no vertebrae, only a rod of cartilage. It is usually shorter and coloured differently." }, fr: { q: "Qu'a de différent la queue repoussée d'un lézard ?", a: ["Elle a deux fois plus de vertèbres", "Un cartilage remplace les vertèbres", "Elle est toujours plus longue", "Elle contient une glande à venin"], x: "La nouvelle queue n'a plus de vertèbres, seulement une tige de cartilage. Elle est souvent plus courte et d'une autre couleur." }, es: { q: "¿Qué tiene de diferente la cola regenerada de una lagartija?", a: ["Tiene el doble de vértebras", "Un cartílago sustituye a las vértebras", "Siempre es más larga que antes", "Contiene una glándula de veneno"], x: "La nueva cola ya no tiene vértebras, solo una varilla de cartílago. Suele ser más corta y de otro color." } } },
  { id: "b17", lvl: 2, type: "text", right: 2, t: { de: { q: "Wie atmet die Wasserspinne, die fast nur unter Wasser lebt?", a: ["Mit Kiemen am Hinterleib", "Sie hält stundenlang die Luft an", "Aus einer selbst gebauten Luftglocke", "Über die Haut aus dem Wasser"], x: "Sie spinnt zwischen Wasserpflanzen ein Gespinst und füllt es mit Luftblasen von der Oberfläche – eine Taucherglocke." }, en: { q: "How does the water spider Argyroneta, which lives almost only underwater, breathe?", a: ["With gills on its abdomen", "It holds its breath for hours", "From an air bell it builds itself", "Through its skin, from the water"], x: "It spins a web between water plants and fills it with air bubbles from the surface – like a diving bell." }, fr: { q: "Comment respire l'argyronète, araignée qui vit presque toujours sous l'eau ?", a: ["Avec des branchies", "Elle retient son souffle des heures", "Dans une cloche d'air qu'elle construit", "Par la peau, dans l'eau"], x: "Elle tisse une toile entre les plantes aquatiques et la remplit de bulles d'air prises en surface : une cloche de plongée." }, es: { q: "¿Cómo respira la araña de agua, que vive casi siempre bajo el agua?", a: ["Con branquias en el abdomen", "Aguanta la respiración durante horas", "En una campana de aire que construye", "A través de la piel, del agua"], x: "Teje una tela entre plantas acuáticas y la llena de burbujas de aire de la superficie: una campana de buceo." } } },
  { id: "b18", lvl: 2, type: "tf", right: 0, t: { de: { q: "Der Gelbrandkäfer lebt im Wasser, kann aber auch fliegen.", a: ["Wahr", "Falsch"], x: "Nachts fliegt er oft zu neuen Gewässern. Beim Tauchen nimmt er einen Luftvorrat unter den Flügeldecken mit." }, en: { q: "The great diving beetle lives in water but can also fly.", a: ["True", "False"], x: "At night it often flies to new ponds. When diving, it carries an air supply under its wing cases." }, fr: { q: "Le dytique bordé vit dans l'eau mais peut aussi voler.", a: ["Vrai", "Faux"], x: "La nuit, il s'envole souvent vers de nouvelles mares. En plongée, il garde une réserve d'air sous ses élytres." }, es: { q: "El ditisco vive en el agua, pero también puede volar.", a: ["Verdadero", "Falso"], x: "De noche vuela a menudo a nuevas charcas. Al bucear lleva una reserva de aire bajo los élitros." } } },
  { id: "b19", lvl: 2, type: "text", right: 0, t: { de: { q: "Womit fängt eine Libellenlarve ihre Beute?", a: ["Mit einer ausklappbaren Fangmaske", "Mit einer klebrigen Zunge", "Mit einem Netz aus Seide", "Mit einem Giftstachel"], x: "Die Fangmaske ist eine umgebaute Unterlippe. Sie schnellt blitzschnell vor und packt Kaulquappen, Larven und Co." }, en: { q: "How does a dragonfly larva catch its prey?", a: ["With an extendable 'mask'", "With a sticky tongue", "With a silk net", "With a venomous sting"], x: "The mask is a modified lower lip. It shoots forward in a flash and grabs tadpoles, larvae and more." }, fr: { q: "Comment une larve de libellule attrape-t-elle ses proies ?", a: ["Avec un « masque » dépliable", "Avec une langue collante", "Avec un filet de soie", "Avec un dard venimeux"], x: "Le masque est une lèvre inférieure transformée. Il se détend comme l'éclair pour saisir têtards et larves." }, es: { q: "¿Cómo atrapa una larva de libélula a sus presas?", a: ["Con una «máscara» extensible", "Con una lengua pegajosa", "Con una red de seda", "Con un aguijón venenoso"], x: "La máscara es un labio inferior modificado. Se dispara en un instante y atrapa renacuajos, larvas y más." } } },
  { id: "b20", lvl: 3, type: "tf", right: 1, t: { de: { q: "Libellen durchlaufen wie Schmetterlinge ein Puppenstadium.", a: ["Wahr", "Falsch"], x: "Libellen haben keine Puppe: Die Larve klettert aus dem Wasser, häutet sich ein letztes Mal, und die Libelle schlüpft." }, en: { q: "Like butterflies, dragonflies go through a pupal stage.", a: ["True", "False"], x: "Dragonflies have no pupa: the larva climbs out of the water, moults one last time and the adult emerges." }, fr: { q: "Comme les papillons, les libellules passent par un stade de chrysalide (pupe).", a: ["Vrai", "Faux"], x: "Les libellules n'ont pas de pupe : la larve sort de l'eau, mue une dernière fois et l'adulte en émerge." }, es: { q: "Como las mariposas, las libélulas pasan por una fase de pupa.", a: ["Verdadero", "Falso"], x: "Las libélulas no tienen pupa: la larva sale del agua, muda por última vez y emerge el adulto." } } },
  { id: "b21", lvl: 2, type: "text", right: 1, t: { de: { q: "Was stimmt beim Großen Leuchtkäfer (Glühwürmchen)?", a: ["Nur die Männchen leuchten", "Die Weibchen können nicht fliegen", "Sein Licht ist heiß wie eine Lampe", "Er ist eigentlich eine Fliege"], x: "Die flügellosen Weibchen leuchten im Gras, um fliegende Männchen anzulocken. Das Licht entsteht chemisch und ist kalt." }, en: { q: "What is true about the common glow-worm?", a: ["Only the males glow", "The females cannot fly", "Its light is hot like a lamp", "It is actually a fly"], x: "The wingless females glow in the grass to attract flying males. The light is made chemically and is cold." }, fr: { q: "Qu'est-ce qui est vrai pour le ver luisant ?", a: ["Seuls les mâles brillent", "Les femelles ne volent pas", "Sa lumière chauffe comme une lampe", "C'est en fait une mouche"], x: "Les femelles sans ailes brillent dans l'herbe pour attirer les mâles volants. Leur lumière est chimique et froide." }, es: { q: "¿Qué es cierto sobre la luciérnaga común europea?", a: ["Solo brillan los machos", "Las hembras no pueden volar", "Su luz quema como una lámpara", "En realidad es una mosca"], x: "Las hembras sin alas brillan en la hierba para atraer a los machos voladores. La luz es química y fría." } } },
  { id: "b22", lvl: 3, type: "text", right: 2, t: { de: { q: "Wovon ernähren sich die Larven des Großen Leuchtkäfers?", a: ["Von Blattläusen", "Von Nektar", "Von Schnecken", "Von morschem Holz"], x: "Sie jagen Schnecken, lähmen sie mit einem giftigen Biss und fressen sie. Sie brauchen feuchte, naturnahe Gärten." }, en: { q: "What do glow-worm larvae feed on?", a: ["Aphids", "Nectar", "Snails", "Rotting wood"], x: "They hunt snails, paralyse them with a venomous bite and eat them. They need damp, natural gardens." }, fr: { q: "De quoi se nourrissent les larves de ver luisant ?", a: ["De pucerons", "De nectar", "D'escargots", "De bois pourri"], x: "Elles chassent les escargots, les paralysent d'une morsure venimeuse puis les mangent. Elles aiment les jardins humides et naturels." }, es: { q: "¿De qué se alimentan las larvas de la luciérnaga común?", a: ["De pulgones", "De néctar", "De caracoles", "De madera podrida"], x: "Cazan caracoles, los paralizan con una mordedura venenosa y se los comen. Necesitan jardines húmedos y naturales." } } },
  { id: "b23", lvl: 1, type: "tf", right: 1, t: { de: { q: "An der Zahl der Punkte kann man das Alter eines Marienkäfers ablesen.", a: ["Wahr", "Falsch"], x: "Ein Mythos: Die Punktzahl hängt von der Art ab – etwa beim Siebenpunkt- oder Zweipunkt-Marienkäfer." }, en: { q: "You can tell a ladybird's age by counting its spots.", a: ["True", "False"], x: "A myth: the number of spots depends on the species, e.g. the seven-spot or two-spot ladybird." }, fr: { q: "On peut connaître l'âge d'une coccinelle en comptant ses points.", a: ["Vrai", "Faux"], x: "Un mythe : le nombre de points dépend de l'espèce, comme chez la coccinelle à sept points ou à deux points." }, es: { q: "Se puede saber la edad de una mariquita contando sus puntos.", a: ["Verdadero", "Falso"], x: "Es un mito: el número de puntos depende de la especie, como la mariquita de siete o de dos puntos." } } },
  { id: "b24", lvl: 1, type: "text", right: 3, t: { de: { q: "Wer überlebt bei Hummeln den Winter?", a: ["Das ganze Volk im Nest", "Nur die Arbeiterinnen", "Nur die Männchen", "Nur junge Königinnen"], x: "Das Volk stirbt im Herbst. Nur junge, begattete Königinnen überwintern im Boden und gründen im Frühjahr ein neues Volk." }, en: { q: "Which bumblebees survive the winter?", a: ["The whole colony in the nest", "Only the workers", "Only the males", "Only young queens"], x: "The colony dies in autumn. Only young, mated queens overwinter in the ground and start a new colony in spring." }, fr: { q: "Quels bourdons survivent à l'hiver ?", a: ["Toute la colonie au nid", "Seulement les ouvrières", "Seulement les mâles", "Seulement les jeunes reines"], x: "La colonie meurt en automne. Seules les jeunes reines fécondées hivernent dans le sol et fondent une colonie au printemps." }, es: { q: "¿Qué abejorros sobreviven al invierno?", a: ["Toda la colonia en el nido", "Solo las obreras", "Solo los machos", "Solo las reinas jóvenes"], x: "La colonia muere en otoño. Solo las reinas jóvenes fecundadas hibernan en el suelo y fundan una colonia en primavera." } } },
  { id: "b25", lvl: 2, type: "tf", right: 1, t: { de: { q: "Drei Hornissenstiche können einen gesunden Erwachsenen töten.", a: ["Wahr", "Falsch"], x: "Ein alter Mythos: Hornissengift ist nicht gefährlicher als Bienengift. Riskant sind Stiche vor allem für Allergiker." }, en: { q: "Three hornet stings can kill a healthy adult.", a: ["True", "False"], x: "An old myth: hornet venom is no more dangerous than bee venom. Stings are mainly risky for people with allergies." }, fr: { q: "Trois piqûres de frelon peuvent tuer un adulte en bonne santé.", a: ["Vrai", "Faux"], x: "Un vieux mythe : le venin du frelon n'est pas plus dangereux que celui de l'abeille. Le risque concerne surtout les allergiques." }, es: { q: "Tres picaduras de avispón pueden matar a un adulto sano.", a: ["Verdadero", "Falso"], x: "Es un viejo mito: su veneno no es más peligroso que el de la abeja. El riesgo es sobre todo para personas alérgicas." } } },
  { id: "b26", lvl: 2, type: "text", right: 0, t: { de: { q: "Warum beschützen manche Ameisen Blattläuse?", a: ["Sie bekommen süßen Honigtau", "Sie fressen deren Eier", "Die Läuse wärmen das Nest", "Die Läuse bauen Nestkammern"], x: "Blattläuse scheiden zuckerhaltigen Honigtau aus. Ameisen 'melken' sie und halten dafür Feinde wie Marienkäfer fern." }, en: { q: "Why do some ants protect aphids?", a: ["They get sweet honeydew", "They eat the aphids' eggs", "The aphids warm the nest", "The aphids build nest chambers"], x: "Aphids excrete sugary honeydew. Ants 'milk' them and in return keep enemies like ladybirds away." }, fr: { q: "Pourquoi certaines fourmis protègent-elles les pucerons ?", a: ["Elles obtiennent du miellat sucré", "Elles mangent leurs œufs", "Les pucerons chauffent le nid", "Les pucerons creusent le nid"], x: "Les pucerons rejettent un miellat sucré. Les fourmis les « traient » et éloignent en échange les coccinelles." }, es: { q: "¿Por qué algunas hormigas protegen a los pulgones?", a: ["Obtienen melaza dulce", "Se comen sus huevos", "Los pulgones calientan el nido", "Los pulgones excavan el nido"], x: "Los pulgones excretan una melaza azucarada. Las hormigas los «ordeñan» y a cambio alejan a enemigos como las mariquitas." } } },
  { id: "b27", lvl: 2, type: "tf", right: 1, t: { de: { q: "Molche verbringen das ganze Jahr im Wasser.", a: ["Wahr", "Falsch"], x: "Bergmolch, Teichmolch und Co. gehen meist nur zur Paarungszeit im Frühjahr ins Wasser und leben sonst an Land." }, en: { q: "Newts spend the whole year in the water.", a: ["True", "False"], x: "Alpine newts, smooth newts and co. mostly enter the water only to breed in spring and otherwise live on land." }, fr: { q: "Les tritons passent toute l'année dans l'eau.", a: ["Vrai", "Faux"], x: "Les tritons alpestres, ponctués et autres ne vont en général à l'eau qu'au printemps pour se reproduire et vivent sinon à terre." }, es: { q: "Los tritones pasan todo el año en el agua.", a: ["Verdadero", "Falso"], x: "El tritón alpino y otros suelen ir al agua solo para reproducirse en primavera; el resto del año viven en tierra." } } },
  { id: "b28", lvl: 1, type: "text", right: 0, t: { de: { q: "Auf welcher Pflanze fressen die Raupen des Tagpfauenauges?", a: ["Brennnessel", "Kohl", "Eiche", "Löwenzahn"], x: "Brennnesseln sind Kinderstube für Tagpfauenauge, Kleinen Fuchs und Admiral. Lass im Garten eine wilde Ecke stehen!" }, en: { q: "Which plant do peacock butterfly caterpillars feed on?", a: ["Stinging nettle", "Cabbage", "Oak", "Dandelion"], x: "Nettles are a nursery for the peacock, small tortoiseshell and red admiral. Leave a wild corner in your garden!" }, fr: { q: "De quelle plante se nourrissent les chenilles du paon-du-jour ?", a: ["Ortie", "Chou", "Chêne", "Pissenlit"], x: "Les orties sont la nurserie du paon-du-jour, de la petite tortue et du vulcain. Laissez un coin sauvage au jardin !" }, es: { q: "¿De qué planta se alimentan las orugas de la mariposa pavo real?", a: ["Ortiga", "Col", "Roble", "Diente de león"], x: "Las ortigas son la guardería de la pavo real, la ortiguera y la vanesa atalanta. ¡Deja un rincón salvaje en el jardín!" } } },
  { id: "b29", lvl: 3, type: "text", right: 2, t: { de: { q: "Woher stammen viele Distelfalter, die im Frühjahr bei uns auftauchen?", a: ["Aus Skandinavien", "Aus Sibirien", "Aus Nordafrika und Südeuropa", "Aus Nordamerika"], x: "Distelfalter wandern in mehreren Generationen von Afrika bis Nordeuropa – ein Staffellauf über Tausende Kilometer." }, en: { q: "Where do many painted ladies that appear in Central Europe in spring come from?", a: ["From Scandinavia", "From Siberia", "From North Africa and southern Europe", "From North America"], x: "Painted ladies migrate over several generations from Africa to northern Europe – a relay over thousands of kilometres." }, fr: { q: "D'où viennent beaucoup de belles-dames qui arrivent au printemps en Europe centrale ?", a: ["De Scandinavie", "De Sibérie", "D'Afrique du Nord et d'Europe du Sud", "D'Amérique du Nord"], x: "La belle-dame migre sur plusieurs générations de l'Afrique au nord de l'Europe : un relais de milliers de kilomètres." }, es: { q: "¿De dónde vienen muchas vanesas de los cardos que llegan en primavera a Centroeuropa?", a: ["De Escandinavia", "De Siberia", "Del norte de África y el sur de Europa", "De Norteamérica"], x: "Migran en varias generaciones desde África hasta el norte de Europa: un relevo de miles de kilómetros." } } },
  { id: "b30", lvl: 2, type: "text", right: 0, t: { de: { q: "Wie kümmern sich Wolfspinnen-Weibchen um ihren Nachwuchs?", a: ["Sie tragen die Jungen auf dem Rücken", "Sie füttern sie mit Blütennektar", "Sie legen die Eier ins Wasser", "Sie legen die Eier in Vogelnester"], x: "Erst schleppen sie den Eikokon an den Spinnwarzen mit. Die geschlüpften Jungen reiten dann einige Tage auf ihrem Rücken." }, en: { q: "How do female wolf spiders care for their young?", a: ["They carry them on their back", "They feed them flower nectar", "They lay their eggs in water", "They lay their eggs in bird nests"], x: "First they drag the egg sac along on their spinnerets. The hatched young then ride on their back for some days." }, fr: { q: "Comment les femelles d'araignée-loup s'occupent-elles de leurs petits ?", a: ["Elles les portent sur le dos", "Elles les nourrissent de nectar", "Elles pondent dans l'eau", "Elles pondent dans des nids d'oiseaux"], x: "Elles traînent d'abord leur cocon accroché aux filières. Puis les petits voyagent quelques jours sur leur dos." }, es: { q: "¿Cómo cuidan las hembras de araña lobo a sus crías?", a: ["Las llevan sobre la espalda", "Las alimentan con néctar", "Ponen los huevos en el agua", "Ponen los huevos en nidos de aves"], x: "Primero arrastran el saco de huevos sujeto a las hileras. Luego las crías viajan unos días sobre su espalda." } } },
  { id: "b31", lvl: 3, type: "tf", right: 0, t: { de: { q: "Kreuzspinnen fressen ihr altes Netz oft auf, bevor sie ein neues bauen.", a: ["Wahr", "Falsch"], x: "So recyceln sie die wertvollen Eiweiße der Spinnenseide. Viele bauen ihr Netz fast täglich neu." }, en: { q: "Garden spiders often eat their old web before building a new one.", a: ["True", "False"], x: "This way they recycle the valuable proteins in the silk. Many rebuild their web almost every day." }, fr: { q: "L'épeire diadème mange souvent sa vieille toile avant d'en tisser une nouvelle.", a: ["Vrai", "Faux"], x: "Elle recycle ainsi les précieuses protéines de la soie. Beaucoup refont leur toile presque chaque jour." }, es: { q: "La araña de jardín (epeira) suele comerse su vieja tela antes de tejer otra.", a: ["Verdadero", "Falso"], x: "Así recicla las valiosas proteínas de la seda. Muchas rehacen su tela casi a diario." } } },
  { id: "b32", lvl: 2, type: "text", right: 2, t: { de: { q: "Was fehlt dem Weberknecht im Gegensatz zu echten Spinnen?", a: ["Augen", "Mundwerkzeuge", "Spinndrüsen", "Beine mit Gelenken"], x: "Weberknechte sind Spinnentiere, aber keine Webspinnen: Sie bauen keine Netze, und ihr Körper wirkt wie aus einem Stück." }, en: { q: "What does a harvestman lack, unlike true spiders?", a: ["Eyes", "Mouthparts", "Silk glands", "Jointed legs"], x: "Harvestmen are arachnids but not spiders: they build no webs, and their body looks like one single piece." }, fr: { q: "Que n'a pas l'opilion (faucheux), contrairement aux vraies araignées ?", a: ["Des yeux", "Des pièces buccales", "Des glandes à soie", "Des pattes articulées"], x: "Les opilions sont des arachnides mais pas des araignées : ils ne tissent pas de toile et leur corps semble d'une seule pièce." }, es: { q: "¿Qué le falta al opilión, a diferencia de las arañas?", a: ["Ojos", "Piezas bucales", "Glándulas de seda", "Patas articuladas"], x: "Los opiliones son arácnidos, pero no arañas: no tejen telas y su cuerpo parece de una sola pieza." } } },
  { id: "b33", lvl: 2, type: "tf", right: 1, t: { de: { q: "Teilt man einen Regenwurm, entstehen daraus zwei vollständige Würmer.", a: ["Wahr", "Falsch"], x: "Meist überlebt höchstens das vordere Stück und bildet ein neues Hinterende. Das hintere Stück stirbt in der Regel." }, en: { q: "If you cut an earthworm in two, you get two complete worms.", a: ["True", "False"], x: "Usually only the front part may survive and grow a new rear end. The back part normally dies." }, fr: { q: "Si l'on coupe un ver de terre en deux, on obtient deux vers complets.", a: ["Vrai", "Faux"], x: "En général, seule la partie avant peut survivre et refaire une nouvelle queue. La partie arrière meurt le plus souvent." }, es: { q: "Si se corta una lombriz en dos, salen dos lombrices completas.", a: ["Verdadero", "Falso"], x: "Normalmente solo la parte delantera puede sobrevivir y regenerar un nuevo extremo trasero. La trasera suele morir." } } },
  { id: "b34", lvl: 3, type: "tf", right: 0, t: { de: { q: "Haie haben keine Schwimmblase.", a: ["Wahr", "Falsch"], x: "Auftrieb gibt Haien vor allem eine große, ölreiche Leber. Viele müssen schwimmen, um nicht abzusinken." }, en: { q: "Sharks have no swim bladder.", a: ["True", "False"], x: "Instead, a large oil-rich liver gives sharks buoyancy. Many must keep swimming so they don't sink." }, fr: { q: "Les requins n'ont pas de vessie natatoire.", a: ["Vrai", "Faux"], x: "Un grand foie riche en huile les aide à flotter. Beaucoup doivent nager sans cesse pour ne pas couler." }, es: { q: "Los tiburones no tienen vejiga natatoria.", a: ["Verdadero", "Falso"], x: "Un hígado grande y rico en aceite les ayuda a flotar. Muchos deben nadar para no hundirse." } } },
  { id: "b35", lvl: 1, type: "text", right: 1, t: { de: { q: "Wer bringt beim Seepferdchen die Jungen zur Welt?", a: ["Das Weibchen", "Das Männchen", "Beide abwechselnd", "Niemand – Eier liegen im Sand"], x: "Das Weibchen legt die Eier in die Bruttasche des Männchens. Dort entwickeln sie sich, bis er die Jungen 'gebärt'." }, en: { q: "Which seahorse parent gives birth to the young?", a: ["The female", "The male", "Both, taking turns", "Neither – eggs lie in the sand"], x: "The female puts her eggs into the male's brood pouch. They develop there until he 'gives birth' to the young." }, fr: { q: "Chez l'hippocampe, qui met les petits au monde ?", a: ["La femelle", "Le mâle", "Les deux à tour de rôle", "Personne : les œufs sont au sol"], x: "La femelle dépose ses œufs dans la poche incubatrice du mâle. Ils s'y développent jusqu'à ce qu'il « accouche »." }, es: { q: "¿Quién da a luz a las crías del caballito de mar?", a: ["La hembra", "El macho", "Ambos, por turnos", "Nadie: los huevos están en la arena"], x: "La hembra deposita los huevos en la bolsa incubadora del macho. Allí se desarrollan hasta que él «da a luz»." } } },
  { id: "b36", lvl: 1, type: "text", right: 2, t: { de: { q: "Wozu hängt man im Garten mit Holzwolle gefüllte Tontöpfe kopfüber auf?", a: ["Als Falle für Schnecken", "Als Winterquartier für Igel", "Als Versteck für Ohrwürmer", "Als Futterstelle für Vögel"], x: "Ohrwürmer verstecken sich tagsüber darin und fressen nachts Blattläuse. In Ohren kriechen sie übrigens nicht gezielt." }, en: { q: "Why do gardeners hang clay pots filled with wood wool upside down?", a: ["As a trap for slugs", "As a winter home for hedgehogs", "As a shelter for earwigs", "As a bird feeder"], x: "Earwigs hide in them by day and eat aphids at night. And no, they don't deliberately crawl into ears." }, fr: { q: "Pourquoi suspend-on au jardin des pots en terre remplis de fibre de bois, à l'envers ?", a: ["Pour piéger les limaces", "Pour abriter les hérissons l'hiver", "Pour abriter les perce-oreilles", "Pour nourrir les oiseaux"], x: "Les perce-oreilles s'y cachent le jour et mangent des pucerons la nuit. Ils n'entrent pas exprès dans les oreilles." }, es: { q: "¿Para qué se cuelgan boca abajo macetas de barro con viruta de madera?", a: ["Como trampa para babosas", "Como refugio invernal para erizos", "Como refugio para tijeretas", "Como comedero para pájaros"], x: "Las tijeretas se esconden en ellas de día y comen pulgones de noche. Y no, no se meten a propósito en los oídos." } } },
  { id: "b37", lvl: 1, type: "text", right: 3, t: { de: { q: "Schwebfliegen sehen oft aus wie Wespen. Was stimmt?", a: ["Sie stechen stärker als Wespen", "Sie haben vier Flügel wie Wespen", "Sie sind junge Wespen", "Sie sind harmlos und ahmen Wespen nach"], x: "Die Tarnung schreckt Feinde ab. Die Larven vieler Schwebfliegen fressen Blattläuse – echte Gartenhelfer!" }, en: { q: "Hoverflies often look like wasps. What is true?", a: ["They sting harder than wasps", "They have four wings like wasps", "They are young wasps", "They're harmless wasp mimics"], x: "The disguise scares off enemies. The larvae of many hoverflies eat aphids – real garden helpers!" }, fr: { q: "Les syrphes ressemblent souvent à des guêpes. Qu'est-ce qui est vrai ?", a: ["Ils piquent plus fort que les guêpes", "Ils ont quatre ailes comme les guêpes", "Ce sont de jeunes guêpes", "Inoffensifs, ils imitent les guêpes"], x: "Ce déguisement effraie les ennemis. Les larves de nombreux syrphes mangent des pucerons : de vrais alliés du jardin !" }, es: { q: "Los sírfidos suelen parecer avispas. ¿Qué es cierto?", a: ["Pican más fuerte que las avispas", "Tienen cuatro alas como las avispas", "Son avispas jóvenes", "Son inofensivos e imitan a avispas"], x: "El disfraz asusta a los enemigos. Las larvas de muchos sírfidos comen pulgones: ¡grandes ayudantes del jardín!" } } },
  { id: "b38", lvl: 1, type: "text", right: 2, t: { de: { q: "Welche Tiergruppe hat weltweit die meisten bekannten Arten?", a: ["Vögel", "Fische", "Käfer", "Schmetterlinge"], x: "Mit rund 350.000 bis 400.000 beschriebenen Arten sind Käfer die artenreichste Tiergruppe der Erde." }, en: { q: "Which animal group has the most known species worldwide?", a: ["Birds", "Fish", "Beetles", "Butterflies and moths"], x: "With around 350,000 to 400,000 described species, beetles are the most species-rich animal group on Earth." }, fr: { q: "Quel groupe d'animaux compte le plus d'espèces connues au monde ?", a: ["Les oiseaux", "Les poissons", "Les coléoptères", "Les papillons"], x: "Avec environ 350 000 à 400 000 espèces décrites, les coléoptères sont le groupe animal le plus riche en espèces." }, es: { q: "¿Qué grupo de animales tiene más especies conocidas en el mundo?", a: ["Las aves", "Los peces", "Los escarabajos", "Las mariposas"], x: "Con unas 350.000 a 400.000 especies descritas, los escarabajos son el grupo animal con más especies de la Tierra." } } },
  { id: "b39", lvl: 2, type: "text", right: 1, t: { de: { q: "Wo laicht der Europäische Aal?", a: ["Im Bodensee", "In der Sargassosee", "Im Wattenmeer", "In Gebirgsbächen"], x: "Aale wandern Tausende Kilometer in die Sargassosee im Atlantik. Ihre Larven treiben mit der Strömung zurück nach Europa." }, en: { q: "Where does the European eel spawn?", a: ["In Lake Constance", "In the Sargasso Sea", "In the Wadden Sea", "In mountain streams"], x: "Eels travel thousands of kilometres to the Sargasso Sea in the Atlantic. Their larvae drift back to Europe on currents." }, fr: { q: "Où se reproduit l'anguille européenne ?", a: ["Dans le lac de Constance", "Dans la mer des Sargasses", "Dans la mer des Wadden", "Dans les torrents de montagne"], x: "Les anguilles parcourent des milliers de kilomètres jusqu'à la mer des Sargasses. Leurs larves dérivent ensuite vers l'Europe." }, es: { q: "¿Dónde desova la anguila europea?", a: ["En el lago de Constanza", "En el mar de los Sargazos", "En el mar de Wadden", "En arroyos de montaña"], x: "Las anguilas recorren miles de kilómetros hasta el mar de los Sargazos. Sus larvas vuelven a Europa con las corrientes." } } },
  { id: "b40", lvl: 2, type: "text", right: 2, t: { de: { q: "Woran erkennen Lachse ihren Heimatfluss, um dort zu laichen?", a: ["An der Farbe des Wassers", "Am Rauschen von Wasserfällen", "Am Geruch des Wassers", "Sie folgen den Aalen"], x: "Junge Lachse prägen sich den Geruch ihres Heimatgewässers ein. Jahre später finden sie damit aus dem Meer zurück." }, en: { q: "How do salmon recognise their home river to spawn there?", a: ["By the colour of the water", "By the sound of waterfalls", "By the smell of the water", "They follow the eels"], x: "Young salmon memorise the smell of their home waters. Years later, they use it to find their way back from the sea." }, fr: { q: "Comment les saumons reconnaissent-ils leur rivière natale pour y frayer ?", a: ["À la couleur de l'eau", "Au bruit des cascades", "À l'odeur de l'eau", "Ils suivent les anguilles"], x: "Les jeunes saumons mémorisent l'odeur de leur rivière natale. Des années plus tard, elle les guide depuis la mer." }, es: { q: "¿Cómo reconocen los salmones su río natal para desovar allí?", a: ["Por el color del agua", "Por el ruido de las cascadas", "Por el olor del agua", "Siguen a las anguilas"], x: "Los salmones jóvenes memorizan el olor de su río natal. Años después, lo usan para volver desde el mar." } } },
  { id: "b41", lvl: 2, type: "text", right: 3, t: { de: { q: "Welche Gartenbeleuchtung lockt nachts am wenigsten Insekten an?", a: ["Kaltweißes Licht", "Bläuliches Licht", "Lampen mit UV-Anteil", "Warmweißes, gelbliches Licht"], x: "Insekten fliegen vor allem auf blaues und UV-Licht. Besser: warmweiße, nach unten gerichtete Lampen – oder gar kein Licht." }, en: { q: "Which garden lighting attracts the fewest insects at night?", a: ["Cool white light", "Bluish light", "Lamps that emit UV", "Warm white, yellowish light"], x: "Insects are drawn mostly to blue and UV light. Better: warm white lamps pointing downwards – or no light at all." }, fr: { q: "Quel éclairage de jardin attire le moins d'insectes la nuit ?", a: ["Lumière blanc froid", "Lumière bleutée", "Lampes émettant des UV", "Lumière blanc chaud, jaunâtre"], x: "Les insectes sont surtout attirés par la lumière bleue et UV. Mieux : des lampes blanc chaud dirigées vers le bas, ou pas de lumière." }, es: { q: "¿Qué iluminación de jardín atrae menos insectos por la noche?", a: ["Luz blanca fría", "Luz azulada", "Lámparas con luz UV", "Luz blanca cálida, amarillenta"], x: "Los insectos acuden sobre todo a la luz azul y UV. Mejor: lámparas cálidas orientadas hacia abajo, o ninguna luz." } } },
  { id: "b42", lvl: 2, type: "text", right: 3, t: { de: { q: "Was macht das Männchen des Dreistachligen Stichlings zur Laichzeit?", a: ["Es trägt die Eier im Maul", "Es vergräbt die Eier und schwimmt weg", "Es klebt die Eier an Wasservögel", "Es baut ein Nest und bewacht die Brut"], x: "Das Männchen bekommt einen roten Bauch, baut ein Nest aus Pflanzenteilen und fächelt den Eiern frisches Wasser zu." }, en: { q: "What does the male three-spined stickleback do in the breeding season?", a: ["Carries the eggs in its mouth", "Buries the eggs and swims off", "Sticks the eggs onto waterbirds", "Builds a nest and guards the brood"], x: "The male turns red-bellied, builds a nest from plant material and fans fresh water over the eggs." }, fr: { q: "Que fait le mâle de l'épinoche à trois épines pendant la reproduction ?", a: ["Il porte les œufs dans sa bouche", "Il enterre les œufs et s'en va", "Il colle les œufs sur des oiseaux", "Il construit un nid et garde les œufs"], x: "Le mâle prend un ventre rouge, construit un nid de débris végétaux et ventile les œufs avec de l'eau fraîche." }, es: { q: "¿Qué hace el macho del espinoso durante la reproducción?", a: ["Lleva los huevos en la boca", "Entierra los huevos y se va", "Pega los huevos a aves acuáticas", "Construye un nido y cuida la puesta"], x: "El macho se vuelve de vientre rojo, construye un nido con restos de plantas y abanica los huevos con agua fresca." } } },
  { id: "b43", lvl: 2, type: "text", right: 0, t: { de: { q: "Wie verschließt die Weinbergschnecke im Winter ihr Haus?", a: ["Mit einem Deckel aus Kalk", "Mit einem eingerollten Blatt", "Mit einem Pfropfen aus Erde", "Gar nicht – es bleibt offen"], x: "Sie gräbt sich ein und verschließt die Öffnung mit einem Kalkdeckel. In Deutschland stehen Weinbergschnecken unter Schutz." }, en: { q: "How does the Roman snail seal its shell in winter?", a: ["With a lid made of lime", "With a rolled-up leaf", "With a plug of soil", "Not at all – it stays open"], x: "It digs in and seals the opening with a chalky lid. In Germany, Roman snails are a protected species." }, fr: { q: "Comment l'escargot de Bourgogne ferme-t-il sa coquille en hiver ?", a: ["Avec un couvercle de calcaire", "Avec une feuille enroulée", "Avec un bouchon de terre", "Il ne la ferme pas"], x: "Il s'enterre et ferme l'ouverture avec un couvercle calcaire. En Allemagne, cette espèce est protégée." }, es: { q: "¿Cómo cierra su concha en invierno el caracol de Borgoña?", a: ["Con una tapa de cal", "Con una hoja enrollada", "Con un tapón de tierra", "No la cierra"], x: "Se entierra y cierra la abertura con una tapa calcárea. En Alemania es una especie protegida." } } },
  { id: "b44", lvl: 3, type: "text", right: 1, t: { de: { q: "Was bedroht den heimischen Edelkrebs am stärksten?", a: ["Zu kalte Winter", "Die eingeschleppte Krebspest", "Der Biber", "Zu viele Wasserpflanzen"], x: "Amerikanische Krebse wie der Signalkrebs tragen den Erreger, ohne zu erkranken. Für heimische Krebse ist er meist tödlich." }, en: { q: "What is the biggest threat to the native noble crayfish?", a: ["Cold winters", "Introduced crayfish plague", "Beavers", "Too many water plants"], x: "American species like the signal crayfish carry the pathogen without falling ill. For native crayfish it is usually fatal." }, fr: { q: "Quelle est la plus grande menace pour l'écrevisse à pattes rouges ?", a: ["Les hivers froids", "La peste de l'écrevisse importée", "Le castor", "Trop de plantes aquatiques"], x: "Des écrevisses américaines comme l'écrevisse signal portent le pathogène sans être malades. Il tue souvent les espèces indigènes." }, es: { q: "¿Cuál es la mayor amenaza para el cangrejo de río europeo?", a: ["Los inviernos fríos", "La peste del cangrejo introducida", "El castor", "El exceso de plantas acuáticas"], x: "Especies americanas como el cangrejo señal portan el patógeno sin enfermar. Para los cangrejos autóctonos suele ser mortal." } } },
  { id: "b45", lvl: 3, type: "text", right: 2, t: { de: { q: "Wie frisst ein Seestern eine Miesmuschel?", a: ["Er knackt sie mit Zähnen", "Er schlägt sie gegen Steine", "Er stülpt seinen Magen in die Muschel", "Er saugt sie durch die Arme auf"], x: "Er zieht die Schalen mit seinen Saugfüßchen einen Spalt auf, stülpt den Magen hinein und verdaut die Muschel darin." }, en: { q: "How does a starfish eat a mussel?", a: ["It cracks it with its teeth", "It smashes it against rocks", "It pushes its stomach into the mussel", "It sucks it up through its arms"], x: "It pulls the shells slightly apart with its tube feet, pushes its stomach inside and digests the mussel right there." }, fr: { q: "Comment une étoile de mer mange-t-elle une moule ?", a: ["Elle la casse avec ses dents", "Elle la frappe contre un rocher", "Elle glisse son estomac dans la moule", "Elle l'aspire par ses bras"], x: "Elle entrouvre les valves avec ses pieds ambulacraires, y glisse son estomac et digère la moule sur place." }, es: { q: "¿Cómo se come una estrella de mar a un mejillón?", a: ["Lo rompe con los dientes", "Lo golpea contra las rocas", "Mete su estómago dentro del mejillón", "Lo absorbe por los brazos"], x: "Abre un poco las valvas con sus pies ambulacrales, introduce el estómago y digiere el mejillón allí mismo." } } },
  { id: "b46", lvl: 3, type: "text", right: 0, t: { de: { q: "Wie verbreiten sich die Larven heimischer Großmuscheln wie der Teichmuschel?", a: ["Sie heften sich an Fische", "Sie werden vom Wind verweht", "Sie kriechen durch den Boden", "Sie treiben in Schaumflocken"], x: "Die winzigen Larven (Glochidien) klammern sich an Kiemen oder Flossen von Fischen und lassen sich eine Weile mitnehmen." }, en: { q: "How do the larvae of native freshwater mussels like the swan mussel spread?", a: ["They attach to fish", "They are blown by the wind", "They crawl through the soil", "They drift in flecks of foam"], x: "The tiny larvae (glochidia) cling to the gills or fins of fish and hitch a ride for a while." }, fr: { q: "Comment se dispersent les larves des grandes moules d'eau douce comme l'anodonte ?", a: ["Elles s'accrochent aux poissons", "Elles sont portées par le vent", "Elles rampent dans le sol", "Elles flottent dans l'écume"], x: "Les minuscules larves (glochidies) s'accrochent aux branchies ou aux nageoires des poissons et voyagent un moment avec eux." }, es: { q: "¿Cómo se dispersan las larvas de los grandes mejillones de agua dulce, como la anodonta?", a: ["Se adhieren a peces", "Las lleva el viento", "Se arrastran por el suelo", "Flotan en la espuma"], x: "Las diminutas larvas (gloquidios) se aferran a las branquias o aletas de los peces y viajan con ellos un tiempo." } } },
  { id: "b47", lvl: 3, type: "text", right: 1, t: { de: { q: "Wie bohrt man Nistlöcher für Wildbienen am besten in Holz?", a: ["Ins Stirnholz (Schnittfläche)", "Seitlich ins Längsholz", "In weiches Fichtenholz", "Mit 3 bis 5 cm Durchmesser"], x: "Löcher im Stirnholz reißen leicht ein, dann kann die Brut verpilzen. Besser: trockenes Hartholz, seitlich, wenige mm breit." }, en: { q: "What is the best way to drill nest holes for wild bees in wood?", a: ["Into the end grain (cut face)", "Into the side of the wood", "Into soft spruce wood", "3 to 5 cm wide"], x: "Holes in end grain crack easily and the brood can go mouldy. Better: dry hardwood, drilled from the side, a few mm wide." }, fr: { q: "Comment percer au mieux des trous de nidification pour abeilles sauvages dans le bois ?", a: ["Dans le bois de bout (la coupe)", "Sur le côté, dans le fil du bois", "Dans de l'épicéa tendre", "Avec 3 à 5 cm de diamètre"], x: "Les trous dans le bois de bout se fendent et le couvain peut moisir. Mieux : bois dur sec, percé sur le côté, de quelques mm." }, es: { q: "¿Cómo se perforan mejor los nidos para abejas silvestres en madera?", a: ["En la testa (cara del corte)", "En el costado de la madera", "En madera blanda de abeto", "Con 3 a 5 cm de diámetro"], x: "Los agujeros en la testa se agrietan y la cría puede enmohecerse. Mejor: madera dura y seca, perforada de lado, de pocos mm." } } },
  { id: "b48", lvl: 3, type: "text", right: 3, t: { de: { q: "Viele Wildbienen sind 'oligolektisch'. Was bedeutet das?", a: ["Sie leben einzeln, ohne Staat", "Sie fliegen nur nachts", "Sie haben keinen Stachel", "Sie sammeln nur an wenigen Pflanzen"], x: "Solche Spezialisten brauchen z. B. Glockenblumen oder Weiden. Fehlen diese Pflanzen, verschwindet auch die Biene." }, en: { q: "Many wild bees are 'oligolectic'. What does that mean?", a: ["They live alone, without a colony", "They only fly at night", "They have no sting", "They collect pollen from few plants"], x: "Such specialists need e.g. bellflowers or willows. If these plants disappear, so does the bee." }, fr: { q: "Beaucoup d'abeilles sauvages sont « oligolectiques ». Qu'est-ce que cela signifie ?", a: ["Elles vivent seules, sans colonie", "Elles ne volent que la nuit", "Elles n'ont pas de dard", "Elles butinent peu de plantes"], x: "Ces spécialistes ont besoin par exemple de campanules ou de saules. Si ces plantes disparaissent, l'abeille aussi." }, es: { q: "Muchas abejas silvestres son «oligolécticas». ¿Qué significa?", a: ["Viven solas, sin colonia", "Solo vuelan de noche", "No tienen aguijón", "Recogen polen de pocas plantas"], x: "Estas especialistas necesitan, por ejemplo, campánulas o sauces. Si esas plantas desaparecen, la abeja también." } } },
  { id: "b49", lvl: 3, type: "text", right: 2, t: { de: { q: "Wie lange entwickeln sich Hirschkäfer-Larven im morschen Holz?", a: ["Etwa 2 Wochen", "Nur einen Sommer", "Meist 3 bis 8 Jahre", "Rund 30 Jahre"], x: "Die Larven fressen jahrelang morsches Holz, oft von alten Eichen. Der fertige Käfer lebt dann nur wenige Wochen." }, en: { q: "How long do stag beetle larvae develop in rotting wood?", a: ["About 2 weeks", "Just one summer", "Usually 3 to 8 years", "Around 30 years"], x: "The larvae feed on rotting wood, often of old oaks, for years. The adult beetle then lives only a few weeks." }, fr: { q: "Combien de temps les larves de lucane cerf-volant se développent-elles dans le bois mort ?", a: ["Environ 2 semaines", "Un seul été", "En général 3 à 8 ans", "Environ 30 ans"], x: "Les larves mangent du bois pourri, souvent de vieux chênes, pendant des années. L'adulte ne vit ensuite que quelques semaines." }, es: { q: "¿Cuánto tiempo se desarrollan las larvas del ciervo volante en la madera podrida?", a: ["Unas 2 semanas", "Solo un verano", "Normalmente de 3 a 8 años", "Unos 30 años"], x: "Las larvas comen madera podrida, a menudo de robles viejos, durante años. El adulto vive luego solo unas semanas." } } },
  { id: "b50", lvl: 3, type: "text", right: 3, t: { de: { q: "Wo sitzen die Ohren des Grünen Heupferds?", a: ["Am Kopf", "An den Fühlern", "Am Hinterleib", "An den Vorderbeinen"], x: "Laubheuschrecken hören mit Trommelfellen an den Vorderbeinen. Kurzfühlerschrecken wie Grashüpfer haben sie am Hinterleib." }, en: { q: "Where are the ears of the great green bush-cricket?", a: ["On its head", "On its antennae", "On its abdomen", "On its front legs"], x: "Bush-crickets hear with eardrums on their front legs. Grasshoppers, by contrast, have theirs on the abdomen." }, fr: { q: "Où se trouvent les oreilles de la grande sauterelle verte ?", a: ["Sur la tête", "Sur les antennes", "Sur l'abdomen", "Sur les pattes avant"], x: "Les sauterelles entendent grâce à des tympans sur les pattes avant. Les criquets, eux, les ont sur l'abdomen." }, es: { q: "¿Dónde tiene los oídos el saltamontes verde (Tettigonia)?", a: ["En la cabeza", "En las antenas", "En el abdomen", "En las patas delanteras"], x: "Los tetigónidos oyen con tímpanos en las patas delanteras. Los saltamontes de antenas cortas los tienen en el abdomen." } } },
  { id: "k01", lvl: 2, type: "text", right: 1, t: { de: { q: "Welche Aussage ist FALSCH?", a: ["Eulen können ihre Augen nicht bewegen", "Alle Haie müssen ständig schwimmen, um zu atmen", "Kraken haben blaues Blut", "Biber haben orange Zähne"], x: "Viele Haie müssen schwimmen, aber nicht alle: Ammenhaie oder Katzenhaie liegen am Grund und pumpen Wasser über ihre Kiemen." }, en: { q: "Which statement is FALSE?", a: ["Owls can’t move their eyes", "All sharks must swim constantly to breathe", "Octopuses have blue blood", "Beavers have orange teeth"], x: "Many sharks have to swim, but not all: nurse sharks or catsharks lie on the bottom and pump water over their gills." }, fr: { q: "Quelle affirmation est FAUSSE ?", a: ["Les chouettes ne peuvent pas bouger les yeux", "Tous les requins doivent nager sans arrêt pour respirer", "Les pieuvres ont le sang bleu", "Les castors ont les dents orange"], x: "Beaucoup de requins doivent nager, mais pas tous : le requin-nourrice ou la roussette restent au fond et pompent l’eau sur leurs branchies." }, es: { q: "¿Qué afirmación es FALSA?", a: ["Los búhos no pueden mover los ojos", "Todos los tiburones deben nadar sin parar para respirar", "Los pulpos tienen sangre azul", "Los castores tienen los dientes naranjas"], x: "Muchos tiburones tienen que nadar, pero no todos: el tiburón nodriza o la pintarroja descansan en el fondo y bombean agua por sus branquias." } } },
  { id: "k02", lvl: 1, type: "text", right: 2, t: { de: { q: "Welche Aussage ist FALSCH?", a: ["Ameisen tragen ein Vielfaches ihres Gewichts", "Spechte trommeln über 10-mal pro Sekunde", "Fledermäuse sind blind", "Hummeln fliegen auch bei Kälte"], x: "Fledermäuse sehen gut. Nachts orientieren sie sich aber zusätzlich mit Ultraschall-Echos." }, en: { q: "Which statement is FALSE?", a: ["Ants carry many times their own weight", "Woodpeckers drum over 10 times a second", "Bats are blind", "Bumblebees fly even in the cold"], x: "Bats can see well. At night, they also find their way using ultrasound echoes." }, fr: { q: "Quelle affirmation est FAUSSE ?", a: ["Les fourmis portent plusieurs fois leur poids", "Le pic tambourine plus de 10 fois par seconde", "Les chauves-souris sont aveugles", "Les bourdons volent même par temps froid"], x: "Les chauves-souris voient bien. La nuit, elles s’orientent en plus grâce à l’écho des ultrasons." }, es: { q: "¿Qué afirmación es FALSA?", a: ["Las hormigas cargan varias veces su peso", "Los pájaros carpinteros tamborilean más de 10 veces por segundo", "Los murciélagos son ciegos", "Los abejorros vuelan incluso con frío"], x: "Los murciélagos ven bien. De noche se orientan además con el eco de los ultrasonidos." } } },
  { id: "k03", lvl: 2, type: "text", right: 0, t: { de: { q: "Schätzfrage: Wie viel Honig sammelt eine Arbeitsbiene in ihrem ganzen Leben?", a: ["Etwa 1/12 Teelöffel", "Etwa 1 Teelöffel", "Etwa 1 Esslöffel", "Etwa ein halbes Glas"], x: "Nur etwa ein Zwölftel Teelöffel! Für ein Glas Honig fliegen Bienen zusammen eine Strecke, die mehrmals um die Erde reicht." }, en: { q: "Guess: how much honey does a worker bee make in her whole life?", a: ["About 1/12 teaspoon", "About 1 teaspoon", "About 1 tablespoon", "About half a jar"], x: "Only about a twelfth of a teaspoon! For one jar of honey, bees together fly a distance that would go around the Earth several times." }, fr: { q: "Devine : combien de miel une abeille ouvrière produit-elle dans toute sa vie ?", a: ["Environ 1/12 de cuillère à café", "Environ 1 cuillère à café", "Environ 1 cuillère à soupe", "Environ un demi-pot"], x: "Seulement un douzième de cuillère à café ! Pour un pot de miel, les abeilles parcourent ensemble une distance de plusieurs fois le tour de la Terre." }, es: { q: "Adivina: ¿cuánta miel produce una abeja obrera en toda su vida?", a: ["Una doceava parte de cucharadita", "Una cucharadita", "Una cucharada", "Medio tarro"], x: "¡Solo una doceava parte de cucharadita! Para un tarro de miel, las abejas recorren juntas una distancia de varias vueltas a la Tierra." } } },
  { id: "k04", lvl: 2, type: "text", right: 2, t: { de: { q: "Schätzfrage: Wie viele Insekten frisst eine kleine Zwergfledermaus in einer Nacht?", a: ["Etwa 5", "Etwa 50", "Mehrere Hundert bis über tausend", "Etwa eine Million"], x: "Eine Zwergfledermaus wiegt nur rund 5 Gramm, fängt aber pro Nacht Hunderte bis über tausend Mücken und andere kleine Insekten." }, en: { q: "Guess: how many insects does a tiny pipistrelle bat eat in one night?", a: ["About 5", "About 50", "Several hundred to over a thousand", "About a million"], x: "A pipistrelle weighs only about 5 grams, but catches hundreds to over a thousand midges and other small insects in one night." }, fr: { q: "Devine : combien d’insectes une petite pipistrelle mange-t-elle en une nuit ?", a: ["Environ 5", "Environ 50", "Plusieurs centaines à plus de mille", "Environ un million"], x: "Une pipistrelle ne pèse qu’environ 5 grammes, mais attrape en une nuit des centaines, voire plus de mille moucherons et autres petits insectes." }, es: { q: "Adivina: ¿cuántos insectos come un pequeño murciélago enano en una noche?", a: ["Unos 5", "Unos 50", "De varios cientos a más de mil", "Un millón"], x: "Un murciélago enano pesa solo unos 5 gramos, pero en una noche caza de cientos a más de mil mosquitos y otros insectos pequeños." } } },
  { id: "k05", lvl: 2, type: "text", right: 1, t: { de: { q: "Schätzfrage: Wie schwer ist ein Igelbaby bei der Geburt?", a: ["Etwa 2 Gramm", "Etwa 20 Gramm", "Etwa 200 Gramm", "Etwa 1 Kilo"], x: "Neugeborene Igel wiegen 12 bis 25 Gramm. Ihre Stacheln sind weich und stecken unter einer Hautschicht, damit die Geburt nicht wehtut – nach einigen Stunden kommen sie heraus." }, en: { q: "Guess: how much does a baby hedgehog weigh at birth?", a: ["About 2 grams", "About 20 grams", "About 200 grams", "About 1 kilo"], x: "Newborn hedgehogs weigh 12 to 25 grams. Their spines are soft and covered by a layer of skin so birth doesn’t hurt – they come out after a few hours." }, fr: { q: "Devine : combien pèse un bébé hérisson à la naissance ?", a: ["Environ 2 grammes", "Environ 20 grammes", "Environ 200 grammes", "Environ 1 kilo"], x: "Un hérisson nouveau-né pèse 12 à 25 grammes. Ses piquants sont mous et couverts d’une couche de peau pour que la naissance ne fasse pas mal – ils sortent après quelques heures." }, es: { q: "Adivina: ¿cuánto pesa un erizo al nacer?", a: ["Unos 2 gramos", "Unos 20 gramos", "Unos 200 gramos", "Un kilo"], x: "Un erizo recién nacido pesa de 12 a 25 gramos. Sus púas son blandas y están cubiertas por una capa de piel para que el parto no duela; salen a las pocas horas." } } },
  { id: "k06", lvl: 3, type: "text", right: 1, t: { de: { q: "Schätzfrage: Wie viele Federn hat ein Höckerschwan?", a: ["Etwa 2.500", "Etwa 25.000", "Etwa 250.000", "Etwa 2,5 Millionen"], x: "Rund 25.000 – die meisten Federn aller Vögel, ein großer Teil davon am langen Hals. Ein Kolibri hat nur etwa 1.000." }, en: { q: "Guess: how many feathers does a mute swan have?", a: ["About 2,500", "About 25,000", "About 250,000", "About 2.5 million"], x: "Around 25,000 – the most feathers of any bird, many of them on the long neck. A hummingbird has only about 1,000." }, fr: { q: "Devine : combien de plumes a un cygne tuberculé ?", a: ["Environ 2 500", "Environ 25 000", "Environ 250 000", "Environ 2,5 millions"], x: "Environ 25 000 – le record chez les oiseaux, dont une grande partie sur le long cou. Un colibri n’en a qu’environ 1 000." }, es: { q: "Adivina: ¿cuántas plumas tiene un cisne vulgar?", a: ["Unas 2.500", "Unas 25.000", "Unas 250.000", "Unos 2,5 millones"], x: "Unas 25.000, el récord entre las aves, muchas de ellas en el largo cuello. Un colibrí tiene solo unas 1.000." } } },
  { id: "k07", lvl: 1, type: "text", right: 0, t: { de: { q: "Was wächst einer Kaulquappe zuerst?", a: ["Die Hinterbeine", "Die Vorderbeine", "Die Zunge zum Fliegenfangen", "Ein längerer Schwanz für das Leben an Land"], x: "Zuerst wachsen die Hinterbeine, dann die Vorderbeine. Zum Schluss wird der Schwanz abgebaut – und als Baumaterial wiederverwertet." }, en: { q: "What does a tadpole grow first?", a: ["Its back legs", "Its front legs", "A tongue for catching flies", "A longer tail for life on land"], x: "The back legs grow first, then the front legs. Finally the tail is absorbed – and recycled as building material." }, fr: { q: "Qu’est-ce qui pousse en premier chez le têtard ?", a: ["Les pattes arrière", "Les pattes avant", "Une langue pour attraper les mouches", "Une queue plus longue pour la vie sur terre"], x: "Les pattes arrière poussent d’abord, puis les pattes avant. Enfin, la queue est résorbée – et recyclée comme matériau." }, es: { q: "¿Qué le crece primero a un renacuajo?", a: ["Las patas traseras", "Las patas delanteras", "Una lengua para cazar moscas", "Una cola más larga para vivir en tierra"], x: "Primero crecen las patas traseras y luego las delanteras. Al final la cola se reabsorbe y se recicla como material." } } },
  { id: "k08", lvl: 2, type: "text", right: 1, t: { de: { q: "Welches Tier hat die größten Augen der Welt?", a: ["Blauwal", "Koloss-Kalmar", "Strauß", "Uhu"], x: "Kalmare der Tiefsee haben Augen so groß wie ein Fußball, etwa 27 cm. Damit erkennen sie im Dunkeln die Pottwale, die sie jagen." }, en: { q: "Which animal has the largest eyes in the world?", a: ["Blue whale", "Colossal squid", "Ostrich", "Eagle owl"], x: "Deep-sea squids have eyes as big as a football, about 27 cm. They use them to spot the sperm whales that hunt them in the dark." }, fr: { q: "Quel animal a les plus grands yeux du monde ?", a: ["Baleine bleue", "Calmar colossal", "Autruche", "Grand-duc"], x: "Les calmars des abysses ont des yeux grands comme un ballon de foot, environ 27 cm. Ils repèrent ainsi dans le noir les cachalots qui les chassent." }, es: { q: "¿Qué animal tiene los ojos más grandes del mundo?", a: ["Ballena azul", "Calamar colosal", "Avestruz", "Búho real"], x: "Los calamares de las profundidades tienen ojos del tamaño de un balón, unos 27 cm. Así ven en la oscuridad a los cachalotes que los cazan." } } },
  { id: "k09", lvl: 2, type: "text", right: 0, t: { de: { q: "Wer gräbt oft den Bau, in dem später ein Fuchs wohnt?", a: ["Dachs", "Kaninchen", "Wildschwein", "Maulwurf"], x: "Füchse ziehen gern in Dachsbaue ein. Manchmal wohnen beide sogar gleichzeitig darin – in verschiedenen Röhren." }, en: { q: "Who often digs the den that a fox later lives in?", a: ["Badger", "Rabbit", "Wild boar", "Mole"], x: "Foxes like to move into badger setts. Sometimes both even live there at the same time – in different tunnels." }, fr: { q: "Qui creuse souvent le terrier où vivra ensuite un renard ?", a: ["Le blaireau", "Le lapin", "Le sanglier", "La taupe"], x: "Le renard s’installe volontiers dans un terrier de blaireau. Parfois, les deux y vivent même en même temps – dans des galeries différentes." }, es: { q: "¿Quién suele cavar la madriguera donde después vive un zorro?", a: ["El tejón", "El conejo", "El jabalí", "El topo"], x: "Los zorros se mudan con gusto a madrigueras de tejón. A veces viven los dos a la vez, en túneles distintos." } } },
  { id: "k10", lvl: 2, type: "text", right: 0, t: { de: { q: "Warum stehen Flamingos oft auf einem Bein?", a: ["Es spart Kraft und Wärme", "Das andere Bein ist müde vom Laufen", "So sehen sie Fische besser", "Damit Feinde sie für Äste halten"], x: "Auf einem Bein halten Flamingos die Balance fast ohne Muskelkraft. Über das eingezogene Bein verlieren sie außerdem weniger Wärme." }, en: { q: "Why do flamingos often stand on one leg?", a: ["It saves energy and warmth", "The other leg is tired from walking", "They can see fish better", "So enemies think they are branches"], x: "On one leg, flamingos keep their balance with almost no muscle effort. They also lose less heat through the tucked-up leg." }, fr: { q: "Pourquoi les flamants se tiennent-ils souvent sur une patte ?", a: ["Ça économise force et chaleur", "L’autre patte est fatiguée", "Ils voient mieux les poissons", "Pour que les ennemis les prennent pour des branches"], x: "Sur une patte, le flamant garde l’équilibre presque sans effort musculaire. Et il perd moins de chaleur par la patte repliée." }, es: { q: "¿Por qué los flamencos se apoyan a menudo en una pata?", a: ["Ahorran fuerza y calor", "La otra pata está cansada", "Ven mejor los peces", "Para que los enemigos los tomen por ramas"], x: "Sobre una pata, el flamenco mantiene el equilibrio casi sin esfuerzo muscular. Además pierde menos calor por la pata recogida." } } },
  { id: "k13", lvl: 2, type: "text", right: 2, t: { de: { q: "Welches Tier ist KEIN Fisch?", a: ["Seepferdchen", "Aal", "Tintenfisch", "Hai"], x: "Tintenfische sind Weichtiere, verwandt mit Schnecken. Seepferdchen und Aale sehen ungewöhnlich aus, sind aber echte Fische." }, en: { q: "Which animal is NOT a fish?", a: ["Seahorse", "Eel", "Squid", "Shark"], x: "Squids are molluscs, related to snails. Seahorses and eels look unusual, but they are real fish." }, fr: { q: "Quel animal n’est PAS un poisson ?", a: ["Hippocampe", "Anguille", "Calmar", "Requin"], x: "Le calmar est un mollusque, parent de l’escargot. L’hippocampe et l’anguille ont l’air étranges, mais ce sont de vrais poissons." }, es: { q: "¿Qué animal NO es un pez?", a: ["Caballito de mar", "Anguila", "Calamar", "Tiburón"], x: "El calamar es un molusco, pariente del caracol. El caballito de mar y la anguila parecen raros, pero son peces de verdad." } } },
  { id: "k14", lvl: 2, type: "text", right: 3, t: { de: { q: "Welches Tier ist KEIN Säugetier?", a: ["Fledermaus", "Delfin", "Schnabeltier", "Pinguin"], x: "Pinguine sind Vögel, die nicht fliegen können. Das Schnabeltier legt zwar Eier, säugt seine Jungen aber und ist ein Säugetier." }, en: { q: "Which animal is NOT a mammal?", a: ["Bat", "Dolphin", "Platypus", "Penguin"], x: "Penguins are birds that can’t fly. The platypus lays eggs, but it feeds its young with milk and is a mammal." }, fr: { q: "Quel animal n’est PAS un mammifère ?", a: ["Chauve-souris", "Dauphin", "Ornithorynque", "Manchot"], x: "Le manchot est un oiseau qui ne vole pas. L’ornithorynque pond des œufs, mais il allaite ses petits : c’est un mammifère." }, es: { q: "¿Qué animal NO es un mamífero?", a: ["Murciélago", "Delfín", "Ornitorrinco", "Pingüino"], x: "El pingüino es un ave que no vuela. El ornitorrinco pone huevos, pero amamanta a sus crías y es un mamífero." } } },
  { id: "k17", lvl: 2, type: "text", right: 2, t: { de: { q: "Schätzfrage: Wie weit springt ein Floh im Verhältnis zu seiner Größe?", a: ["Etwa doppelt so weit", "Etwa 10-mal so weit", "Über 100-mal so weit", "Etwa 10.000-mal so weit"], x: "Ein Floh springt rund 30 cm weit – über hundertmal seine Körperlänge. Ein Mensch müsste dafür weiter springen als ein Fußballfeld lang ist." }, en: { q: "Guess: how far does a flea jump compared to its size?", a: ["About twice as far", "About 10 times as far", "Over 100 times as far", "About 10,000 times as far"], x: "A flea jumps about 30 cm – over a hundred times its body length. A human would have to jump further than a football pitch is long." }, fr: { q: "Devine : à quelle distance une puce saute-t-elle par rapport à sa taille ?", a: ["Environ deux fois sa taille", "Environ 10 fois", "Plus de 100 fois", "Environ 10 000 fois"], x: "Une puce saute environ 30 cm – plus de cent fois la longueur de son corps. Un humain devrait sauter plus loin que la longueur d’un terrain de foot." }, es: { q: "Adivina: ¿cuánto salta una pulga en relación con su tamaño?", a: ["El doble de su tamaño", "Unas 10 veces", "Más de 100 veces", "Unas 10.000 veces"], x: "Una pulga salta unos 30 cm, más de cien veces su longitud. Un humano tendría que saltar más que lo que mide un campo de fútbol." } } },
  { id: "k18", lvl: 1, type: "text", right: 0, t: { de: { q: "Welche Reihenfolge stimmt beim Schmetterling?", a: ["Ei – Raupe – Puppe – Falter", "Ei – Puppe – Raupe – Falter", "Raupe – Ei – Puppe – Falter", "Ei – Raupe – Falter – Puppe"], x: "Aus dem Ei schlüpft die Raupe, sie frisst und wächst, verpuppt sich, und in der Puppe wird ihr ganzer Körper zum Falter umgebaut." }, en: { q: "Which order is right for a butterfly?", a: ["Egg – caterpillar – pupa – butterfly", "Egg – pupa – caterpillar – butterfly", "Caterpillar – egg – pupa – butterfly", "Egg – caterpillar – butterfly – pupa"], x: "A caterpillar hatches from the egg, eats and grows, turns into a pupa, and inside the pupa its whole body is rebuilt into a butterfly." }, fr: { q: "Quel est le bon ordre chez le papillon ?", a: ["Œuf – chenille – chrysalide – papillon", "Œuf – chrysalide – chenille – papillon", "Chenille – œuf – chrysalide – papillon", "Œuf – chenille – papillon – chrysalide"], x: "La chenille sort de l’œuf, mange et grandit, devient chrysalide, et dans la chrysalide tout son corps se transforme en papillon." }, es: { q: "¿Qué orden es el correcto en la mariposa?", a: ["Huevo – oruga – crisálida – mariposa", "Huevo – crisálida – oruga – mariposa", "Oruga – huevo – crisálida – mariposa", "Huevo – oruga – mariposa – crisálida"], x: "Del huevo sale la oruga, que come y crece, se convierte en crisálida, y dentro todo su cuerpo se transforma en mariposa." } } },
  { id: "t04", lvl: 1, type: "tf", right: 1, t: { de: { q: "Stimmt’s? Goldfische haben ein Gedächtnis von nur drei Sekunden.", a: ["Wahr", "Falsch"], x: "Ein Mythos! Goldfische können sich Dinge monatelang merken und lassen sich sogar auf Töne oder Farben trainieren." }, en: { q: "True or false? Goldfish have a memory of only three seconds.", a: ["True", "False"], x: "A myth! Goldfish can remember things for months and can even be trained to respond to sounds or colours." }, fr: { q: "Vrai ou faux ? Le poisson rouge n’a que trois secondes de mémoire.", a: ["Vrai", "Faux"], x: "Un mythe ! Le poisson rouge se souvient de choses pendant des mois et peut même être dressé à réagir à des sons ou des couleurs." }, es: { q: "¿Verdadero o falso? Los peces de colores solo tienen tres segundos de memoria.", a: ["Verdadero", "Falso"], x: "¡Un mito! Los peces de colores recuerdan cosas durante meses e incluso se les puede entrenar con sonidos o colores." } } },
  { id: "k19", lvl: 1, type: "text", right: 3, t: { de: { q: "Welche Aussage ist FALSCH?", a: ["Krokodile lebten schon zur Zeit der Dinosaurier", "Eine Schnecke kriecht auf einem einzigen Fuß", "Hummeln können stechen", "Strauße stecken bei Gefahr den Kopf in den Sand"], x: "Ein Mythos: Strauße legen sich bei Gefahr flach auf den Boden – oder rennen mit bis zu 70 km/h davon." }, en: { q: "Which statement is FALSE?", a: ["Crocodiles already lived in the time of the dinosaurs", "A snail crawls on a single foot", "Bumblebees can sting", "Ostriches bury their heads in the sand when in danger"], x: "A myth: in danger, ostriches lie flat on the ground – or run away at up to 70 km/h." }, fr: { q: "Quelle affirmation est FAUSSE ?", a: ["Les crocodiles vivaient déjà à l’époque des dinosaures", "L’escargot rampe sur un seul pied", "Les bourdons peuvent piquer", "L’autruche cache sa tête dans le sable en cas de danger"], x: "Un mythe : en cas de danger, l’autruche se couche à plat sur le sol – ou s’enfuit à 70 km/h." }, es: { q: "¿Qué afirmación es FALSA?", a: ["Los cocodrilos ya vivían en tiempos de los dinosaurios", "El caracol se arrastra sobre un solo pie", "Los abejorros pueden picar", "El avestruz esconde la cabeza en la arena ante el peligro"], x: "Un mito: ante el peligro, el avestruz se tumba en el suelo o huye corriendo a hasta 70 km/h." } } },
  { id: "k20", lvl: 2, type: "text", right: 2, t: { de: { q: "Schätzfrage: Wie weit kann ein Chamäleon seine Zunge herausschnellen?", a: ["Halb so weit, wie es lang ist", "Etwa so weit, wie es lang ist", "Bis zu doppelt so weit, wie es lang ist", "Zehnmal so weit, wie es lang ist"], x: "Bis zur doppelten Körperlänge (ohne Schwanz) – und das in einem Bruchteil einer Sekunde. Die klebrige Zungenspitze hält auch große Insekten fest." }, en: { q: "Guess: how far can a chameleon shoot out its tongue?", a: ["Half its body length", "About its body length", "Up to twice its body length", "Ten times its body length"], x: "Up to twice its body length (without the tail) – in a fraction of a second. The sticky tongue tip holds even large insects." }, fr: { q: "Devine : jusqu’où un caméléon peut-il projeter sa langue ?", a: ["La moitié de sa longueur", "Environ sa longueur", "Jusqu’à deux fois sa longueur", "Dix fois sa longueur"], x: "Jusqu’à deux fois la longueur de son corps (sans la queue) – en une fraction de seconde. Le bout collant retient même de gros insectes." }, es: { q: "Adivina: ¿hasta dónde lanza un camaleón su lengua?", a: ["La mitad de su longitud", "Más o menos su longitud", "Hasta el doble de su longitud", "Diez veces su longitud"], x: "Hasta el doble de la longitud de su cuerpo (sin la cola), en una fracción de segundo. La punta pegajosa sujeta incluso insectos grandes." } } },
  { id: "k21", lvl: 3, type: "text", right: 3, t: { de: { q: "Schätzfrage: Wie viele Ameisen leben ungefähr auf der Erde?", a: ["Etwa 20 Millionen", "Etwa 20 Milliarden", "Etwa 20 Billionen", "Etwa 20 Billiarden"], x: "Forscher schätzten 2022: rund 20 Billiarden – eine 2 mit 16 Nullen. Das sind etwa 2,5 Millionen Ameisen pro Mensch." }, en: { q: "Guess: roughly how many ants live on Earth?", a: ["About 20 million", "About 20 billion", "About 20 trillion", "About 20 quadrillion"], x: "Researchers estimated in 2022: around 20 quadrillion – a 2 with 16 zeros. That’s about 2.5 million ants per person." }, fr: { q: "Devine : combien de fourmis vivent environ sur Terre ?", a: ["Environ 20 millions", "Environ 20 milliards", "Environ 20 000 milliards", "Environ 20 millions de milliards"], x: "Selon une estimation de 2022 : environ 20 millions de milliards – un 2 suivi de 16 zéros. Soit environ 2,5 millions de fourmis par personne." }, es: { q: "Adivina: ¿cuántas hormigas viven aproximadamente en la Tierra?", a: ["Unos 20 millones", "Unos 20.000 millones", "Unos 20 billones", "Unos 20.000 billones"], x: "Según una estimación de 2022: unos 20.000 billones, un 2 seguido de 16 ceros. Son unos 2,5 millones de hormigas por persona." } } },
  { id: "k22", lvl: 3, type: "text", right: 0, t: { de: { q: "Wofür sind die Streifen des Zebras nach heutigem Wissen am wahrscheinlichsten gut?", a: ["Sie halten stechende Fliegen fern", "Tarnung im hohen Gras", "Damit Löwen sie nicht von Felsen unterscheiden", "Gegen Sonnenbrand"], x: "Versuche zeigen: Bremsen landen auf gestreiften Flächen viel seltener – das Muster bringt sie beim Anflug durcheinander." }, en: { q: "According to current knowledge, what are zebra stripes most likely good for?", a: ["Keeping biting flies away", "Camouflage in tall grass", "So lions can’t tell them from rocks", "Against sunburn"], x: "Experiments show that horseflies land far less often on striped surfaces – the pattern confuses them as they approach." }, fr: { q: "Selon les connaissances actuelles, à quoi servent le plus probablement les rayures du zèbre ?", a: ["À éloigner les mouches piqueuses", "À se camoufler dans les hautes herbes", "À ressembler à des rochers pour les lions", "À éviter les coups de soleil"], x: "Des expériences le montrent : les taons se posent bien plus rarement sur des surfaces rayées – le motif les désoriente à l’approche." }, es: { q: "Según lo que se sabe hoy, ¿para qué sirven probablemente las rayas de la cebra?", a: ["Para alejar a las moscas que pican", "Para camuflarse en la hierba alta", "Para que los leones las confundan con rocas", "Contra las quemaduras del sol"], x: "Los experimentos muestran que los tábanos se posan mucho menos en superficies rayadas: el dibujo los confunde al acercarse." } } },
  { id: "k23", lvl: 2, type: "text", right: 0, t: { de: { q: "Wie verständigen sich Elefanten über viele Kilometer?", a: ["Mit sehr tiefen Tönen, die wir nicht hören", "Mit Ohrenwedeln als Lichtzeichen", "Mit Duftwolken im Wind", "Gar nicht – nur aus der Nähe"], x: "Elefanten brummen im Infraschall. Diese tiefen Töne reichen kilometerweit – andere Elefanten spüren sie sogar über die Füße im Boden." }, en: { q: "How do elephants communicate over many kilometres?", a: ["With very low sounds we can’t hear", "By flapping their ears as light signals", "With clouds of scent in the wind", "They don’t – only up close"], x: "Elephants rumble in infrasound. These deep sounds travel for kilometres – other elephants even feel them through their feet in the ground." }, fr: { q: "Comment les éléphants communiquent-ils sur des kilomètres ?", a: ["Avec des sons très graves que nous n’entendons pas", "En agitant les oreilles comme des signaux lumineux", "Avec des nuages d’odeurs dans le vent", "Pas du tout – seulement de près"], x: "Les éléphants grondent en infrasons. Ces sons graves portent sur des kilomètres – les autres éléphants les sentent même par les pieds, dans le sol." }, es: { q: "¿Cómo se comunican los elefantes a muchos kilómetros?", a: ["Con sonidos muy graves que no oímos", "Moviendo las orejas como señales", "Con nubes de olor en el viento", "No lo hacen: solo de cerca"], x: "Los elefantes emiten infrasonidos. Esos sonidos graves llegan a kilómetros, y otros elefantes los notan incluso con las patas a través del suelo." } } },
  { id: "t06", lvl: 2, type: "tf", right: 0, t: { de: { q: "Stimmt’s? Viele Schmetterlinge können erst fliegen, wenn sie sich aufgewärmt haben.", a: ["Wahr", "Falsch"], x: "Ihre Flugmuskeln brauchen Wärme. Darum sonnen sich Tagfalter morgens mit ausgebreiteten Flügeln oder zittern sich warm." }, en: { q: "True or false? Many butterflies can only fly once they have warmed up.", a: ["True", "False"], x: "Their flight muscles need warmth. That’s why butterflies sunbathe with open wings in the morning or shiver to warm up." }, fr: { q: "Vrai ou faux ? Beaucoup de papillons ne peuvent voler qu’après s’être réchauffés.", a: ["Vrai", "Faux"], x: "Leurs muscles de vol ont besoin de chaleur. C’est pourquoi les papillons se chauffent au soleil, ailes ouvertes, le matin, ou frissonnent pour se réchauffer." }, es: { q: "¿Verdadero o falso? Muchas mariposas solo pueden volar cuando se han calentado.", a: ["Verdadero", "Falso"], x: "Sus músculos de vuelo necesitan calor. Por eso, por la mañana, toman el sol con las alas abiertas o tiritan para calentarse." } } },
  { id: "t07", lvl: 3, type: "tf", right: 0, t: { de: { q: "Stimmt’s? Im Fell von Faultieren wachsen Algen.", a: ["Wahr", "Falsch"], x: "Ja – sie geben dem Fell einen grünlichen Schimmer, eine gute Tarnung im Regenwald. Sogar eigene Mottenarten leben darin." }, en: { q: "True or false? Algae grow in sloths’ fur.", a: ["True", "False"], x: "Yes – they give the fur a greenish tint, good camouflage in the rainforest. Even special kinds of moths live in it." }, fr: { q: "Vrai ou faux ? Des algues poussent dans la fourrure des paresseux.", a: ["Vrai", "Faux"], x: "Oui – elles donnent au pelage un reflet verdâtre, un bon camouflage dans la forêt tropicale. Des papillons de nuit spéciaux y vivent même." }, es: { q: "¿Verdadero o falso? En el pelo de los perezosos crecen algas.", a: ["Verdadero", "Falso"], x: "Sí, le dan al pelo un tono verdoso, buen camuflaje en la selva. Hasta viven en él polillas especiales." } } },
  { id: "t08", lvl: 3, type: "tf", right: 0, t: { de: { q: "Stimmt’s? Krokodile können ihre Zunge nicht herausstrecken.", a: ["Wahr", "Falsch"], x: "Ihre Zunge ist am Mundboden festgewachsen. Sie hilft beim Schlucken und dichtet zusammen mit einer Klappe den Rachen ab, wenn sie unter Wasser das Maul öffnen." }, en: { q: "True or false? Crocodiles can’t stick out their tongue.", a: ["True", "False"], x: "Their tongue is attached to the floor of the mouth. It helps with swallowing and, together with a flap, seals the throat when they open their mouth underwater." }, fr: { q: "Vrai ou faux ? Les crocodiles ne peuvent pas tirer la langue.", a: ["Vrai", "Faux"], x: "Leur langue est fixée au plancher de la bouche. Elle aide à avaler et, avec un clapet, ferme la gorge quand ils ouvrent la gueule sous l’eau." }, es: { q: "¿Verdadero o falso? Los cocodrilos no pueden sacar la lengua.", a: ["Verdadero", "Falso"], x: "Su lengua está unida al suelo de la boca. Ayuda a tragar y, junto con una válvula, cierra la garganta cuando abren la boca bajo el agua." } } },
  { id: "r01", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer rennt am schnellsten? Schnellstes zuerst.", a: ["Gepard", "Gabelbock", "Feldhase", "Mensch"], x: "Gepard bis etwa 110 km/h, Gabelbock fast 90, Feldhase rund 70 – und der schnellste Mensch knapp 45 km/h." }, en: { q: "Who runs fastest? Fastest first.", a: ["Cheetah", "Pronghorn", "Brown hare", "Human"], x: "Cheetah up to about 110 km/h, pronghorn almost 90, brown hare around 70 – and the fastest human just under 45 km/h." }, fr: { q: "Qui court le plus vite ? Le plus rapide d’abord.", a: ["Guépard", "Antilope d’Amérique", "Lièvre d’Europe", "Humain"], x: "Guépard jusqu’à environ 110 km/h, antilope d’Amérique près de 90, lièvre environ 70 – et l’humain le plus rapide un peu moins de 45 km/h." }, es: { q: "¿Quién corre más rápido? El más rápido primero.", a: ["Guepardo", "Berrendo", "Liebre europea", "Humano"], x: "Guepardo hasta unos 110 km/h, berrendo casi 90, liebre unos 70, y el humano más rápido algo menos de 45 km/h." } } },
  { id: "r02", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer ist in der Luft am schnellsten? Schnellstes zuerst.", a: ["Wanderfalke (Sturzflug)", "Steinadler (Sturzflug)", "Mauersegler", "Haussperling"], x: "Wanderfalke über 300 km/h, Steinadler rund 240 km/h im Sturzflug, Mauersegler über 100 km/h im Flug, Spatz etwa 40 km/h." }, en: { q: "Who is fastest in the air? Fastest first.", a: ["Peregrine falcon (dive)", "Golden eagle (dive)", "Common swift", "House sparrow"], x: "Peregrine falcon over 300 km/h, golden eagle around 240 km/h in a dive, swift over 100 km/h in flight, sparrow about 40 km/h." }, fr: { q: "Qui est le plus rapide dans les airs ? Le plus rapide d’abord.", a: ["Faucon pèlerin (en piqué)", "Aigle royal (en piqué)", "Martinet noir", "Moineau domestique"], x: "Faucon pèlerin plus de 300 km/h, aigle royal environ 240 km/h en piqué, martinet plus de 100 km/h en vol, moineau environ 40 km/h." }, es: { q: "¿Quién es más rápido en el aire? El más rápido primero.", a: ["Halcón peregrino (en picado)", "Águila real (en picado)", "Vencejo común", "Gorrión común"], x: "Halcón peregrino más de 300 km/h, águila real unos 240 km/h en picado, vencejo más de 100 km/h volando, gorrión unos 40 km/h." } } },
  { id: "r03", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer schwimmt am schnellsten? Schnellstes zuerst.", a: ["Schwertwal", "Kalifornischer Seelöwe", "Fischotter", "Mensch"], x: "Schwertwale schaffen gut 50 km/h, Seelöwen um 40, Fischotter gut 10 km/h. Die besten Schwimmer unter den Menschen kommen auf knapp 9 km/h." }, en: { q: "Who swims fastest? Fastest first.", a: ["Orca", "California sea lion", "Eurasian otter", "Human"], x: "Orcas reach over 50 km/h, sea lions around 40, otters just over 10 km/h. The best human swimmers manage just under 9 km/h." }, fr: { q: "Qui nage le plus vite ? Le plus rapide d’abord.", a: ["Orque", "Otarie de Californie", "Loutre d’Europe", "Humain"], x: "L’orque dépasse 50 km/h, l’otarie environ 40, la loutre un peu plus de 10 km/h. Les meilleurs nageurs humains atteignent à peine 9 km/h." }, es: { q: "¿Quién nada más rápido? El más rápido primero.", a: ["Orca", "León marino de California", "Nutria europea", "Humano"], x: "La orca supera los 50 km/h, el león marino unos 40 y la nutria algo más de 10 km/h. Los mejores nadadores humanos llegan a casi 9 km/h." } } },
  { id: "r04", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer ist am schwersten? Schwerstes zuerst.", a: ["Blauwal", "Afrikanischer Elefant", "Flusspferd", "Eisbär"], x: "Blauwal bis etwa 150 Tonnen, Elefantenbulle rund 6 Tonnen, Flusspferd 1,5 bis 3 Tonnen, Eisbär-Männchen 400 bis 700 kg." }, en: { q: "Who is heaviest? Heaviest first.", a: ["Blue whale", "African elephant", "Hippo", "Polar bear"], x: "Blue whale up to about 150 tonnes, bull elephant around 6 tonnes, hippo 1.5 to 3 tonnes, male polar bear 400 to 700 kg." }, fr: { q: "Qui est le plus lourd ? Le plus lourd d’abord.", a: ["Baleine bleue", "Éléphant d’Afrique", "Hippopotame", "Ours polaire"], x: "Baleine bleue jusqu’à environ 150 tonnes, éléphant mâle environ 6 tonnes, hippopotame 1,5 à 3 tonnes, ours polaire mâle 400 à 700 kg." }, es: { q: "¿Quién pesa más? El más pesado primero.", a: ["Ballena azul", "Elefante africano", "Hipopótamo", "Oso polar"], x: "Ballena azul hasta unas 150 toneladas, elefante macho unas 6 toneladas, hipopótamo de 1,5 a 3 toneladas, oso polar macho de 400 a 700 kg." } } },
  { id: "r05", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer wird am ältesten? Ältestes zuerst.", a: ["Grönlandhai", "Riesenschildkröte", "Asiatischer Elefant", "Hund"], x: "Grönlandhai mehrere hundert Jahre, Riesenschildkröten weit über 100, Elefanten bis etwa 70, Hunde meist 10 bis 15 Jahre." }, en: { q: "Who lives longest? Oldest first.", a: ["Greenland shark", "Giant tortoise", "Asian elephant", "Dog"], x: "Greenland shark several hundred years, giant tortoises well over 100, elephants up to about 70, dogs usually 10 to 15 years." }, fr: { q: "Qui vit le plus longtemps ? Le plus âgé d’abord.", a: ["Requin du Groenland", "Tortue géante", "Éléphant d’Asie", "Chien"], x: "Requin du Groenland plusieurs siècles, tortue géante bien plus de 100 ans, éléphant jusqu’à environ 70, chien en général 10 à 15 ans." }, es: { q: "¿Quién vive más años? El más longevo primero.", a: ["Tiburón de Groenlandia", "Tortuga gigante", "Elefante asiático", "Perro"], x: "Tiburón de Groenlandia varios siglos, tortuga gigante mucho más de 100 años, elefante hasta unos 70, perro normalmente de 10 a 15 años." } } },
  { id: "r06", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer schläft am längsten pro Tag? Längster Schlaf zuerst.", a: ["Koala", "Hauskatze", "Mensch", "Giraffe"], x: "Koalas schlafen bis zu 20 Stunden, Katzen 12 bis 16, Erwachsene etwa 8 – und Giraffen oft weniger als 4 Stunden, in kurzen Häppchen." }, en: { q: "Who sleeps longest each day? Longest sleep first.", a: ["Koala", "Pet cat", "Human", "Giraffe"], x: "Koalas sleep up to 20 hours, cats 12 to 16, adults about 8 – and giraffes often less than 4 hours, in short bits." }, fr: { q: "Qui dort le plus par jour ? Le plus gros dormeur d’abord.", a: ["Koala", "Chat domestique", "Humain", "Girafe"], x: "Le koala dort jusqu’à 20 heures, le chat 12 à 16, l’adulte environ 8 – et la girafe souvent moins de 4 heures, par petits morceaux." }, es: { q: "¿Quién duerme más al día? El más dormilón primero.", a: ["Koala", "Gato doméstico", "Humano", "Jirafa"], x: "El koala duerme hasta 20 horas, el gato de 12 a 16, un adulto unas 8, y la jirafa a menudo menos de 4 horas, a ratos." } } },
  { id: "r07", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer ist am höchsten (vom Boden bis zum Scheitel)? Höchstes zuerst.", a: ["Giraffe", "Afrikanischer Elefant", "Strauß", "Mensch"], x: "Giraffe bis 5,5 m, Elefant rund 4 m, Strauß bis etwa 2,7 m – der größte Vogel der Welt. Ein Mensch misst im Schnitt 1,70 m." }, en: { q: "Who is tallest (from the ground to the top of the head)? Tallest first.", a: ["Giraffe", "African elephant", "Ostrich", "Human"], x: "Giraffe up to 5.5 m, elephant around 4 m, ostrich up to about 2.7 m – the biggest bird in the world. A human averages 1.70 m." }, fr: { q: "Qui est le plus haut (du sol au sommet de la tête) ? Le plus haut d’abord.", a: ["Girafe", "Éléphant d’Afrique", "Autruche", "Humain"], x: "Girafe jusqu’à 5,5 m, éléphant environ 4 m, autruche jusqu’à 2,7 m environ – le plus grand oiseau du monde. Un humain mesure en moyenne 1,70 m." }, es: { q: "¿Quién es más alto (del suelo a la coronilla)? El más alto primero.", a: ["Jirafa", "Elefante africano", "Avestruz", "Humano"], x: "Jirafa hasta 5,5 m, elefante unos 4 m, avestruz hasta unos 2,7 m (el ave más grande del mundo). Un humano mide de media 1,70 m." } } },
  { id: "r08", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wessen Ei ist am schwersten? Schwerstes zuerst.", a: ["Strauß", "Emu", "Haushuhn", "Kolibri"], x: "Ein Straußenei wiegt rund 1,5 kg – so viel wie über 20 Hühnereier. Emu-Eier etwa 600 g, Hühnereier 60 g, Kolibri-Eier nur rund ein halbes Gramm." }, en: { q: "Whose egg is heaviest? Heaviest first.", a: ["Ostrich", "Emu", "Chicken", "Hummingbird"], x: "An ostrich egg weighs about 1.5 kg – as much as over 20 hen’s eggs. Emu eggs about 600 g, hen’s eggs 60 g, hummingbird eggs only about half a gram." }, fr: { q: "Quel œuf est le plus lourd ? Le plus lourd d’abord.", a: ["Autruche", "Émeu", "Poule", "Colibri"], x: "Un œuf d’autruche pèse environ 1,5 kg – autant que plus de 20 œufs de poule. Œuf d’émeu environ 600 g, de poule 60 g, de colibri un demi-gramme à peine." }, es: { q: "¿De quién es el huevo más pesado? El más pesado primero.", a: ["Avestruz", "Emú", "Gallina", "Colibrí"], x: "Un huevo de avestruz pesa unos 1,5 kg, tanto como más de 20 huevos de gallina. El de emú unos 600 g, el de gallina 60 g y el de colibrí apenas medio gramo." } } },
  { id: "r09", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer hat die meisten Beine? Die meisten zuerst.", a: ["Tausendfüßer", "Krabbe", "Kreuzspinne", "Maikäfer"], x: "Tausendfüßer haben je nach Art Dutzende bis Hunderte Beine (nie ganz 1000 – bis auf eine Art mit über 1300). Krabben haben 10, Spinnen 8, Käfer 6." }, en: { q: "Who has the most legs? Most first.", a: ["Millipede", "Crab", "Garden spider", "Cockchafer"], x: "Depending on the species, millipedes have dozens to hundreds of legs (one species has over 1,300). Crabs have 10, spiders 8, beetles 6." }, fr: { q: "Qui a le plus de pattes ? Le plus d’abord.", a: ["Mille-pattes", "Crabe", "Épeire diadème", "Hanneton"], x: "Selon l’espèce, le mille-pattes a des dizaines à des centaines de pattes (une espèce en a plus de 1300). Le crabe en a 10, l’araignée 8, le coléoptère 6." }, es: { q: "¿Quién tiene más patas? El que más primero.", a: ["Milpiés", "Cangrejo", "Araña de jardín", "Abejorro sanjuanero"], x: "Según la especie, el milpiés tiene de decenas a cientos de patas (una especie tiene más de 1.300). El cangrejo tiene 10, la araña 8 y el escarabajo 6." } } },
  { id: "r10", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer ist am längsten schwanger? Längste Tragzeit zuerst.", a: ["Afrikanischer Elefant", "Giraffe", "Mensch", "Hund"], x: "Elefanten tragen ihr Junges rund 22 Monate, Giraffen etwa 15, Menschen 9 – und Hunde nur gut 2 Monate." }, en: { q: "Who is pregnant the longest? Longest pregnancy first.", a: ["African elephant", "Giraffe", "Human", "Dog"], x: "Elephants carry their baby for about 22 months, giraffes about 15, humans 9 – and dogs only just over 2 months." }, fr: { q: "Qui porte son petit le plus longtemps ? La plus longue gestation d’abord.", a: ["Éléphant d’Afrique", "Girafe", "Humain", "Chien"], x: "L’éléphante porte son petit environ 22 mois, la girafe environ 15, l’humain 9 – et la chienne à peine plus de 2 mois." }, es: { q: "¿Quién tiene el embarazo más largo? El más largo primero.", a: ["Elefante africano", "Jirafa", "Humano", "Perro"], x: "La elefanta lleva a su cría unos 22 meses, la jirafa unos 15, el humano 9 y la perra solo algo más de 2 meses." } } },
  { id: "r11", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wessen Herz schlägt am schnellsten? Schnellstes zuerst.", a: ["Etruskerspitzmaus", "Hausmaus", "Mensch", "Blauwal"], x: "Die winzige Etruskerspitzmaus kommt auf über 1000 Schläge pro Minute, eine Maus auf 500 bis 600, ein Mensch auf etwa 70 – ein Blauwal beim Tauchen nur auf 2 bis 10." }, en: { q: "Whose heart beats fastest? Fastest first.", a: ["Etruscan shrew", "House mouse", "Human", "Blue whale"], x: "The tiny Etruscan shrew reaches over 1,000 beats a minute, a mouse 500 to 600, a human about 70 – a diving blue whale only 2 to 10." }, fr: { q: "Quel cœur bat le plus vite ? Le plus rapide d’abord.", a: ["Pachyure étrusque", "Souris domestique", "Humain", "Baleine bleue"], x: "La minuscule pachyure étrusque dépasse 1000 battements par minute, la souris 500 à 600, l’humain environ 70 – la baleine bleue en plongée seulement 2 à 10." }, es: { q: "¿Qué corazón late más rápido? El más rápido primero.", a: ["Musgaño enano", "Ratón doméstico", "Humano", "Ballena azul"], x: "El diminuto musgaño enano supera los 1.000 latidos por minuto, el ratón de 500 a 600, el humano unos 70 y la ballena azul al bucear solo de 2 a 10." } } },
  { id: "r12", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wessen Baby ist bei der Geburt am schwersten? Schwerstes zuerst.", a: ["Blauwal", "Afrikanischer Elefant", "Mensch", "Großer Panda"], x: "Ein Blauwalkalb wiegt rund 2,5 Tonnen, ein Elefantenbaby etwa 100 kg, ein Menschenbaby 3,5 kg – ein Pandababy nur rund 100 Gramm." }, en: { q: "Whose baby is heaviest at birth? Heaviest first.", a: ["Blue whale", "African elephant", "Human", "Giant panda"], x: "A blue whale calf weighs about 2.5 tonnes, a baby elephant about 100 kg, a human baby 3.5 kg – a panda cub only around 100 grams." }, fr: { q: "Quel bébé est le plus lourd à la naissance ? Le plus lourd d’abord.", a: ["Baleine bleue", "Éléphant d’Afrique", "Humain", "Panda géant"], x: "Un baleineau bleu pèse environ 2,5 tonnes, un éléphanteau environ 100 kg, un bébé humain 3,5 kg – un bébé panda à peine 100 grammes." }, es: { q: "¿Qué cría pesa más al nacer? La más pesada primero.", a: ["Ballena azul", "Elefante africano", "Humano", "Panda gigante"], x: "Una cría de ballena azul pesa unas 2,5 toneladas, la de elefante unos 100 kg, un bebé humano 3,5 kg y una cría de panda solo unos 100 gramos." } } },
  { id: "r13", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer fliegt am höchsten? Höchstes zuerst.", a: ["Sperbergeier", "Streifengans", "Weißstorch", "Amsel"], x: "Ein Sperbergeier stieß 1973 in über 11.000 m Höhe mit einem Flugzeug zusammen. Streifengänse überqueren den Himalaya in 7.000 bis 8.000 m. Störche ziehen meist in einigen hundert bis tausend Metern, Amseln bleiben nah am Boden." }, en: { q: "Who flies highest? Highest first.", a: ["Rüppell’s vulture", "Bar-headed goose", "White stork", "Blackbird"], x: "In 1973 a Rüppell’s vulture collided with a plane at over 11,000 m. Bar-headed geese cross the Himalayas at 7,000 to 8,000 m. Storks usually migrate at a few hundred to a thousand metres; blackbirds stay close to the ground." }, fr: { q: "Qui vole le plus haut ? Le plus haut d’abord.", a: ["Vautour de Rüppell", "Oie à tête barrée", "Cigogne blanche", "Merle noir"], x: "En 1973, un vautour de Rüppell a percuté un avion à plus de 11 000 m. L’oie à tête barrée franchit l’Himalaya à 7 000–8 000 m. La cigogne migre en général à quelques centaines ou milliers de mètres, le merle reste près du sol." }, es: { q: "¿Quién vuela más alto? El más alto primero.", a: ["Buitre moteado", "Ánsar indio", "Cigüeña blanca", "Mirlo"], x: "En 1973 un buitre moteado chocó con un avión a más de 11.000 m. El ánsar indio cruza el Himalaya a 7.000-8.000 m. La cigüeña migra normalmente a unos cientos o mil metros; el mirlo se queda cerca del suelo." } } },
  { id: "r14", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer taucht am tiefsten? Tiefstes zuerst.", a: ["Cuvier-Schnabelwal", "Pottwal", "Kaiserpinguin", "Mensch (ohne Gerät)"], x: "Cuvier-Schnabelwale tauchen fast 3.000 m tief, Pottwale über 2.000 m, Kaiserpinguine über 500 m. Freitaucher schaffen gut 100 m." }, en: { q: "Who dives deepest? Deepest first.", a: ["Cuvier’s beaked whale", "Sperm whale", "Emperor penguin", "Human (no equipment)"], x: "Cuvier’s beaked whales dive almost 3,000 m deep, sperm whales over 2,000 m, emperor penguins over 500 m. Free divers manage just over 100 m." }, fr: { q: "Qui plonge le plus profond ? Le plus profond d’abord.", a: ["Baleine de Cuvier", "Cachalot", "Manchot empereur", "Humain (sans matériel)"], x: "La baleine de Cuvier plonge à près de 3 000 m, le cachalot à plus de 2 000 m, le manchot empereur à plus de 500 m. Les apnéistes dépassent à peine 100 m." }, es: { q: "¿Quién bucea más hondo? El más profundo primero.", a: ["Zifio de Cuvier", "Cachalote", "Pingüino emperador", "Humano (sin equipo)"], x: "El zifio de Cuvier baja a casi 3.000 m, el cachalote a más de 2.000 m, el pingüino emperador a más de 500 m. Los apneístas pasan por poco de 100 m." } } },
  { id: "r15", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer hat die meisten Zähne? Die meisten zuerst.", a: ["Großer Tümmler", "Hund", "Mensch", "Großer Ameisenbär"], x: "Große Tümmler haben 80 bis 100 Zähne, Hunde 42, erwachsene Menschen 32. Der Ameisenbär hat gar keine – er schleckt Ameisen mit seiner langen Zunge auf." }, en: { q: "Who has the most teeth? Most first.", a: ["Bottlenose dolphin", "Dog", "Human", "Giant anteater"], x: "Bottlenose dolphins have 80 to 100 teeth, dogs 42, adult humans 32. The anteater has none at all – it licks up ants with its long tongue." }, fr: { q: "Qui a le plus de dents ? Le plus d’abord.", a: ["Grand dauphin", "Chien", "Humain", "Grand fourmilier"], x: "Le grand dauphin a 80 à 100 dents, le chien 42, l’humain adulte 32. Le fourmilier n’en a aucune – il lape les fourmis avec sa longue langue." }, es: { q: "¿Quién tiene más dientes? El que más primero.", a: ["Delfín mular", "Perro", "Humano", "Oso hormiguero gigante"], x: "El delfín mular tiene de 80 a 100 dientes, el perro 42 y el humano adulto 32. El oso hormiguero no tiene ninguno: atrapa las hormigas con su larga lengua." } } },
  { id: "r16", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer beißt am stärksten zu? Stärkstes zuerst.", a: ["Leistenkrokodil", "Flusspferd", "Löwe", "Mensch"], x: "Das Leistenkrokodil hat den stärksten je gemessenen Biss, etwa doppelt so stark wie ein Flusspferd. Ein Löwe beißt deutlich schwächer, ein Mensch nur mit einem Bruchteil davon." }, en: { q: "Who has the strongest bite? Strongest first.", a: ["Saltwater crocodile", "Hippo", "Lion", "Human"], x: "The saltwater crocodile has the strongest bite ever measured, about twice as strong as a hippo’s. A lion bites much more weakly, a human with just a fraction of that." }, fr: { q: "Qui a la morsure la plus puissante ? La plus forte d’abord.", a: ["Crocodile marin", "Hippopotame", "Lion", "Humain"], x: "Le crocodile marin a la morsure la plus forte jamais mesurée, environ deux fois celle de l’hippopotame. Le lion mord bien moins fort, l’humain avec une fraction seulement." }, es: { q: "¿Quién muerde con más fuerza? El más fuerte primero.", a: ["Cocodrilo marino", "Hipopótamo", "León", "Humano"], x: "El cocodrilo marino tiene la mordida más fuerte jamás medida, unas dos veces la del hipopótamo. El león muerde mucho más flojo y el humano con solo una fracción." } } },
  { id: "r17", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer hat die größte Flügelspannweite? Größte zuerst.", a: ["Wanderalbatros", "Andenkondor", "Weißstorch", "Amsel"], x: "Wanderalbatrosse messen bis 3,5 m von Flügelspitze zu Flügelspitze, Andenkondore gut 3 m, Störche etwa 2 m, Amseln knapp 40 cm." }, en: { q: "Who has the largest wingspan? Largest first.", a: ["Wandering albatross", "Andean condor", "White stork", "Blackbird"], x: "Wandering albatrosses measure up to 3.5 m from wingtip to wingtip, Andean condors just over 3 m, storks about 2 m, blackbirds just under 40 cm." }, fr: { q: "Qui a la plus grande envergure ? La plus grande d’abord.", a: ["Albatros hurleur", "Condor des Andes", "Cigogne blanche", "Merle noir"], x: "L’albatros hurleur mesure jusqu’à 3,5 m d’une pointe d’aile à l’autre, le condor un peu plus de 3 m, la cigogne environ 2 m, le merle à peine 40 cm." }, es: { q: "¿Quién tiene mayor envergadura? La mayor primero.", a: ["Albatros viajero", "Cóndor andino", "Cigüeña blanca", "Mirlo"], x: "El albatros viajero mide hasta 3,5 m de punta a punta de ala, el cóndor andino algo más de 3 m, la cigüeña unos 2 m y el mirlo poco menos de 40 cm." } } },
  { id: "r18", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer ist am längsten? Längstes zuerst.", a: ["Blauwal", "Walhai", "Weißer Hai", "Großer Tümmler"], x: "Blauwale werden bis 30 m lang, Walhaie – die größten Fische – über 12 m, Weiße Haie bis etwa 6 m, Große Tümmler 2 bis 4 m." }, en: { q: "Who is longest? Longest first.", a: ["Blue whale", "Whale shark", "Great white shark", "Bottlenose dolphin"], x: "Blue whales grow up to 30 m long, whale sharks – the biggest fish – over 12 m, great whites up to about 6 m, bottlenose dolphins 2 to 4 m." }, fr: { q: "Qui est le plus long ? Le plus long d’abord.", a: ["Baleine bleue", "Requin-baleine", "Grand requin blanc", "Grand dauphin"], x: "La baleine bleue atteint 30 m, le requin-baleine – le plus grand poisson – plus de 12 m, le grand requin blanc environ 6 m, le grand dauphin 2 à 4 m." }, es: { q: "¿Quién es más largo? El más largo primero.", a: ["Ballena azul", "Tiburón ballena", "Tiburón blanco", "Delfín mular"], x: "La ballena azul llega a 30 m, el tiburón ballena (el pez más grande) a más de 12 m, el tiburón blanco a unos 6 m y el delfín mular a 2-4 m." } } },
  { id: "r19", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer ist am LANGSAMSTEN unterwegs? Langsamstes zuerst.", a: ["Gartenschnecke", "Dreifingerfaultier", "Spazierender Mensch", "Galoppierendes Pferd"], x: "Eine Schnecke schafft nur ein paar Meter pro Stunde, ein Faultier etwa 200 bis 250 m. Ein Mensch spaziert mit rund 5 km/h, ein Pferd galoppiert mit über 40 km/h." }, en: { q: "Who moves the SLOWEST? Slowest first.", a: ["Garden snail", "Three-toed sloth", "Walking human", "Galloping horse"], x: "A snail manages only a few metres an hour, a sloth about 200 to 250 m. A human walks at about 5 km/h, a horse gallops at over 40 km/h." }, fr: { q: "Qui avance le plus LENTEMENT ? Le plus lent d’abord.", a: ["Escargot des jardins", "Paresseux à trois doigts", "Humain qui se promène", "Cheval au galop"], x: "L’escargot ne fait que quelques mètres par heure, le paresseux environ 200 à 250 m. L’humain marche à environ 5 km/h, le cheval galope à plus de 40 km/h." }, es: { q: "¿Quién va más LENTO? El más lento primero.", a: ["Caracol de jardín", "Perezoso de tres dedos", "Humano paseando", "Caballo al galope"], x: "Un caracol solo avanza unos metros por hora, un perezoso unos 200-250 m. Un humano pasea a unos 5 km/h y un caballo galopa a más de 40 km/h." } } },
  { id: "r20", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer hört die höchsten Töne? Höchste zuerst.", a: ["Fledermaus", "Delfin", "Hund", "Mensch"], x: "Manche Fledermäuse hören über 200.000 Schwingungen pro Sekunde (200 kHz), Delfine bis etwa 150 kHz, Hunde rund 45 kHz. Menschen hören höchstens bis 20 kHz – im Alter weniger." }, en: { q: "Who hears the highest sounds? Highest first.", a: ["Bat", "Dolphin", "Dog", "Human"], x: "Some bats hear over 200,000 vibrations a second (200 kHz), dolphins up to about 150 kHz, dogs around 45 kHz. Humans hear up to 20 kHz at most – less with age." }, fr: { q: "Qui entend les sons les plus aigus ? Le plus aigu d’abord.", a: ["Chauve-souris", "Dauphin", "Chien", "Humain"], x: "Certaines chauves-souris entendent plus de 200 000 vibrations par seconde (200 kHz), le dauphin jusqu’à environ 150 kHz, le chien environ 45 kHz. L’humain entend au mieux jusqu’à 20 kHz – moins avec l’âge." }, es: { q: "¿Quién oye los sonidos más agudos? El más agudo primero.", a: ["Murciélago", "Delfín", "Perro", "Humano"], x: "Algunos murciélagos oyen más de 200.000 vibraciones por segundo (200 kHz), el delfín hasta unos 150 kHz, el perro unos 45 kHz. El humano oye como mucho hasta 20 kHz, y menos con la edad." } } },
  { id: "r21", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wessen Körper ist am wärmsten? Wärmster zuerst.", a: ["Haushuhn", "Hund", "Mensch", "Schnabeltier"], x: "Vögel sind besonders warm: Hühner um 41 °C. Hunde haben etwa 38,5 °C, Menschen 37 °C, das Schnabeltier nur rund 32 °C." }, en: { q: "Whose body is warmest? Warmest first.", a: ["Chicken", "Dog", "Human", "Platypus"], x: "Birds are especially warm: chickens around 41 °C. Dogs are about 38.5 °C, humans 37 °C, the platypus only around 32 °C." }, fr: { q: "Quel corps est le plus chaud ? Le plus chaud d’abord.", a: ["Poule", "Chien", "Humain", "Ornithorynque"], x: "Les oiseaux sont très chauds : la poule environ 41 °C. Le chien a environ 38,5 °C, l’humain 37 °C, l’ornithorynque à peine 32 °C." }, es: { q: "¿Qué cuerpo está más caliente? El más caliente primero.", a: ["Gallina", "Perro", "Humano", "Ornitorrinco"], x: "Las aves son muy calientes: la gallina unos 41 °C. El perro tiene unos 38,5 °C, el humano 37 °C y el ornitorrinco solo unos 32 °C." } } },
  { id: "r22", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer war zuerst auf der Erde? Ältestes zuerst.", a: ["Quallen", "Haie", "Dinosaurier", "Menschen"], x: "Quallen gibt es seit über 500 Millionen Jahren, Haie seit über 400 Millionen, Dinosaurier tauchten vor rund 230 Millionen Jahren auf – unsere Art erst vor etwa 300.000 Jahren." }, en: { q: "Who was on Earth first? Oldest first.", a: ["Jellyfish", "Sharks", "Dinosaurs", "Humans"], x: "Jellyfish have existed for over 500 million years, sharks for over 400 million, dinosaurs appeared about 230 million years ago – our species only about 300,000 years ago." }, fr: { q: "Qui était sur Terre en premier ? Le plus ancien d’abord.", a: ["Méduses", "Requins", "Dinosaures", "Humains"], x: "Les méduses existent depuis plus de 500 millions d’années, les requins depuis plus de 400 millions, les dinosaures sont apparus il y a environ 230 millions d’années – notre espèce il y a environ 300 000 ans." }, es: { q: "¿Quién llegó antes a la Tierra? El más antiguo primero.", a: ["Medusas", "Tiburones", "Dinosaurios", "Humanos"], x: "Las medusas existen desde hace más de 500 millones de años, los tiburones desde hace más de 400 millones, los dinosaurios aparecieron hace unos 230 millones y nuestra especie hace solo unos 300.000 años." } } },
  { id: "r23", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer bekommt pro Jahr die meisten Jungen? Die meisten zuerst.", a: ["Hausmaus", "Wildkaninchen", "Rotfuchs", "Afrikanischer Elefant"], x: "Hausmäuse schaffen bis zu 50 Junge im Jahr, Wildkaninchen 20 bis 30, Füchse einen Wurf mit 4 bis 6. Eine Elefantenkuh bekommt nur etwa alle 4 bis 5 Jahre ein Kalb." }, en: { q: "Who has the most babies per year? Most first.", a: ["House mouse", "Wild rabbit", "Red fox", "African elephant"], x: "House mice can have up to 50 young a year, wild rabbits 20 to 30, foxes one litter of 4 to 6. An elephant cow has a calf only about every 4 to 5 years." }, fr: { q: "Qui a le plus de petits par an ? Le plus d’abord.", a: ["Souris domestique", "Lapin de garenne", "Renard roux", "Éléphant d’Afrique"], x: "La souris peut avoir jusqu’à 50 petits par an, le lapin de garenne 20 à 30, le renard une portée de 4 à 6. Une éléphante n’a un petit qu’environ tous les 4 à 5 ans." }, es: { q: "¿Quién tiene más crías al año? El que más primero.", a: ["Ratón doméstico", "Conejo silvestre", "Zorro rojo", "Elefante africano"], x: "El ratón puede tener hasta 50 crías al año, el conejo de 20 a 30 y el zorro una camada de 4 a 6. Una elefanta solo tiene una cría cada 4 o 5 años." } } },
  { id: "r24", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Welcher Vogel ist am schwersten? Schwerster zuerst.", a: ["Strauß", "Kaiserpinguin", "Höckerschwan", "Steinadler"], x: "Strauße wiegen über 100 kg, Kaiserpinguine 20 bis 40 kg, Höckerschwäne um 10 kg – einer der schwersten fliegenden Vögel. Steinadler bringen 3 bis 6 kg auf die Waage." }, en: { q: "Which bird is heaviest? Heaviest first.", a: ["Ostrich", "Emperor penguin", "Mute swan", "Golden eagle"], x: "Ostriches weigh over 100 kg, emperor penguins 20 to 40 kg, mute swans around 10 kg – one of the heaviest flying birds. Golden eagles weigh 3 to 6 kg." }, fr: { q: "Quel oiseau est le plus lourd ? Le plus lourd d’abord.", a: ["Autruche", "Manchot empereur", "Cygne tuberculé", "Aigle royal"], x: "L’autruche dépasse 100 kg, le manchot empereur pèse 20 à 40 kg, le cygne environ 10 kg – l’un des plus lourds oiseaux volants. L’aigle royal pèse 3 à 6 kg." }, es: { q: "¿Qué ave pesa más? La más pesada primero.", a: ["Avestruz", "Pingüino emperador", "Cisne vulgar", "Águila real"], x: "El avestruz supera los 100 kg, el pingüino emperador pesa de 20 a 40 kg, el cisne unos 10 kg (una de las aves voladoras más pesadas). El águila real pesa de 3 a 6 kg." } } },
  { id: "r25", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer lebt als erwachsenes Tier am KÜRZESTEN? Kürzestes Leben zuerst.", a: ["Eintagsfliege", "Sommer-Arbeitsbiene", "Hausmaus", "Hauskatze"], x: "Erwachsene Eintagsfliegen leben oft nur Stunden bis wenige Tage – als Larve aber bis zu drei Jahre. Arbeitsbienen im Sommer etwa 6 Wochen, Mäuse 1 bis 2 Jahre, Katzen um 15 Jahre." }, en: { q: "Who lives the SHORTEST as an adult? Shortest life first.", a: ["Mayfly", "Summer worker bee", "House mouse", "Pet cat"], x: "Adult mayflies often live only hours to a few days – but up to three years as larvae. Summer worker bees about 6 weeks, mice 1 to 2 years, cats around 15 years." }, fr: { q: "Qui vit le moins longtemps à l’âge adulte ? La vie la plus courte d’abord.", a: ["Éphémère", "Abeille ouvrière d’été", "Souris domestique", "Chat domestique"], x: "L’éphémère adulte ne vit souvent que quelques heures à quelques jours – mais jusqu’à trois ans à l’état de larve. L’ouvrière d’été environ 6 semaines, la souris 1 à 2 ans, le chat environ 15 ans." }, es: { q: "¿Quién vive MENOS de adulto? La vida más corta primero.", a: ["Efímera", "Abeja obrera de verano", "Ratón doméstico", "Gato doméstico"], x: "La efímera adulta suele vivir de horas a pocos días, pero como larva hasta tres años. La obrera de verano unas 6 semanas, el ratón de 1 a 2 años y el gato unos 15 años." } } },
  { id: "r26", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer legt auf einmal die meisten Eier? Die meisten zuerst.", a: ["Mondfisch", "Erdkröte", "Meeresschildkröte", "Kaiserpinguin"], x: "Ein Mondfisch-Weibchen kann rund 300 Millionen Eier tragen, eine Erdkröte legt Schnüre mit einigen tausend, Meeresschildkröten etwa 100 pro Gelege, Kaiserpinguine genau eins." }, en: { q: "Who lays the most eggs at once? Most first.", a: ["Ocean sunfish", "Common toad", "Sea turtle", "Emperor penguin"], x: "A female ocean sunfish can carry around 300 million eggs, a common toad lays strings with a few thousand, sea turtles about 100 per clutch, emperor penguins exactly one." }, fr: { q: "Qui pond le plus d’œufs en une fois ? Le plus d’abord.", a: ["Poisson-lune", "Crapaud commun", "Tortue marine", "Manchot empereur"], x: "Une femelle poisson-lune peut porter environ 300 millions d’œufs, le crapaud pond des cordons de quelques milliers, la tortue marine environ 100 par ponte, le manchot empereur un seul." }, es: { q: "¿Quién pone más huevos de una vez? El que más primero.", a: ["Pez luna", "Sapo común", "Tortuga marina", "Pingüino emperador"], x: "Una hembra de pez luna puede llevar unos 300 millones de huevos, el sapo pone cordones con unos miles, la tortuga marina unos 100 por puesta y el pingüino emperador, uno solo." } } },
  { id: "r27", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer ist am kleinsten? Kleinstes zuerst.", a: ["Bienenelfe (Kolibri)", "Feldmaus", "Eichhörnchen", "Rotfuchs"], x: "Die Bienenelfe ist mit gut 5 cm der kleinste Vogel der Welt. Eine Feldmaus misst etwa 10 cm, ein Eichhörnchen gut 20 cm (ohne Schwanz), ein Fuchs rund 70 cm." }, en: { q: "Who is smallest? Smallest first.", a: ["Bee hummingbird", "Common vole", "Red squirrel", "Red fox"], x: "At just over 5 cm, the bee hummingbird is the smallest bird in the world. A vole is about 10 cm, a squirrel just over 20 cm (without tail), a fox around 70 cm." }, fr: { q: "Qui est le plus petit ? Le plus petit d’abord.", a: ["Colibri d’Elena", "Campagnol des champs", "Écureuil roux", "Renard roux"], x: "Avec à peine plus de 5 cm, le colibri d’Elena est le plus petit oiseau du monde. Le campagnol mesure environ 10 cm, l’écureuil un peu plus de 20 cm (sans la queue), le renard environ 70 cm." }, es: { q: "¿Quién es más pequeño? El más pequeño primero.", a: ["Colibrí zunzuncito", "Topillo campesino", "Ardilla roja", "Zorro rojo"], x: "Con algo más de 5 cm, el zunzuncito es el ave más pequeña del mundo. Un topillo mide unos 10 cm, una ardilla algo más de 20 cm (sin cola) y un zorro unos 70 cm." } } },
  { id: "r28", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer kann am längsten unter Wasser bleiben? Längste Zeit zuerst.", a: ["Cuvier-Schnabelwal", "Südlicher See-Elefant", "Großer Tümmler", "Fischotter"], x: "Rekord: ein Cuvier-Schnabelwal blieb fast 4 Stunden unten. See-Elefanten schaffen bis etwa 2 Stunden, Große Tümmler meist unter 10 Minuten, Fischotter wenige Minuten." }, en: { q: "Who can stay underwater longest? Longest first.", a: ["Cuvier’s beaked whale", "Southern elephant seal", "Bottlenose dolphin", "Eurasian otter"], x: "Record: a Cuvier’s beaked whale stayed down for almost 4 hours. Elephant seals manage up to about 2 hours, bottlenose dolphins usually under 10 minutes, otters a few minutes." }, fr: { q: "Qui peut rester le plus longtemps sous l’eau ? Le plus long d’abord.", a: ["Baleine de Cuvier", "Éléphant de mer du Sud", "Grand dauphin", "Loutre d’Europe"], x: "Record : une baleine de Cuvier est restée près de 4 heures sous l’eau. L’éléphant de mer tient jusqu’à environ 2 heures, le grand dauphin en général moins de 10 minutes, la loutre quelques minutes." }, es: { q: "¿Quién aguanta más bajo el agua? El que más primero.", a: ["Zifio de Cuvier", "Elefante marino del sur", "Delfín mular", "Nutria europea"], x: "Récord: un zifio de Cuvier estuvo casi 4 horas sumergido. El elefante marino aguanta hasta unas 2 horas, el delfín mular normalmente menos de 10 minutos y la nutria unos minutos." } } },
  { id: "r29", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer ist an Land am schnellsten? Schnellstes zuerst.", a: ["Strauß", "Rotfuchs", "Eichhörnchen", "Igel"], x: "Strauße laufen bis 70 km/h – der schnellste Vogel zu Fuß. Füchse schaffen etwa 50, Eichhörnchen gut 20 km/h. Ein Igel trippelt höchstens rund 9 km/h." }, en: { q: "Who is fastest on land? Fastest first.", a: ["Ostrich", "Red fox", "Red squirrel", "Hedgehog"], x: "Ostriches run up to 70 km/h – the fastest bird on foot. Foxes manage about 50, squirrels just over 20 km/h. A hedgehog scurries at about 9 km/h at most." }, fr: { q: "Qui est le plus rapide sur terre ? Le plus rapide d’abord.", a: ["Autruche", "Renard roux", "Écureuil roux", "Hérisson"], x: "L’autruche court jusqu’à 70 km/h – l’oiseau le plus rapide à pied. Le renard atteint environ 50, l’écureuil un peu plus de 20 km/h. Le hérisson trottine à 9 km/h au plus." }, es: { q: "¿Quién es más rápido en tierra? El más rápido primero.", a: ["Avestruz", "Zorro rojo", "Ardilla roja", "Erizo"], x: "El avestruz corre hasta 70 km/h, el ave más rápida a pie. El zorro llega a unos 50 y la ardilla a algo más de 20 km/h. El erizo trota como mucho a unos 9 km/h." } } },
  { id: "r30", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wessen Gehirn ist am schwersten? Schwerstes zuerst.", a: ["Pottwal", "Afrikanischer Elefant", "Mensch", "Schimpanse"], x: "Das Pottwal-Gehirn wiegt rund 8 kg – das schwerste im Tierreich. Elefanten haben etwa 5 kg, Menschen 1,3 bis 1,4 kg, Schimpansen knapp 400 g." }, en: { q: "Whose brain is heaviest? Heaviest first.", a: ["Sperm whale", "African elephant", "Human", "Chimpanzee"], x: "A sperm whale’s brain weighs about 8 kg – the heaviest in the animal kingdom. Elephants have about 5 kg, humans 1.3 to 1.4 kg, chimpanzees just under 400 g." }, fr: { q: "Quel cerveau est le plus lourd ? Le plus lourd d’abord.", a: ["Cachalot", "Éléphant d’Afrique", "Humain", "Chimpanzé"], x: "Le cerveau du cachalot pèse environ 8 kg – le plus lourd du règne animal. L’éléphant en a environ 5 kg, l’humain 1,3 à 1,4 kg, le chimpanzé à peine 400 g." }, es: { q: "¿Qué cerebro pesa más? El más pesado primero.", a: ["Cachalote", "Elefante africano", "Humano", "Chimpancé"], x: "El cerebro del cachalote pesa unos 8 kg, el más pesado del reino animal. El del elefante unos 5 kg, el humano de 1,3 a 1,4 kg y el del chimpancé poco menos de 400 g." } } },
  { id: "a01", lvl: 1, type: "text", right: 1, t: { de: { q: "Welcher heimische Vogel kann kopfüber einen Baumstamm hinunterlaufen?", a: ["Buntspecht", "Kleiber", "Gartenbaumläufer", "Kohlmeise"], x: "Der Kleiber klettert als einziger heimischer Vogel auch kopfüber abwärts. Spechte und Baumläufer klettern nur aufwärts." }, en: { q: "Which bird native to Central Europe can walk head-first down a tree trunk?", a: ["Great spotted woodpecker", "Nuthatch", "Short-toed treecreeper", "Great tit"], x: "The nuthatch is the only native bird that also climbs head-first downwards. Woodpeckers and treecreepers only climb up." }, fr: { q: "Quel oiseau d'Europe centrale peut descendre un tronc la tête en bas ?", a: ["Pic épeiche", "Sittelle torchepot", "Grimpereau des jardins", "Mésange charbonnière"], x: "La sittelle est le seul oiseau de chez nous à descendre les troncs tête en bas. Pics et grimpereaux ne font que monter." }, es: { q: "¿Qué ave de Europa central puede bajar por un tronco cabeza abajo?", a: ["Pico picapinos", "Trepador azul", "Agateador europeo", "Carbonero común"], x: "El trepador azul es la única ave autóctona que baja por los troncos cabeza abajo. Pájaros carpinteros y agateadores solo suben." } } },
  { id: "a02", lvl: 1, type: "tf", right: 1, t: { de: { q: "Milch ist ein gutes Futter für Igel.", a: ["Wahr", "Falsch"], x: "Igel vertragen keinen Milchzucker und bekommen von Milch Durchfall. Wasser ist das richtige Getränk für sie." }, en: { q: "Milk is good food for hedgehogs.", a: ["True", "False"], x: "Hedgehogs can't digest milk sugar (lactose); milk gives them diarrhoea. Water is the right drink for them." }, fr: { q: "Le lait est une bonne nourriture pour les hérissons.", a: ["Vrai", "Faux"], x: "Les hérissons ne digèrent pas le lactose : le lait leur donne la diarrhée. L'eau est la bonne boisson pour eux." }, es: { q: "La leche es un buen alimento para los erizos.", a: ["Verdadero", "Falso"], x: "Los erizos no toleran la lactosa y la leche les provoca diarrea. Lo adecuado es darles agua." } } },
  { id: "a03", lvl: 1, type: "tf", right: 0, t: { de: { q: "Fledermäuse sind die einzigen Säugetiere, die aktiv fliegen können.", a: ["Wahr", "Falsch"], x: "Stimmt! Flughörnchen gleiten nur. Fledermäuse fliegen mit echten Flügeln aus Flughaut zwischen ihren langen Fingern." }, en: { q: "Bats are the only mammals capable of true powered flight.", a: ["True", "False"], x: "True! Flying squirrels only glide. Bats fly with real wings made of skin stretched between their long fingers." }, fr: { q: "Les chauves-souris sont les seuls mammifères capables de vrai vol battu.", a: ["Vrai", "Faux"], x: "Vrai ! Les écureuils volants ne font que planer. Les chauves-souris volent avec une membrane tendue entre leurs longs doigts." }, es: { q: "Los murciélagos son los únicos mamíferos capaces de volar activamente.", a: ["Verdadero", "Falso"], x: "¡Cierto! Las ardillas voladoras solo planean. Los murciélagos vuelan con una membrana de piel entre sus largos dedos." } } },
  { id: "a04", lvl: 1, type: "text", right: 2, t: { de: { q: "Um wie viel Grad kann eine Eule ihren Kopf etwa drehen?", a: ["90 Grad", "180 Grad", "270 Grad", "360 Grad"], x: "Eulen drehen den Kopf bis etwa 270 Grad. Das gleicht aus, dass sie ihre großen Augen kaum bewegen können." }, en: { q: "About how far can an owl turn its head?", a: ["90 degrees", "180 degrees", "270 degrees", "360 degrees"], x: "Owls can turn their heads about 270 degrees. This makes up for their large eyes, which can barely move." }, fr: { q: "De combien de degrés une chouette peut-elle tourner la tête environ ?", a: ["90 degrés", "180 degrés", "270 degrés", "360 degrés"], x: "Les chouettes tournent la tête d'environ 270 degrés, car leurs grands yeux ne bougent presque pas." }, es: { q: "¿Aproximadamente cuántos grados puede girar la cabeza un búho?", a: ["90 grados", "180 grados", "270 grados", "360 grados"], x: "Los búhos giran la cabeza unos 270 grados, porque sus grandes ojos apenas pueden moverse." } } },
  { id: "a05", lvl: 1, type: "text", right: 1, t: { de: { q: "Welcher Vogel erreicht im Sturzflug mehr als 300 km/h?", a: ["Turmfalke", "Wanderfalke", "Mauersegler", "Habicht"], x: "Der Wanderfalke stößt mit über 300 km/h auf Beute herab und gilt damit als schnellstes Tier der Welt." }, en: { q: "Which bird reaches over 300 km/h in a hunting dive?", a: ["Kestrel", "Peregrine falcon", "Common swift", "Goshawk"], x: "The peregrine falcon dives at prey at over 300 km/h, making it the fastest animal in the world." }, fr: { q: "Quel oiseau dépasse 300 km/h en piqué ?", a: ["Faucon crécerelle", "Faucon pèlerin", "Martinet noir", "Autour des palombes"], x: "Le faucon pèlerin fond sur ses proies à plus de 300 km/h : c'est l'animal le plus rapide du monde." }, es: { q: "¿Qué ave supera los 300 km/h en picado?", a: ["Cernícalo vulgar", "Halcón peregrino", "Vencejo común", "Azor común"], x: "El halcón peregrino se lanza sobre sus presas a más de 300 km/h: es el animal más rápido del mundo." } } },
  { id: "a06", lvl: 1, type: "text", right: 3, t: { de: { q: "Welches ist das größte Nagetier der Welt?", a: ["Biber", "Stachelschwein", "Murmeltier", "Wasserschwein"], x: "Das südamerikanische Wasserschwein (Capybara) kann über 50 kg wiegen. Der Biber ist das größte Nagetier Europas." }, en: { q: "Which is the largest rodent in the world?", a: ["Beaver", "Porcupine", "Marmot", "Capybara"], x: "The South American capybara can weigh over 50 kg. The beaver is Europe's largest rodent." }, fr: { q: "Quel est le plus grand rongeur du monde ?", a: ["Castor", "Porc-épic", "Marmotte", "Capybara"], x: "Le capybara d'Amérique du Sud peut dépasser 50 kg. Le castor est le plus grand rongeur d'Europe." }, es: { q: "¿Cuál es el roedor más grande del mundo?", a: ["Castor", "Puercoespín", "Marmota", "Capibara"], x: "El capibara sudamericano puede superar los 50 kg. El castor es el roedor más grande de Europa." } } },
  { id: "a07", lvl: 1, type: "text", right: 0, t: { de: { q: "Was macht ein frisch geschlüpftes Kuckucksküken mit den anderen Eiern im Nest?", a: ["Es wirft sie aus dem Nest", "Es wärmt sie mit", "Es frisst sie auf", "Es lässt sie liegen"], x: "Das Kuckucksküken schiebt Eier und Küken der Wirtsvögel aus dem Nest. So bekommt es das ganze Futter allein." }, en: { q: "What does a newly hatched cuckoo chick do with the other eggs in the nest?", a: ["Pushes them out of the nest", "Keeps them warm", "Eats them", "Leaves them alone"], x: "The cuckoo chick pushes the host's eggs and chicks out of the nest so it gets all the food for itself." }, fr: { q: "Que fait un poussin de coucou fraîchement éclos des autres œufs du nid ?", a: ["Il les pousse hors du nid", "Il les couve aussi", "Il les mange", "Il les ignore"], x: "Le jeune coucou pousse les œufs et oisillons de ses hôtes hors du nid pour garder toute la nourriture." }, es: { q: "¿Qué hace un pollo de cuco recién nacido con los otros huevos del nido?", a: ["Los empuja fuera del nido", "Los mantiene calientes", "Se los come", "Los deja en paz"], x: "El pollo de cuco empuja fuera del nido los huevos y pollos de sus anfitriones para quedarse con toda la comida." } } },
  { id: "a08", lvl: 1, type: "text", right: 2, t: { de: { q: "Welche Farbe hat das Gefieder eines Amselweibchens?", a: ["Schwarz", "Grau mit roter Brust", "Dunkelbraun", "Schwarz-weiß gefleckt"], x: "Nur das Männchen ist schwarz mit gelbem Schnabel. Das Weibchen ist dunkelbraun und dadurch beim Brüten gut getarnt." }, en: { q: "What colour is a female blackbird?", a: ["Black", "Grey with a red breast", "Dark brown", "Black-and-white spotted"], x: "Only the male is black with a yellow bill. The female is dark brown, which camouflages her on the nest." }, fr: { q: "De quelle couleur est la femelle du merle noir ?", a: ["Noire", "Grise à poitrine rouge", "Brun foncé", "Tachetée noir et blanc"], x: "Seul le mâle est noir à bec jaune. La femelle est brun foncé, ce qui la camoufle quand elle couve." }, es: { q: "¿De qué color es la hembra del mirlo común?", a: ["Negra", "Gris con pecho rojo", "Marrón oscuro", "Moteada de blanco y negro"], x: "Solo el macho es negro con pico amarillo. La hembra es marrón oscuro, lo que la camufla al incubar." } } },
  { id: "a09", lvl: 1, type: "text", right: 1, t: { de: { q: "Was ist ein „Gewölle“ bei Eulen?", a: ["Ein Nest aus Federn", "Ausgewürgte Knochen und Haare", "Ein Balzruf", "Das weiche Daunengefieder"], x: "Eulen schlucken Mäuse ganz und würgen Unverdauliches wie Knochen und Fell später als Ballen wieder aus." }, en: { q: "What is an owl pellet?", a: ["A nest made of feathers", "Coughed-up bones and fur", "A courtship call", "Soft down feathers"], x: "Owls swallow mice whole and later cough up the indigestible bones and fur as a compact pellet." }, fr: { q: "Qu'est-ce qu'une pelote de réjection chez la chouette ?", a: ["Un nid de plumes", "Des os et poils régurgités", "Un chant nuptial", "Le duvet des poussins"], x: "Les chouettes avalent les souris entières, puis recrachent les os et poils non digérés en boulette." }, es: { q: "¿Qué es una egagrópila de búho?", a: ["Un nido de plumas", "Huesos y pelos regurgitados", "Un canto de cortejo", "El plumón suave"], x: "Los búhos tragan los ratones enteros y luego regurgitan los huesos y pelos no digeridos en una bola." } } },
  { id: "a10", lvl: 1, type: "text", right: 3, t: { de: { q: "Welcher ist der häufigste Greifvogel in Deutschland?", a: ["Rotmilan", "Habicht", "Seeadler", "Mäusebussard"], x: "Der Mäusebussard ist der häufigste Greifvogel Deutschlands. Man sieht ihn oft auf Zaunpfählen an Feldern sitzen." }, en: { q: "Which is the most common bird of prey in Germany?", a: ["Red kite", "Goshawk", "White-tailed eagle", "Common buzzard"], x: "The common buzzard is Germany's most common bird of prey, often seen perched on fence posts by fields." }, fr: { q: "Quel est le rapace le plus commun en Allemagne ?", a: ["Milan royal", "Autour des palombes", "Pygargue à queue blanche", "Buse variable"], x: "La buse variable est le rapace le plus commun d'Allemagne, souvent perchée sur des piquets au bord des champs." }, es: { q: "¿Cuál es el ave rapaz más común en Alemania?", a: ["Milano real", "Azor común", "Pigargo europeo", "Busardo ratonero"], x: "El busardo ratonero es la rapaz más común de Alemania; suele posarse en postes junto a los campos." } } },
  { id: "a11", lvl: 1, type: "tf", right: 1, t: { de: { q: "Das Reh ist das Weibchen des Hirsches.", a: ["Wahr", "Falsch"], x: "Falsch! Reh und Rothirsch sind zwei verschiedene Arten. Das Rehmännchen heißt Rehbock, das Weibchen Ricke." }, en: { q: "The roe deer is the female of the red deer.", a: ["True", "False"], x: "False! Roe deer and red deer are two separate species. Roe deer are much smaller than red deer." }, fr: { q: "Le chevreuil est la femelle du cerf.", a: ["Vrai", "Faux"], x: "Faux ! Chevreuil et cerf élaphe sont deux espèces différentes. La femelle du cerf s'appelle la biche." }, es: { q: "El corzo es la hembra del ciervo.", a: ["Verdadero", "Falso"], x: "¡Falso! El corzo y el ciervo rojo son dos especies distintas. El corzo es mucho más pequeño." } } },
  { id: "a12", lvl: 1, type: "text", right: 0, t: { de: { q: "Welches ist die größte Hirschart der Welt?", a: ["Elch", "Rothirsch", "Rentier", "Damhirsch"], x: "Der Elch ist der größte Hirsch der Welt. Große Bullen erreichen etwa 2 m Schulterhöhe und tragen schaufelförmige Geweihe." }, en: { q: "Which is the largest species of deer in the world?", a: ["Moose (elk)", "Red deer", "Reindeer", "Fallow deer"], x: "The moose is the largest deer in the world. Big bulls reach about 2 m at the shoulder and carry broad, flat antlers." }, fr: { q: "Quelle est la plus grande espèce de cerf au monde ?", a: ["Élan", "Cerf élaphe", "Renne", "Daim"], x: "L'élan est le plus grand cervidé du monde. Les grands mâles atteignent environ 2 m au garrot et portent des bois en pelle." }, es: { q: "¿Cuál es la especie de ciervo más grande del mundo?", a: ["Alce", "Ciervo rojo", "Reno", "Gamo"], x: "El alce es el cérvido más grande del mundo. Los machos grandes alcanzan unos 2 m a la cruz y tienen astas en forma de pala." } } },
  { id: "a13", lvl: 1, type: "text", right: 2, t: { de: { q: "Welche ist die größte Eule Europas?", a: ["Waldkauz", "Schleiereule", "Uhu", "Waldohreule"], x: "Der Uhu ist Europas größte Eule, mit bis zu etwa 1,8 m Flügelspannweite. Er jagt sogar Igel." }, en: { q: "Which is the largest owl in Europe?", a: ["Tawny owl", "Barn owl", "Eurasian eagle-owl", "Long-eared owl"], x: "The eagle-owl is Europe's largest owl, with a wingspan of up to about 1.8 m. It even hunts hedgehogs." }, fr: { q: "Quel est le plus grand rapace nocturne d'Europe ?", a: ["Chouette hulotte", "Effraie des clochers", "Grand-duc d'Europe", "Hibou moyen-duc"], x: "Le grand-duc est le plus grand rapace nocturne d'Europe : jusqu'à environ 1,8 m d'envergure. Il chasse même le hérisson." }, es: { q: "¿Cuál es el búho más grande de Europa?", a: ["Cárabo común", "Lechuza común", "Búho real", "Búho chico"], x: "El búho real es el mayor búho de Europa, con hasta unos 1,8 m de envergadura. Incluso caza erizos." } } },
  { id: "a14", lvl: 1, type: "text", right: 1, t: { de: { q: "Welches dieser Tiere hält einen echten Winterschlaf?", a: ["Dachs", "Siebenschläfer", "Eichhörnchen", "Reh"], x: "Der Siebenschläfer schläft bis zu etwa 7 Monate. Dachs und Eichhörnchen halten nur Winterruhe, Rehe bleiben aktiv." }, en: { q: "Which of these animals truly hibernates?", a: ["Badger", "Edible dormouse", "Red squirrel", "Roe deer"], x: "The edible dormouse sleeps for up to about 7 months. Badgers and squirrels only rest more; roe deer stay active." }, fr: { q: "Lequel de ces animaux hiberne vraiment ?", a: ["Blaireau", "Loir gris", "Écureuil roux", "Chevreuil"], x: "Le loir dort jusqu’à environ 7 mois. Le blaireau et l’écureuil ne font qu’un repos hivernal, le chevreuil reste actif." }, es: { q: "¿Cuál de estos animales hiberna de verdad?", a: ["Tejón", "Lirón gris", "Ardilla roja", "Corzo"], x: "El lirón gris duerme hasta unos 7 meses. El tejón y la ardilla solo reducen su actividad; el corzo sigue activo." } } },
  { id: "a15", lvl: 1, type: "text", right: 3, t: { de: { q: "Was passiert jedes Jahr mit dem Geweih eines Rothirsches?", a: ["Es wächst einfach weiter", "Es färbt sich weiß", "Es bleibt für immer gleich", "Es wird abgeworfen und wächst neu"], x: "Hirsche werfen ihr Geweih jedes Jahr ab. Das neue wächst in wenigen Monaten nach, geschützt von einer Haut, dem „Bast“." }, en: { q: "What happens to a red deer stag's antlers every year?", a: ["They keep growing longer", "They turn white", "They never change", "They are shed and regrow"], x: "Deer shed their antlers every year. New ones grow back within a few months, covered in skin called velvet." }, fr: { q: "Que se passe-t-il chaque année avec les bois du cerf ?", a: ["Ils continuent de s'allonger", "Ils deviennent blancs", "Ils ne changent jamais", "Ils tombent et repoussent"], x: "Le cerf perd ses bois chaque année. De nouveaux repoussent en quelques mois, couverts d'une peau appelée velours." }, es: { q: "¿Qué le pasa cada año a la cornamenta del ciervo?", a: ["Sigue creciendo sin parar", "Se vuelve blanca", "Nunca cambia", "Se cae y vuelve a crecer"], x: "Los ciervos pierden la cornamenta cada año. La nueva crece en pocos meses, cubierta de una piel llamada terciopelo." } } },
  { id: "a16", lvl: 2, type: "text", right: 1, t: { de: { q: "In welchem Land brütet etwa die Hälfte aller Rotmilane der Welt?", a: ["Spanien", "Deutschland", "Frankreich", "Polen"], x: "Etwa die Hälfte aller Rotmilane brütet in Deutschland. Man erkennt ihn am tief gegabelten, rostroten Schwanz." }, en: { q: "In which country do about half of the world's red kites breed?", a: ["Spain", "Germany", "France", "Poland"], x: "About half of all red kites breed in Germany. You can recognise it by its deeply forked, rusty-red tail." }, fr: { q: "Dans quel pays niche environ la moitié des milans royaux du monde ?", a: ["Espagne", "Allemagne", "France", "Pologne"], x: "Environ la moitié des milans royaux nichent en Allemagne. On le reconnaît à sa queue rousse profondément fourchue." }, es: { q: "¿En qué país cría aproximadamente la mitad de los milanos reales del mundo?", a: ["España", "Alemania", "Francia", "Polonia"], x: "Cerca de la mitad de los milanos reales cría en Alemania. Se reconoce por su cola rojiza muy ahorquillada." } } },
  { id: "a17", lvl: 2, type: "text", right: 2, t: { de: { q: "Wie lange können Mauersegler ohne Landung in der Luft bleiben?", a: ["Höchstens einen Tag", "Etwa eine Woche", "Bis zu etwa 10 Monate", "Ihr ganzes Leben lang"], x: "Manche Mauersegler bleiben bis zu etwa 10 Monate ununterbrochen in der Luft. Sie fressen und trinken im Flug und landen nur zum Brüten." }, en: { q: "How long can common swifts stay in the air without landing?", a: ["One day at most", "About a week", "Up to about 10 months", "Their whole life"], x: "Some swifts stay airborne for up to about 10 months non-stop. They eat and drink in flight and land only to breed." }, fr: { q: "Combien de temps les martinets noirs peuvent-ils rester en l'air sans se poser ?", a: ["Un jour au maximum", "Environ une semaine", "Jusqu'à environ 10 mois", "Toute leur vie"], x: "Certains martinets restent jusqu'à environ 10 mois en vol sans arrêt. Ils mangent et boivent en vol et ne se posent que pour nicher." }, es: { q: "¿Cuánto tiempo pueden pasar los vencejos comunes en el aire sin posarse?", a: ["Un día como máximo", "Una semana más o menos", "Hasta unos 10 meses", "Toda su vida"], x: "Algunos vencejos pasan hasta unos 10 meses volando sin parar. Comen y beben en vuelo y solo se posan para criar." } } },
  { id: "a18", lvl: 2, type: "text", right: 0, t: { de: { q: "Warum sind die Nagezähne des Bibers orange?", a: ["Eisen im Zahnschmelz", "Farbstoff aus Baumrinde", "Eine Zahnkrankheit", "Sie sind mit Blut gefüllt"], x: "Eingelagertes Eisen färbt den Zahnschmelz orange und macht ihn besonders hart – ideal zum Fällen von Bäumen." }, en: { q: "Why are a beaver's front teeth orange?", a: ["Iron in the enamel", "Dye from tree bark", "A tooth disease", "They are full of blood"], x: "Iron in the enamel turns it orange and makes it extra hard – perfect for felling trees." }, fr: { q: "Pourquoi les incisives du castor sont-elles orange ?", a: ["Du fer dans l'émail", "Un pigment de l'écorce", "Une maladie dentaire", "Elles sont pleines de sang"], x: "Le fer présent dans l'émail le colore en orange et le rend très dur, idéal pour abattre des arbres." }, es: { q: "¿Por qué los incisivos del castor son naranjas?", a: ["Hierro en el esmalte", "Tinte de la corteza", "Una enfermedad dental", "Están llenos de sangre"], x: "El hierro del esmalte lo vuelve naranja y muy duro, ideal para talar árboles." } } },
  { id: "a19", lvl: 2, type: "text", right: 3, t: { de: { q: "Warum fliegen Weißstörche auf dem Weg nach Afrika nicht einfach übers Mittelmeer?", a: ["Sie haben Angst vor Möwen", "Sie können nicht schwimmen", "Über dem Meer ist es zu kalt", "Über Wasser fehlen warme Aufwinde"], x: "Störche segeln in warmen Aufwinden, die über Land entstehen, kaum aber über dem Meer. Daher ziehen sie über Gibraltar oder den Bosporus." }, en: { q: "Why don't white storks simply fly across the Mediterranean to Africa?", a: ["They fear seagulls", "They cannot swim", "It is too cold over the sea", "There are no rising warm air currents"], x: "Storks soar on rising warm air (thermals), which forms over land but hardly over sea. So they detour via Gibraltar or the Bosporus." }, fr: { q: "Pourquoi les cigognes blanches ne traversent-elles pas simplement la Méditerranée ?", a: ["Elles ont peur des mouettes", "Elles ne savent pas nager", "Il fait trop froid sur la mer", "Il n'y a pas d'ascendances chaudes"], x: "Les cigognes planent sur l'air chaud ascendant, présent sur terre mais rare sur la mer. Elles passent donc par Gibraltar ou le Bosphore." }, es: { q: "¿Por qué las cigüeñas blancas no cruzan directamente el Mediterráneo?", a: ["Temen a las gaviotas", "No saben nadar", "Hace demasiado frío sobre el mar", "Faltan corrientes de aire cálido"], x: "Las cigüeñas planean con corrientes térmicas, que se forman sobre tierra y apenas sobre el mar. Por eso pasan por Gibraltar o el Bósforo." } } },
  { id: "a20", lvl: 2, type: "text", right: 1, t: { de: { q: "Welcher Vogel „pflanzt“ durch vergessene Wintervorräte viele neue Eichen?", a: ["Buntspecht", "Eichelhäher", "Amsel", "Ringeltaube"], x: "Der Eichelhäher versteckt im Herbst tausende Eicheln im Boden. Was er nicht wiederfindet, kann zu neuen Eichen keimen." }, en: { q: "Which bird 'plants' many new oak trees through forgotten winter stores?", a: ["Great spotted woodpecker", "Eurasian jay", "Blackbird", "Wood pigeon"], x: "In autumn the jay hides thousands of acorns in the ground. Those it never finds again can sprout into new oaks." }, fr: { q: "Quel oiseau « plante » de nombreux chênes grâce à ses réserves oubliées ?", a: ["Pic épeiche", "Geai des chênes", "Merle noir", "Pigeon ramier"], x: "En automne, le geai cache des milliers de glands dans le sol. Ceux qu'il oublie peuvent germer et devenir des chênes." }, es: { q: "¿Qué ave «planta» muchos robles nuevos con sus despensas olvidadas?", a: ["Pico picapinos", "Arrendajo", "Mirlo común", "Paloma torcaz"], x: "En otoño, el arrendajo esconde miles de bellotas en el suelo. Las que olvida pueden germinar y convertirse en robles." } } },
  { id: "a21", lvl: 2, type: "text", right: 2, t: { de: { q: "Wo brütet der Eisvogel?", a: ["In einem Nest im Schilf", "In einer Baumhöhle", "In einer selbst gegrabenen Erdröhre", "In einer Mulde am Strand"], x: "Der Eisvogel gräbt mit dem Schnabel eine oft fast meterlange Röhre in steile Uferwände. Am Ende liegt die Brutkammer." }, en: { q: "Where does the kingfisher nest?", a: ["In a reed nest", "In a tree hole", "In a burrow it digs itself", "In a hollow on the beach"], x: "The kingfisher digs a tunnel, often almost a metre long, into steep riverbanks with its bill. The nest chamber is at the end." }, fr: { q: "Où niche le martin-pêcheur ?", a: ["Dans un nid de roseaux", "Dans un trou d'arbre", "Dans un terrier qu'il creuse", "Dans un creux sur la plage"], x: "Le martin-pêcheur creuse avec son bec un tunnel souvent long de près d'un mètre dans une berge abrupte. Le nid est au fond." }, es: { q: "¿Dónde cría el martín pescador?", a: ["En un nido entre juncos", "En el hueco de un árbol", "En un túnel que excava él mismo", "En un hoyo en la playa"], x: "El martín pescador excava con el pico un túnel de casi un metro en taludes de ríos. Al fondo está el nido." } } },
  { id: "a22", lvl: 2, type: "text", right: 0, t: { de: { q: "Warum können Fledermäuse kopfüber hängend schlafen, ohne sich anzustrengen?", a: ["Ihr Gewicht schließt die Krallen", "Sie kleben mit Speichel fest", "Sie haben Saugnäpfe an den Füßen", "Sie spannen dauernd die Muskeln an"], x: "Ein Sehnen-Mechanismus hält die Zehen geschlossen, solange das Körpergewicht daran zieht. So kostet das Hängen keine Kraft." }, en: { q: "Why can bats sleep hanging upside down without any effort?", a: ["Their weight locks their claws", "They stick on with saliva", "They have suction pads on their feet", "They keep their muscles tensed"], x: "A tendon mechanism keeps the toes closed while the body weight pulls on them, so hanging costs no effort." }, fr: { q: "Pourquoi les chauves-souris peuvent-elles dormir suspendues sans effort ?", a: ["Leur poids verrouille leurs griffes", "Elles se collent avec leur salive", "Elles ont des ventouses aux pieds", "Elles gardent les muscles contractés"], x: "Un mécanisme de tendons garde les orteils fermés tant que le poids du corps tire dessus : rester suspendue ne coûte aucun effort." }, es: { q: "¿Por qué los murciélagos pueden dormir colgados sin hacer esfuerzo?", a: ["Su peso bloquea sus garras", "Se pegan con saliva", "Tienen ventosas en las patas", "Tensan los músculos todo el rato"], x: "Un mecanismo de tendones mantiene los dedos cerrados mientras el peso del cuerpo tira de ellos: colgar no les cuesta esfuerzo." } } },
  { id: "a23", lvl: 2, type: "text", right: 2, t: { de: { q: "Wie viele Stacheln hat ein erwachsener Igel ungefähr?", a: ["Etwa 70", "Etwa 700", "Etwa 7.000", "Etwa 70.000"], x: "Ein erwachsener Igel trägt etwa 6.000 bis 8.000 Stacheln. Das sind umgewandelte Haare." }, en: { q: "About how many spines does an adult hedgehog have?", a: ["About 70", "About 700", "About 7,000", "About 70,000"], x: "An adult hedgehog has about 6,000 to 8,000 spines. They are actually modified hairs." }, fr: { q: "Combien de piquants un hérisson adulte a-t-il environ ?", a: ["Environ 70", "Environ 700", "Environ 7 000", "Environ 70 000"], x: "Un hérisson adulte porte environ 6 000 à 8 000 piquants. Ce sont des poils transformés." }, es: { q: "¿Aproximadamente cuántas púas tiene un erizo adulto?", a: ["Unas 70", "Unas 700", "Unas 7.000", "Unas 70.000"], x: "Un erizo adulto tiene unas 6.000 a 8.000 púas. Son pelos modificados." } } },
  { id: "a24", lvl: 2, type: "text", right: 3, t: { de: { q: "Mit welchem dieser Tiere ist die Spitzmaus am nächsten verwandt?", a: ["Hausmaus", "Eichhörnchen", "Wildkaninchen", "Maulwurf"], x: "Spitzmäuse sind trotz des Namens keine Nagetiere. Sie gehören wie Maulwurf und Igel zu den Insektenfressern." }, en: { q: "Which of these animals is the shrew most closely related to?", a: ["House mouse", "Red squirrel", "Rabbit", "Mole"], x: "Despite looking like mice, shrews aren't rodents. Like moles and hedgehogs, they belong to the insectivores." }, fr: { q: "De quel animal la musaraigne est-elle la plus proche parente ?", a: ["Souris domestique", "Écureuil roux", "Lapin", "Taupe"], x: "Malgré leur air de souris, les musaraignes ne sont pas des rongeurs. Comme la taupe et le hérisson, ce sont des insectivores." }, es: { q: "¿Con cuál de estos animales está más emparentada la musaraña?", a: ["Ratón doméstico", "Ardilla roja", "Conejo", "Topo"], x: "Aunque parezcan ratones, las musarañas no son roedores. Como el topo y el erizo, son insectívoros." } } },
  { id: "a25", lvl: 2, type: "text", right: 0, t: { de: { q: "Was unterscheidet junge Feldhasen bei der Geburt von jungen Wildkaninchen?", a: ["Hasen haben Fell und offene Augen", "Hasen sind nackt und blind", "Hasen schlüpfen aus Eiern", "Es gibt keinen Unterschied"], x: "Junghasen kommen behaart und sehend in einer offenen Mulde zur Welt. Kaninchen werden nackt und blind im Bau geboren." }, en: { q: "How do newborn brown hares differ from newborn rabbits?", a: ["Hares have fur and open eyes", "Hares are naked and blind", "Hares hatch from eggs", "There is no difference"], x: "Young hares are born furred and with open eyes in a shallow hollow. Rabbits are born naked and blind in a burrow." }, fr: { q: "En quoi les levrauts nouveau-nés diffèrent-ils des lapereaux ?", a: ["Ils ont du poil et les yeux ouverts", "Ils sont nus et aveugles", "Ils sortent d'un œuf", "Il n'y a aucune différence"], x: "Les levrauts naissent poilus et les yeux ouverts dans un simple creux. Les lapereaux naissent nus et aveugles dans un terrier." }, es: { q: "¿En qué se diferencian los lebratos recién nacidos de las crías de conejo?", a: ["Tienen pelo y ojos abiertos", "Nacen desnudos y ciegos", "Salen de un huevo", "No hay ninguna diferencia"], x: "Los lebratos nacen con pelo y ojos abiertos en un simple hoyo. Los conejos nacen desnudos y ciegos en una madriguera." } } },
  { id: "a26", lvl: 2, type: "text", right: 1, t: { de: { q: "Wie hält sich der Fischotter im kalten Wasser warm?", a: ["Mit einer dicken Speckschicht", "Mit extrem dichtem Fell", "Durch ständiges Zittern", "Gar nicht – er friert"], x: "Der Otter hat kaum Speck, aber eines der dichtesten Felle aller Tiere. Darin hält sich eine isolierende Luftschicht." }, en: { q: "How does the Eurasian otter keep warm in cold water?", a: ["A thick layer of blubber", "Extremely dense fur", "Constant shivering", "It doesn't – it just freezes"], x: "Otters have little fat but one of the densest furs of any animal. It traps an insulating layer of air." }, fr: { q: "Comment la loutre d'Europe se protège-t-elle de l'eau froide ?", a: ["Une épaisse couche de graisse", "Une fourrure extrêmement dense", "En frissonnant sans cesse", "Elle ne se protège pas"], x: "La loutre a peu de graisse, mais l'une des fourrures les plus denses du règne animal, qui retient une couche d'air isolante." }, es: { q: "¿Cómo se mantiene caliente la nutria europea en el agua fría?", a: ["Una gruesa capa de grasa", "Un pelaje densísimo", "Tiritando sin parar", "No lo hace: pasa frío"], x: "La nutria apenas tiene grasa, pero sí uno de los pelajes más densos del reino animal, que atrapa una capa de aire aislante." } } },
  { id: "a27", lvl: 2, type: "text", right: 2, t: { de: { q: "Woher stammt der Marderhund, der heute auch in Deutschland lebt?", a: ["Nordamerika", "Südamerika", "Ostasien", "Australien"], x: "Der Marderhund stammt aus Ostasien. Er wurde in Osteuropa als Pelztier ausgesetzt und breitete sich bis zu uns aus." }, en: { q: "Where does the raccoon dog, now also living in Germany, originally come from?", a: ["North America", "South America", "East Asia", "Australia"], x: "The raccoon dog comes from East Asia. It was released in Eastern Europe for its fur and spread west as far as Germany." }, fr: { q: "D'où vient à l'origine le chien viverrin, présent aujourd'hui en Allemagne ?", a: ["Amérique du Nord", "Amérique du Sud", "Asie de l'Est", "Australie"], x: "Le chien viverrin vient d'Asie de l'Est. Relâché en Europe de l'Est pour sa fourrure, il s'est répandu jusqu'en Allemagne." }, es: { q: "¿De dónde procede el perro mapache, que hoy vive también en Alemania?", a: ["Norteamérica", "Sudamérica", "Asia oriental", "Australia"], x: "El perro mapache procede de Asia oriental. Se liberó en Europa del Este por su piel y se extendió hasta Alemania." } } },
  { id: "a28", lvl: 2, type: "text", right: 0, t: { de: { q: "Welcher Vogel ist – gemeinsam mit einem nahen Verwandten – der kleinste Vogel Europas?", a: ["Wintergoldhähnchen", "Zaunkönig", "Blaumeise", "Rotkehlchen"], x: "Winter- und Sommergoldhähnchen wiegen nur etwa 5 bis 6 Gramm. Der Zaunkönig ist etwas schwerer." }, en: { q: "Which bird is – together with a close relative – the smallest bird in Europe?", a: ["Goldcrest", "Wren", "Blue tit", "Robin"], x: "The goldcrest and its relative the firecrest weigh only about 5 to 6 grams. The wren is a bit heavier." }, fr: { q: "Quel oiseau est, avec un proche parent, le plus petit oiseau d'Europe ?", a: ["Roitelet huppé", "Troglodyte mignon", "Mésange bleue", "Rougegorge familier"], x: "Le roitelet huppé et le roitelet à triple bandeau ne pèsent qu'environ 5 à 6 grammes. Le troglodyte est un peu plus lourd." }, es: { q: "¿Qué ave es, junto con un pariente cercano, la más pequeña de Europa?", a: ["Reyezuelo sencillo", "Chochín común", "Herrerillo común", "Petirrojo"], x: "El reyezuelo sencillo y el listado pesan solo unos 5 o 6 gramos. El chochín es algo más pesado." } } },
  { id: "a29", lvl: 2, type: "text", right: 3, t: { de: { q: "Welcher dieser Vögel legt jedes Jahr die längste Zugstrecke zurück?", a: ["Weißstorch", "Kuckuck", "Rauchschwalbe", "Küstenseeschwalbe"], x: "Die Küstenseeschwalbe pendelt jedes Jahr zwischen Arktis und Antarktis – oft mehrere zehntausend Kilometer." }, en: { q: "Which of these birds flies the longest migration every year?", a: ["White stork", "Cuckoo", "Barn swallow", "Arctic tern"], x: "The Arctic tern travels between the Arctic and the Antarctic every year – often tens of thousands of kilometres." }, fr: { q: "Lequel de ces oiseaux fait chaque année la plus longue migration ?", a: ["Cigogne blanche", "Coucou gris", "Hirondelle rustique", "Sterne arctique"], x: "La sterne arctique fait chaque année l'aller-retour entre Arctique et Antarctique : souvent des dizaines de milliers de kilomètres." }, es: { q: "¿Cuál de estas aves realiza cada año la migración más larga?", a: ["Cigüeña blanca", "Cuco común", "Golondrina común", "Charrán ártico"], x: "El charrán ártico viaja cada año entre el Ártico y la Antártida: a menudo decenas de miles de kilómetros." } } },
  { id: "a30", lvl: 2, type: "text", right: 0, t: { de: { q: "Welches ist das schwerste wild lebende Landsäugetier Europas?", a: ["Wisent", "Elch", "Braunbär", "Rothirsch"], x: "Wisentbullen werden bis zu etwa 900 kg schwer. In freier Wildbahn war der Wisent ausgestorben und wurde mit Zootieren gerettet." }, en: { q: "Which is the heaviest wild land mammal in Europe?", a: ["European bison", "Moose", "Brown bear", "Red deer"], x: "European bison bulls can weigh up to about 900 kg. Once extinct in the wild, the species was saved with zoo animals." }, fr: { q: "Quel est le plus lourd mammifère terrestre sauvage d'Europe ?", a: ["Bison d'Europe", "Élan", "Ours brun", "Cerf élaphe"], x: "Les mâles du bison d'Europe pèsent jusqu'à environ 900 kg. Disparu à l'état sauvage, il a été sauvé grâce aux zoos." }, es: { q: "¿Cuál es el mamífero terrestre salvaje más pesado de Europa?", a: ["Bisonte europeo", "Alce", "Oso pardo", "Ciervo rojo"], x: "Los machos de bisonte europeo pesan hasta unos 900 kg. Se extinguió en libertad y se salvó gracias a animales de zoo." } } },
  { id: "a31", lvl: 2, type: "tf", right: 0, t: { de: { q: "Der Kolkrabe gehört zu den Singvögeln.", a: ["Wahr", "Falsch"], x: "Stimmt! Rabenvögel zählen zu den Singvögeln. Der Kolkrabe ist sogar der größte Singvogel der Welt." }, en: { q: "The common raven is a songbird.", a: ["True", "False"], x: "True! Crows and ravens belong to the songbirds. The raven is even the largest songbird in the world." }, fr: { q: "Le grand corbeau fait partie des oiseaux chanteurs.", a: ["Vrai", "Faux"], x: "Vrai ! Les corvidés sont des oiseaux chanteurs. Le grand corbeau est même le plus grand oiseau chanteur du monde." }, es: { q: "El cuervo grande es un ave cantora.", a: ["Verdadero", "Falso"], x: "¡Cierto! Los córvidos son aves cantoras. El cuervo grande es incluso el ave cantora más grande del mundo." } } },
  { id: "a32", lvl: 2, type: "tf", right: 0, t: { de: { q: "Ein Rehkitz, das allein im hohen Gras liegt, ist meist nicht verlassen.", a: ["Wahr", "Falsch"], x: "Stimmt! Die Mutter lässt es absichtlich liegen und kommt zum Säugen zurück. Bitte nicht anfassen – sonst riecht es nach Mensch." }, en: { q: "A fawn lying alone in tall grass has usually not been abandoned.", a: ["True", "False"], x: "True! The mother leaves it there on purpose and comes back to feed it. Please don’t touch it – or it will smell of humans." }, fr: { q: "Un faon couché seul dans les hautes herbes n’est en général pas abandonné.", a: ["Vrai", "Faux"], x: "Vrai ! Sa mère le laisse là exprès et revient l’allaiter. Surtout ne pas le toucher – sinon il sent l’humain." }, es: { q: "Un corzo bebé tumbado solo en la hierba alta normalmente no está abandonado.", a: ["Verdadero", "Falso"], x: "¡Verdadero! La madre lo deja allí a propósito y vuelve a amamantarlo. Por favor, no lo toques: olería a humano." } } },
  { id: "a33", lvl: 2, type: "tf", right: 1, t: { de: { q: "Hasen und Kaninchen gehören zu den Nagetieren.", a: ["Wahr", "Falsch"], x: "Falsch! Sie bilden eine eigene Gruppe, die Hasenartigen. Hinter den oberen Nagezähnen haben sie ein zweites Paar kleiner Zähne." }, en: { q: "Hares and rabbits are rodents.", a: ["True", "False"], x: "False! They form their own order, the lagomorphs. Behind their upper incisors they have a second pair of small teeth." }, fr: { q: "Les lièvres et les lapins sont des rongeurs.", a: ["Vrai", "Faux"], x: "Faux ! Ce sont des lagomorphes. Derrière leurs incisives supérieures, ils ont une seconde paire de petites dents." }, es: { q: "Las liebres y los conejos son roedores.", a: ["Verdadero", "Falso"], x: "¡Falso! Son lagomorfos. Detrás de los incisivos superiores tienen un segundo par de pequeños dientes." } } },
  { id: "a34", lvl: 2, type: "tf", right: 1, t: { de: { q: "Unter seinem weißen Fell hat der Eisbär ebenfalls weiße Haut.", a: ["Wahr", "Falsch"], x: "Falsch! Die Haut des Eisbären ist schwarz. Seine Haare sind eigentlich farblos und durchsichtig und wirken nur weiß." }, en: { q: "Under its white fur, a polar bear also has white skin.", a: ["True", "False"], x: "False! A polar bear's skin is black. Its hairs are actually colourless and see-through; they only look white." }, fr: { q: "Sous sa fourrure blanche, l'ours polaire a aussi la peau blanche.", a: ["Vrai", "Faux"], x: "Faux ! Sa peau est noire. Ses poils sont en fait incolores et transparents : ils paraissent seulement blancs." }, es: { q: "Bajo su pelaje blanco, el oso polar también tiene la piel blanca.", a: ["Verdadero", "Falso"], x: "¡Falso! Su piel es negra. Sus pelos son en realidad incoloros y transparentes; solo parecen blancos." } } },
  { id: "a35", lvl: 2, type: "tf", right: 0, t: { de: { q: "Schleiereulen können Mäuse in völliger Dunkelheit allein nach Gehör fangen.", a: ["Wahr", "Falsch"], x: "Stimmt! Der herzförmige Gesichtsschleier lenkt Geräusche zu den leicht versetzten Ohren. So orten sie Beute punktgenau." }, en: { q: "Barn owls can catch mice in total darkness by hearing alone.", a: ["True", "False"], x: "True! The heart-shaped facial disc funnels sound to their slightly offset ears, so they can pinpoint prey." }, fr: { q: "L'effraie des clochers peut attraper une souris dans le noir complet, rien qu'à l'ouïe.", a: ["Vrai", "Faux"], x: "Vrai ! Son disque facial en cœur dirige les sons vers ses oreilles décalées, ce qui lui permet de localiser la proie avec précision." }, es: { q: "La lechuza común puede cazar ratones en total oscuridad solo con el oído.", a: ["Verdadero", "Falso"], x: "¡Cierto! Su disco facial en forma de corazón dirige el sonido a sus oídos asimétricos y localiza la presa con precisión." } } },
  { id: "a36", lvl: 3, type: "text", right: 2, t: { de: { q: "Wo liegt die extrem lange Zunge des Grünspechts, wenn er sie nicht benutzt?", a: ["Aufgerollt im Kehlsack", "Gefaltet im Schnabel", "Um den Schädel herum gewickelt", "Im Magen"], x: "Die Zunge sitzt auf langen Knochenspangen, die hinten um den ganzen Schädel laufen. So kann er tief in Ameisennester stoßen." }, en: { q: "Where is the green woodpecker's extremely long tongue kept when not in use?", a: ["Coiled in a throat pouch", "Folded in its bill", "Wrapped around its skull", "In its stomach"], x: "The tongue sits on long bony rods that loop around the back of the skull. This lets it probe deep into ant nests." }, fr: { q: "Où se range la langue extrêmement longue du pic vert au repos ?", a: ["Enroulée dans la gorge", "Pliée dans le bec", "Enroulée autour du crâne", "Dans l'estomac"], x: "La langue repose sur de longues tiges osseuses qui font le tour du crâne. Le pic vert peut ainsi fouiller loin dans les fourmilières." }, es: { q: "¿Dónde guarda el pito real su larguísima lengua cuando no la usa?", a: ["Enrollada en la garganta", "Doblada dentro del pico", "Enrollada alrededor del cráneo", "En el estómago"], x: "La lengua se apoya en largos huesos que rodean el cráneo por detrás. Así puede hurgar a fondo en los hormigueros." } } },
  { id: "a37", lvl: 3, type: "text", right: 1, t: { de: { q: "Rehe paaren sich im Hochsommer, die Kitze kommen aber erst im nächsten Mai oder Juni. Warum?", a: ["Die Ricke trägt zwei Kitze nacheinander", "Der Embryo macht monatelang Pause", "Die Kitze wachsen extrem langsam", "Sie paaren sich im Frühling erneut"], x: "Beim Reh ruht der Keim nach der Befruchtung bis etwa Dezember (Keimruhe). So kommen die Kitze, wenn es viel Futter gibt." }, en: { q: "Roe deer mate in midsummer, but fawns are only born the next May or June. Why?", a: ["The doe carries two fawns in turn", "The embryo pauses for months", "The fawns grow extremely slowly", "They mate again in spring"], x: "In roe deer the embryo rests until around December (delayed implantation), so fawns arrive when food is plentiful." }, fr: { q: "Les chevreuils s'accouplent en plein été, mais les faons naissent en mai ou juin suivant. Pourquoi ?", a: ["La chevrette porte deux faons à la suite", "L'embryon reste en pause des mois", "Les faons grandissent très lentement", "Ils s'accouplent à nouveau au printemps"], x: "Chez le chevreuil, l'embryon reste en pause jusque vers décembre (implantation différée). Les faons naissent quand la nourriture abonde." }, es: { q: "Los corzos se aparean en pleno verano, pero las crías nacen en mayo o junio. ¿Por qué?", a: ["La hembra gesta dos crías seguidas", "El embrión se detiene durante meses", "Las crías crecen muy despacio", "Vuelven a aparearse en primavera"], x: "En el corzo, el embrión queda en pausa hasta diciembre (implantación diferida); así las crías nacen cuando abunda el alimento." } } },
  { id: "a38", lvl: 3, type: "text", right: 2, t: { de: { q: "In welchem Jahr wurden in Deutschland erstmals wieder wilde Wolfswelpen geboren?", a: ["1975", "1990", "2000", "2015"], x: "Im Jahr 2000 zog ein Wolfspaar in der Lausitz in Sachsen Junge groß – nach über 100 Jahren ohne Wolfsnachwuchs in Deutschland." }, en: { q: "In which year were wild wolf pups born in Germany again for the first time?", a: ["1975", "1990", "2000", "2015"], x: "In 2000 a wolf pair raised pups in Lusatia, Saxony – after more than 100 years without wolves breeding in Germany." }, fr: { q: "En quelle année des louveteaux sauvages sont-ils de nouveau nés en Allemagne ?", a: ["1975", "1990", "2000", "2015"], x: "En 2000, un couple de loups a élevé des petits en Lusace (Saxe), après plus de 100 ans sans reproduction de loups en Allemagne." }, es: { q: "¿En qué año volvieron a nacer lobeznos salvajes en Alemania por primera vez?", a: ["1975", "1990", "2000", "2015"], x: "En 2000 una pareja de lobos crió cachorros en Lusacia (Sajonia), tras más de 100 años sin lobos criando en Alemania." } } },
  { id: "a39", lvl: 3, type: "text", right: 3, t: { de: { q: "Woran unterscheidet man eine Europäische Wildkatze von einer getigerten Hauskatze?", a: ["An Pinseln auf den Ohren", "An weißen Pfoten", "Am langen, dünnen Schwanz", "Dicker Schwanz, stumpfe schwarze Spitze"], x: "Die Wildkatze hat einen dicken, buschigen Schwanz mit schwarzen Ringen und stumpfem schwarzem Ende. Pinselohren hat der Luchs." }, en: { q: "What helps tell a European wildcat from a tabby house cat?", a: ["Tufts on its ears", "White paws", "A long, thin tail", "Bushy tail with a blunt black tip"], x: "The wildcat has a thick, bushy tail with black rings and a blunt black end. Ear tufts belong to the lynx." }, fr: { q: "Qu'est-ce qui distingue le chat forestier d'un chat domestique tigré ?", a: ["Des pinceaux aux oreilles", "Des pattes blanches", "Une queue longue et fine", "Queue touffue à bout noir arrondi"], x: "Le chat forestier a une queue épaisse et touffue, annelée de noir, au bout noir arrondi. Les pinceaux aux oreilles, c'est le lynx." }, es: { q: "¿Qué distingue al gato montés europeo de un gato doméstico atigrado?", a: ["Pinceles en las orejas", "Patas blancas", "Una cola larga y fina", "Cola tupida con punta negra roma"], x: "El gato montés tiene una cola gruesa y tupida, con anillos negros y punta negra roma. Los pinceles en las orejas son del lince." } } },
  { id: "a40", lvl: 3, type: "text", right: 1, t: { de: { q: "In welchem Jahr wurden in Deutschland erstmals Waschbären gezielt in der Natur ausgesetzt?", a: ["1834", "1934", "1974", "1994"], x: "1934 wurden am Edersee in Hessen zwei Waschbärpaare freigelassen. Heute leben in Deutschland sehr viele dieser Nordamerikaner." }, en: { q: "In which year were raccoons first deliberately released into the wild in Germany?", a: ["1834", "1934", "1974", "1994"], x: "In 1934 two pairs of raccoons were released at Lake Edersee in Hesse. Today these North Americans are very common in Germany." }, fr: { q: "En quelle année des ratons laveurs ont-ils été relâchés exprès pour la première fois en Allemagne ?", a: ["1834", "1934", "1974", "1994"], x: "En 1934, deux couples ont été relâchés au lac d'Edersee (Hesse). Aujourd'hui, ces Nord-Américains sont très nombreux en Allemagne." }, es: { q: "¿En qué año se soltaron a propósito los primeros mapaches en la naturaleza en Alemania?", a: ["1834", "1934", "1974", "1994"], x: "En 1934 se liberaron dos parejas junto al lago Edersee (Hesse). Hoy estos norteamericanos son muy abundantes en Alemania." } } },
  { id: "a41", lvl: 3, type: "text", right: 2, t: { de: { q: "Welches ist das größte wild lebende Raubtier Deutschlands?", a: ["Wolf", "Luchs", "Kegelrobbe", "Seehund"], x: "Robben zählen zu den Raubtieren. Kegelrobben-Männchen an Nord- und Ostsee werden bis zu etwa 300 kg schwer." }, en: { q: "Which is the largest wild carnivore in Germany?", a: ["Wolf", "Lynx", "Grey seal", "Harbour seal"], x: "Seals belong to the carnivores. Male grey seals on the North Sea and Baltic coasts weigh up to about 300 kg." }, fr: { q: "Quel est le plus grand carnivore sauvage d'Allemagne ?", a: ["Loup", "Lynx", "Phoque gris", "Phoque veau-marin"], x: "Les phoques font partie des carnivores. Les mâles du phoque gris, en mer du Nord et Baltique, pèsent jusqu'à environ 300 kg." }, es: { q: "¿Cuál es el mayor carnívoro salvaje de Alemania?", a: ["Lobo", "Lince", "Foca gris", "Foca común"], x: "Las focas pertenecen a los carnívoros. Los machos de foca gris del mar del Norte y el Báltico pesan hasta unos 300 kg." } } },
  { id: "a42", lvl: 3, type: "text", right: 0, t: { de: { q: "Womit füttern Tauben ihre frisch geschlüpften Jungen?", a: ["Mit „Kropfmilch“", "Mit zerkauten Insekten", "Mit Regenwürmern", "Mit Blütennektar"], x: "Beide Eltern bilden im Kropf eine nahrhafte, käseartige „Kropfmilch“. Das ist bei Vögeln eine große Ausnahme." }, en: { q: "What do pigeons feed their newly hatched chicks?", a: ["'Crop milk'", "Chewed-up insects", "Earthworms", "Flower nectar"], x: "Both parents produce a nutritious, cheese-like 'crop milk' in their crop – very unusual for birds." }, fr: { q: "De quoi les pigeons nourrissent-ils leurs petits tout juste éclos ?", a: ["Du « lait de jabot »", "Des insectes mâchés", "Des vers de terre", "Du nectar de fleurs"], x: "Les deux parents produisent dans leur jabot un « lait » nourrissant, semblable à du fromage. C'est très rare chez les oiseaux." }, es: { q: "¿Con qué alimentan las palomas a sus pichones recién nacidos?", a: ["Con «leche de buche»", "Con insectos masticados", "Con lombrices", "Con néctar de flores"], x: "Ambos padres producen en el buche una «leche» nutritiva, parecida al queso. Es algo muy raro entre las aves." } } },
  { id: "a43", lvl: 3, type: "text", right: 1, t: { de: { q: "Welche Tiere sind die nächsten lebenden Verwandten des Flusspferds?", a: ["Schweine", "Wale", "Nashörner", "Elefanten"], x: "Erbgut-Vergleiche zeigen: Flusspferde sind am engsten mit Walen und Delfinen verwandt – nicht mit Schweinen, wie man lange dachte." }, en: { q: "Which animals are the hippopotamus's closest living relatives?", a: ["Pigs", "Whales", "Rhinos", "Elephants"], x: "DNA studies show that hippos are most closely related to whales and dolphins – not to pigs, as was long believed." }, fr: { q: "Quels animaux sont les plus proches parents vivants de l'hippopotame ?", a: ["Les cochons", "Les baleines", "Les rhinocéros", "Les éléphants"], x: "L'ADN le montre : les hippopotames sont les plus proches parents des baleines et dauphins, et non des cochons comme on l'a longtemps cru." }, es: { q: "¿Qué animales son los parientes vivos más cercanos del hipopótamo?", a: ["Los cerdos", "Las ballenas", "Los rinocerontes", "Los elefantes"], x: "El ADN lo demuestra: los hipopótamos están más emparentados con ballenas y delfines que con los cerdos, como se creyó mucho tiempo." } } },
  { id: "a44", lvl: 3, type: "text", right: 3, t: { de: { q: "Wie wirbt das Zaunkönig-Männchen um ein Weibchen?", a: ["Es bringt ihr Beeren", "Es tanzt auf dem Wasser", "Es färbt sein Gefieder rot", "Es baut mehrere Nester zur Auswahl"], x: "Das Männchen baut mehrere kugelige Rohbau-Nester. Das Weibchen sucht sich eines aus und polstert es dann weich aus." }, en: { q: "How does a male wren win over a female?", a: ["He brings her berries", "He dances on the water", "His plumage turns red", "He builds several nests to choose from"], x: "The male builds several unfinished, ball-shaped nests. The female chooses one and lines it with soft material." }, fr: { q: "Comment le troglodyte mâle séduit-il une femelle ?", a: ["Il lui apporte des baies", "Il danse sur l'eau", "Son plumage devient rouge", "Il construit plusieurs nids au choix"], x: "Le mâle construit plusieurs nids en boule inachevés. La femelle en choisit un et le garnit de matériaux doux." }, es: { q: "¿Cómo conquista el macho de chochín a una hembra?", a: ["Le lleva bayas", "Baila sobre el agua", "Su plumaje se vuelve rojo", "Construye varios nidos para elegir"], x: "El macho construye varios nidos esféricos sin terminar. La hembra elige uno y lo forra con material blando." } } },
  { id: "a45", lvl: 3, type: "text", right: 2, t: { de: { q: "Was passiert mit Stockenten während der Mauser im Sommer?", a: ["Sie verlieren ihre Stimme", "Sie werden ganz weiß", "Sie können wochenlang nicht fliegen", "Sie halten einen Sommerschlaf"], x: "Enten verlieren alle Schwungfedern auf einmal und sind etwa 3 bis 4 Wochen flugunfähig. Erpel tragen dann ein schlichtes Kleid." }, en: { q: "What happens to mallards during their summer moult?", a: ["They lose their voice", "They turn completely white", "They can't fly for weeks", "They sleep through the summer"], x: "Ducks shed all their flight feathers at once and can't fly for about 3–4 weeks. Drakes then wear a plain, dull plumage." }, fr: { q: "Que se passe-t-il chez le canard colvert lors de la mue d'été ?", a: ["Il perd sa voix", "Il devient tout blanc", "Il ne vole plus pendant des semaines", "Il dort tout l'été"], x: "Les canards perdent toutes leurs rémiges d'un coup et ne volent plus pendant 3 à 4 semaines. Le mâle prend alors un plumage terne." }, es: { q: "¿Qué les ocurre a los ánades reales durante la muda de verano?", a: ["Pierden la voz", "Se vuelven totalmente blancos", "No pueden volar durante semanas", "Duermen todo el verano"], x: "Los patos pierden todas las plumas de vuelo a la vez y no vuelan durante 3 o 4 semanas. Los machos lucen entonces un plumaje apagado." } } },
  { id: "a46", lvl: 3, type: "text", right: 0, t: { de: { q: "Welche Tiergruppe gehört zu den nächsten lebenden Verwandten der Elefanten?", a: ["Seekühe", "Nashörner", "Flusspferde", "Tapire"], x: "Elefanten sind eng mit Seekühen (Manatis und Dugongs) verwandt – und mit den kleinen Klippschliefern." }, en: { q: "Which group of animals is among the elephant's closest living relatives?", a: ["Sea cows (manatees)", "Rhinos", "Hippos", "Tapirs"], x: "Elephants are closely related to sea cows (manatees and dugongs) – and to the small rock hyraxes." }, fr: { q: "Quel groupe d'animaux compte parmi les plus proches parents des éléphants ?", a: ["Les siréniens (lamantins)", "Les rhinocéros", "Les hippopotames", "Les tapirs"], x: "Les éléphants sont proches parents des siréniens (lamantins et dugongs) et des petits damans." }, es: { q: "¿Qué grupo de animales está entre los parientes más cercanos de los elefantes?", a: ["Los sirenios (manatíes)", "Los rinocerontes", "Los hipopótamos", "Los tapires"], x: "Los elefantes están emparentados con los sirenios (manatíes y dugongos) y con los pequeños damanes." } } },
  { id: "a47", lvl: 3, type: "tf", right: 1, t: { de: { q: "Mauersegler sind eng mit den Schwalben verwandt.", a: ["Wahr", "Falsch"], x: "Falsch! Sie sehen Schwalben nur ähnlich. Mauersegler sind näher mit den Kolibris verwandt als mit Schwalben." }, en: { q: "Common swifts are closely related to swallows.", a: ["True", "False"], x: "False! They only look similar. Swifts are more closely related to hummingbirds than to swallows." }, fr: { q: "Le martinet noir est un proche parent des hirondelles.", a: ["Vrai", "Faux"], x: "Faux ! Ils se ressemblent seulement. Les martinets sont plus proches des colibris que des hirondelles." }, es: { q: "El vencejo común es pariente cercano de las golondrinas.", a: ["Verdadero", "Falso"], x: "¡Falso! Solo se parecen. Los vencejos están más emparentados con los colibríes que con las golondrinas." } } },
  { id: "a48", lvl: 3, type: "tf", right: 0, t: { de: { q: "Es gibt einen heimischen Singvogel, der tauchen und unter Wasser am Bachgrund entlanglaufen kann.", a: ["Wahr", "Falsch"], x: "Stimmt! Die Wasseramsel taucht in schnellen Bächen nach Insektenlarven und läuft dabei sogar über den Grund." }, en: { q: "There is a Central European songbird that can dive and walk along a stream bed underwater.", a: ["True", "False"], x: "True! The white-throated dipper dives in fast streams for insect larvae and even walks along the bottom." }, fr: { q: "Il existe un oiseau chanteur d'Europe centrale qui plonge et marche sous l'eau au fond des ruisseaux.", a: ["Vrai", "Faux"], x: "Vrai ! Le cincle plongeur plonge dans les torrents pour chercher des larves d'insectes et marche même sur le fond." }, es: { q: "Existe un ave cantora centroeuropea que bucea y camina bajo el agua por el fondo de los arroyos.", a: ["Verdadero", "Falso"], x: "¡Cierto! El mirlo acuático bucea en arroyos rápidos buscando larvas de insectos e incluso camina por el fondo." } } },
  { id: "a49", lvl: 3, type: "tf", right: 0, t: { de: { q: "Maulwürfe legen Vorratskammern mit lebenden Regenwürmern an, die sie durch einen Biss lähmen.", a: ["Wahr", "Falsch"], x: "Stimmt! Ein Biss in den Kopf macht die Würmer bewegungsunfähig. So bleiben sie als frischer Vorrat für den Winter erhalten." }, en: { q: "Moles keep larders of live earthworms that they have paralysed with a bite.", a: ["True", "False"], x: "True! A bite to the head immobilises the worms, keeping them fresh as a winter food supply." }, fr: { q: "Les taupes stockent des vers de terre vivants, paralysés par une morsure.", a: ["Vrai", "Faux"], x: "Vrai ! Une morsure à la tête immobilise les vers, qui restent frais comme réserve pour l'hiver." }, es: { q: "Los topos almacenan lombrices vivas que han paralizado con un mordisco.", a: ["Verdadero", "Falso"], x: "¡Cierto! Un mordisco en la cabeza inmoviliza las lombrices, que se conservan frescas como reserva para el invierno." } } },
  { id: "a50", lvl: 3, type: "tf", right: 0, t: { de: { q: "Bei Rotkehlchen singen im Herbst und Winter auch die Weibchen.", a: ["Wahr", "Falsch"], x: "Stimmt! Im Winter verteidigen auch Rotkehlchen-Weibchen ein eigenes Revier – und tun das mit Gesang." }, en: { q: "In autumn and winter, female robins sing too.", a: ["True", "False"], x: "True! In winter, female robins also defend their own territory – and they do it by singing." }, fr: { q: "En automne et en hiver, les femelles de rougegorge chantent aussi.", a: ["Vrai", "Faux"], x: "Vrai ! En hiver, les femelles de rougegorge défendent elles aussi leur propre territoire, et elles le font en chantant." }, es: { q: "En otoño e invierno, las hembras de petirrojo también cantan.", a: ["Verdadero", "Falso"], x: "¡Cierto! En invierno, las hembras de petirrojo también defienden su propio territorio, y lo hacen cantando." } } },
  { id: "d01", lvl: 1, type: "pic", right: 0, img: ["q-tr-fox"], t: { de: { q: "Wessen Spur ist das?", a: ["Fuchs", "Reh", "Dachs", "Hase"], x: "Vier Zehen mit Krallen und ein kleiner Ballen: ein Fuchs. Typisch ist das schmale Oval – zwischen Ballen und Zehen bleibt ein freier Raum in X-Form." }, en: { q: "Whose track is this?", a: ["Fox", "Roe deer", "Badger", "Hare"], x: "Four toes with claws and a small pad: a fox. Typical is the narrow oval – between the pad and the toes there is an empty X-shaped space." }, fr: { q: "À qui est cette empreinte ?", a: ["Renard", "Chevreuil", "Blaireau", "Lièvre"], x: "Quatre doigts avec griffes et une petite pelote : un renard. L’ovale étroit est typique – entre la pelote et les doigts reste un espace libre en forme de X." }, es: { q: "¿De quién es esta huella?", a: ["Zorro", "Corzo", "Tejón", "Liebre"], x: "Cuatro dedos con uñas y una almohadilla pequeña: un zorro. Es típico el óvalo estrecho: entre la almohadilla y los dedos queda un hueco en forma de X." } } },
  { id: "d02", lvl: 2, type: "pic", right: 1, img: ["q-tr-deer"], t: { de: { q: "Wer ist hier durch den Matsch gelaufen?", a: ["Wildschwein", "Reh", "Hund", "Dachs"], x: "Zwei schmale, spitze Hufhälften: das Trittsiegel eines Rehs. Das Wildschwein hat breitere Hufe und dahinter meist zwei Abdrücke der Afterklauen." }, en: { q: "Who walked through the mud here?", a: ["Wild boar", "Roe deer", "Dog", "Badger"], x: "Two narrow, pointed hoof halves: the print of a roe deer. A wild boar has wider hooves and usually two dewclaw marks behind them." }, fr: { q: "Qui est passé dans la boue ici ?", a: ["Sanglier", "Chevreuil", "Chien", "Blaireau"], x: "Deux moitiés de sabot étroites et pointues : l’empreinte d’un chevreuil. Le sanglier a des sabots plus larges et, derrière, souvent deux marques d’ergots." }, es: { q: "¿Quién ha pasado por el barro?", a: ["Jabalí", "Corzo", "Perro", "Tejón"], x: "Dos mitades de pezuña estrechas y puntiagudas: la huella de un corzo. El jabalí tiene pezuñas más anchas y, detrás, casi siempre dos marcas de los espolones." } } },
  { id: "d03", lvl: 3, type: "pic", right: 2, img: ["q-tr-boar"], t: { de: { q: "Zwei Hufe und dahinter zwei Punkte – wer war das?", a: ["Reh", "Rothirsch", "Wildschwein", "Gämse"], x: "Die zwei Punkte sind die Afterklauen. Beim Wildschwein sitzen sie tief und weit außen und drücken sich fast immer mit ab – bei Reh und Hirsch meist nur in weichem Boden." }, en: { q: "Two hooves and two dots behind them – who was it?", a: ["Roe deer", "Red deer", "Wild boar", "Chamois"], x: "The two dots are dewclaws. On a wild boar they sit low and wide and almost always leave a mark – on deer usually only in soft ground." }, fr: { q: "Deux sabots et deux points derrière – qui est-ce ?", a: ["Chevreuil", "Cerf", "Sanglier", "Chamois"], x: "Les deux points sont les ergots. Chez le sanglier, ils sont bas et écartés et marquent presque toujours – chez le chevreuil et le cerf, surtout en sol mou." }, es: { q: "Dos pezuñas y dos puntos detrás: ¿quién fue?", a: ["Corzo", "Ciervo", "Jabalí", "Rebeco"], x: "Los dos puntos son los espolones. En el jabalí están bajos y separados y casi siempre se marcan; en corzos y ciervos, normalmente solo en suelo blando." } } },
  { id: "d04", lvl: 2, type: "pic", right: 1, img: ["q-tr-badger"], t: { de: { q: "Wessen Spur ist das?", a: ["Fuchs", "Dachs", "Fischotter", "Hase"], x: "Fünf Zehen fast in einer Reihe vor einem breiten Ballen: ein Dachs. Mit den langen Krallen der Vorderpfoten gräbt er seine riesigen Baue." }, en: { q: "Whose track is this?", a: ["Fox", "Badger", "Otter", "Hare"], x: "Five toes almost in a row in front of a wide pad: a badger. With the long claws on its front paws it digs huge burrows." }, fr: { q: "À qui est cette empreinte ?", a: ["Renard", "Blaireau", "Loutre", "Lièvre"], x: "Cinq doigts presque alignés devant une large pelote : un blaireau. Avec les longues griffes de ses pattes avant, il creuse d’immenses terriers." }, es: { q: "¿De quién es esta huella?", a: ["Zorro", "Tejón", "Nutria", "Liebre"], x: "Cinco dedos casi en fila delante de una almohadilla ancha: un tejón. Con las largas uñas de las patas delanteras excava enormes madrigueras." } } },
  { id: "d05", lvl: 3, type: "pic", right: 1, img: ["q-tr-hare"], t: { de: { q: "Diese Spuren im Schnee (Laufrichtung nach oben): wer ist hier gehoppelt?", a: ["Eichhörnchen", "Hase", "Reh", "Fuchs"], x: "Beim Hasen landen die langen Hinterpfoten vor den Vorderpfoten, und die Vorderpfoten stehen hintereinander. Beim Eichhörnchen stehen auch die Vorderpfoten nebeneinander." }, en: { q: "These tracks in the snow (moving upwards): who hopped here?", a: ["Squirrel", "Hare", "Roe deer", "Fox"], x: "A hare’s long hind feet land in front of its front feet, and the front feet land one behind the other. A squirrel puts its front feet side by side too." }, fr: { q: "Ces traces dans la neige (direction vers le haut) : qui a sautillé ici ?", a: ["Écureuil", "Lièvre", "Chevreuil", "Renard"], x: "Chez le lièvre, les longues pattes arrière se posent devant les pattes avant, et celles-ci se suivent l’une derrière l’autre. L’écureuil pose aussi ses pattes avant côte à côte." }, es: { q: "Estas huellas en la nieve (dirección hacia arriba): ¿quién ha saltado aquí?", a: ["Ardilla", "Liebre", "Corzo", "Zorro"], x: "La liebre apoya sus largas patas traseras delante de las delanteras, y las delanteras quedan una detrás de otra. La ardilla pone también las delanteras una al lado de la otra." } } },
  { id: "d06", lvl: 1, type: "pic", right: 2, img: ["q-tr-duck"], t: { de: { q: "Wer hat am Ufer diese Spur hinterlassen?", a: ["Krähe", "Taube", "Stockente", "Graureiher"], x: "Drei Zehen nach vorn, verbunden mit Schwimmhäuten: eine Ente. Krähe, Taube und Reiher haben keine Schwimmhäute." }, en: { q: "Who left this track on the shore?", a: ["Crow", "Pigeon", "Mallard", "Grey heron"], x: "Three toes pointing forward, joined by webbing: a duck. Crows, pigeons and herons have no webbed feet." }, fr: { q: "Qui a laissé cette trace sur la rive ?", a: ["Corneille", "Pigeon", "Canard colvert", "Héron cendré"], x: "Trois doigts vers l’avant reliés par une palmure : un canard. La corneille, le pigeon et le héron n’ont pas de pattes palmées." }, es: { q: "¿Quién dejó esta huella en la orilla?", a: ["Corneja", "Paloma", "Ánade real", "Garza real"], x: "Tres dedos hacia delante unidos por membranas: un pato. Cornejas, palomas y garzas no tienen membranas." } } },
  { id: "d07", lvl: 2, type: "pic", right: 1, img: ["q-tr-crow"], t: { de: { q: "Welcher Vogel hat diesen Abdruck hinterlassen?", a: ["Stockente", "Rabenkrähe", "Höckerschwan", "Blässhuhn"], x: "Drei dünne Zehen nach vorn und eine lange nach hinten: typisch für Vögel wie die Krähe, die damit Äste umklammern. Enten und Schwäne haben Schwimmhäute, das Blässhuhn Schwimmlappen." }, en: { q: "Which bird left this print?", a: ["Mallard", "Carrion crow", "Mute swan", "Coot"], x: "Three thin toes forward and a long one backwards: typical of birds like the crow, which use it to grip branches. Ducks and swans have webbed feet, coots have lobed toes." }, fr: { q: "Quel oiseau a laissé cette empreinte ?", a: ["Canard colvert", "Corneille noire", "Cygne tuberculé", "Foulque"], x: "Trois doigts fins vers l’avant et un long vers l’arrière : typique des oiseaux comme la corneille, qui s’agrippent ainsi aux branches. Canards et cygnes ont des palmures, la foulque des lobes." }, es: { q: "¿Qué ave dejó esta huella?", a: ["Ánade real", "Corneja", "Cisne vulgar", "Focha"], x: "Tres dedos finos hacia delante y uno largo hacia atrás: típico de aves como la corneja, que así se agarran a las ramas. Patos y cisnes tienen membranas, la focha lóbulos." } } },
  { id: "d08", lvl: 2, type: "pic", right: 1, img: ["q-si-buzzard"], t: { de: { q: "Wer kreist da über dem Feld?", a: ["Rotmilan", "Mäusebussard", "Weißstorch", "Mauersegler"], x: "Breite Flügel mit gespreizten „Fingern“ und ein kurzer, runder Schwanz: der Mäusebussard. Oft sitzt er auch auf Zaunpfählen am Feldrand und späht nach Mäusen. Der Rotmilan hätte einen tief gegabelten Schwanz." }, en: { q: "Who is circling over the field?", a: ["Red kite", "Common buzzard", "White stork", "Common swift"], x: "Broad wings with spread “fingers” and a short, round tail: the common buzzard. It often sits on fence posts at the edge of fields, watching for mice. A red kite would have a deeply forked tail." }, fr: { q: "Qui tournoie au-dessus du champ ?", a: ["Milan royal", "Buse variable", "Cigogne blanche", "Martinet noir"], x: "De larges ailes aux « doigts » écartés et une queue courte et ronde : la buse variable. Elle guette souvent les souris perchée sur un piquet au bord des champs. Le milan royal aurait une queue profondément fourchue." }, es: { q: "¿Quién vuela en círculos sobre el campo?", a: ["Milano real", "Busardo ratonero", "Cigüeña blanca", "Vencejo común"], x: "Alas anchas con los «dedos» abiertos y una cola corta y redonda: el busardo ratonero. A menudo acecha ratones posado en un poste junto a los campos. El milano real tendría la cola muy ahorquillada." } } },
  { id: "d09", lvl: 2, type: "pic", right: 1, img: ["q-si-kite"], t: { de: { q: "Wer ist das? Achte auf den Schwanz!", a: ["Mäusebussard", "Rotmilan", "Turmfalke", "Habicht"], x: "Der tief gegabelte Schwanz verrät den Rotmilan. Beim Segeln dreht er ihn ständig hin und her und steuert damit wie mit einem Ruder." }, en: { q: "Who is this? Look at the tail!", a: ["Common buzzard", "Red kite", "Kestrel", "Goshawk"], x: "The deeply forked tail gives away the red kite. While gliding, it keeps twisting it and steers with it like a rudder." }, fr: { q: "Qui est-ce ? Regarde la queue !", a: ["Buse variable", "Milan royal", "Faucon crécerelle", "Autour des palombes"], x: "La queue profondément fourchue trahit le milan royal. En planant, il la tourne sans cesse et s’en sert comme d’un gouvernail." }, es: { q: "¿Quién es? ¡Fíjate en la cola!", a: ["Busardo ratonero", "Milano real", "Cernícalo", "Azor"], x: "La cola muy ahorquillada delata al milano real. Al planear la gira sin parar y la usa como un timón." } } },
  { id: "d10", lvl: 2, type: "pic", right: 1, img: ["q-si-stork"], t: { de: { q: "Wer fliegt da mit lang gestrecktem Hals?", a: ["Graureiher", "Weißstorch", "Höckerschwan", "Mäusebussard"], x: "Langer Hals nach vorn, lange Beine nach hinten: der Weißstorch. Der Graureiher zieht im Flug den Hals ein, der Schwan hat kurze Beine." }, en: { q: "Who is flying with its neck stretched out?", a: ["Grey heron", "White stork", "Mute swan", "Common buzzard"], x: "Long neck forward, long legs back: the white stork. A grey heron pulls its neck in while flying, and a swan has short legs." }, fr: { q: "Qui vole le cou tendu ?", a: ["Héron cendré", "Cigogne blanche", "Cygne tuberculé", "Buse variable"], x: "Long cou vers l’avant, longues pattes vers l’arrière : la cigogne blanche. Le héron rentre le cou en vol, et le cygne a des pattes courtes." }, es: { q: "¿Quién vuela con el cuello estirado?", a: ["Garza real", "Cigüeña blanca", "Cisne vulgar", "Busardo ratonero"], x: "Cuello largo hacia delante y patas largas hacia atrás: la cigüeña blanca. La garza recoge el cuello al volar y el cisne tiene patas cortas." } } },
  { id: "d11", lvl: 3, type: "pic", right: 2, img: ["q-si-heron"], t: { de: { q: "Lange Beine nach hinten, aber der Hals ist eingezogen. Wer ist das?", a: ["Weißstorch", "Kranich", "Graureiher", "Kormoran"], x: "Reiher legen den Hals im Flug in eine S-Kurve und ziehen den Kopf ein. Störche und Kraniche fliegen mit gestrecktem Hals." }, en: { q: "Long legs trailing, but the neck is pulled in. Who is it?", a: ["White stork", "Common crane", "Grey heron", "Cormorant"], x: "Herons fold their neck into an S-shape and pull in their head while flying. Storks and cranes fly with their necks stretched out." }, fr: { q: "Longues pattes vers l’arrière, mais le cou rentré. Qui est-ce ?", a: ["Cigogne blanche", "Grue cendrée", "Héron cendré", "Grand cormoran"], x: "En vol, les hérons plient le cou en S et rentrent la tête. Cigognes et grues volent le cou tendu." }, es: { q: "Patas largas hacia atrás, pero el cuello recogido. ¿Quién es?", a: ["Cigüeña blanca", "Grulla común", "Garza real", "Cormorán"], x: "Las garzas doblan el cuello en forma de S y recogen la cabeza al volar. Cigüeñas y grullas vuelan con el cuello estirado." } } },
  { id: "d12", lvl: 3, type: "pic", right: 1, img: ["q-si-swift"], t: { de: { q: "Wer saust da mit sichelförmigen Flügeln über die Dächer?", a: ["Rauchschwalbe", "Mauersegler", "Mehlschwalbe", "Turmfalke"], x: "Sichelflügel und ein kurzer Gabelschwanz: der Mauersegler. Seine Füße sind winzig – auf den Boden setzt er sich fast nie, er krallt sich lieber an Mauern fest." }, en: { q: "Who is racing over the rooftops with sickle-shaped wings?", a: ["Barn swallow", "Common swift", "House martin", "Kestrel"], x: "Sickle wings and a short forked tail: the common swift. Its feet are tiny – it almost never lands on the ground and prefers to cling to walls." }, fr: { q: "Qui file au-dessus des toits avec des ailes en faucille ?", a: ["Hirondelle rustique", "Martinet noir", "Hirondelle de fenêtre", "Faucon crécerelle"], x: "Des ailes en faucille et une courte queue fourchue : le martinet noir. Ses pattes sont minuscules – il ne se pose presque jamais au sol et s’agrippe plutôt aux murs." }, es: { q: "¿Quién pasa volando sobre los tejados con alas en forma de hoz?", a: ["Golondrina común", "Vencejo común", "Avión común", "Cernícalo"], x: "Alas en forma de hoz y una cola corta ahorquillada: el vencejo común. Sus patas son diminutas: casi nunca se posa en el suelo y prefiere agarrarse a las paredes." } } },
  { id: "d13", lvl: 3, type: "pic", right: 1, img: ["q-si-swallow"], t: { de: { q: "Lange Schwanzspieße und spitze Flügel – wer ist das?", a: ["Mauersegler", "Rauchschwalbe", "Rotmilan", "Kuckuck"], x: "Die langen Schwanzspieße gehören der Rauchschwalbe. Der Mauersegler hat längere, sichelförmige Flügel und einen kurzen Schwanz." }, en: { q: "Long tail streamers and pointed wings – who is it?", a: ["Common swift", "Barn swallow", "Red kite", "Cuckoo"], x: "The long tail streamers belong to the barn swallow. A swift has longer, sickle-shaped wings and a short tail." }, fr: { q: "De longs filets à la queue et des ailes pointues – qui est-ce ?", a: ["Martinet noir", "Hirondelle rustique", "Milan royal", "Coucou"], x: "Les longs filets de la queue sont ceux de l’hirondelle rustique. Le martinet a des ailes plus longues en faucille et une queue courte." }, es: { q: "Largas plumas en la cola y alas puntiagudas: ¿quién es?", a: ["Vencejo común", "Golondrina común", "Milano real", "Cuco"], x: "Las largas plumas de la cola son de la golondrina común. El vencejo tiene alas más largas en forma de hoz y la cola corta." } } },
  { id: "d14", lvl: 1, type: "pic", right: 0, img: ["q-fi-beaver"], t: { de: { q: "Wer hat diesen Baum so angenagt?", a: ["Biber", "Wildschwein", "Specht", "Eichhörnchen"], x: "Die Sanduhr-Form ist typisch für den Biber, die Späne liegen drum herum. Er fällt Bäume vor allem, um an Rinde, Zweige und Knospen zu kommen – sein Futter." }, en: { q: "Who gnawed this tree like that?", a: ["Beaver", "Wild boar", "Woodpecker", "Squirrel"], x: "The hourglass shape is typical of a beaver, with chips lying all around. It fells trees mainly to reach the bark, twigs and buds – its food." }, fr: { q: "Qui a rongé cet arbre ainsi ?", a: ["Castor", "Sanglier", "Pic", "Écureuil"], x: "La forme de sablier est typique du castor, avec des copeaux tout autour. Il abat surtout les arbres pour atteindre l’écorce, les rameaux et les bourgeons – sa nourriture." }, es: { q: "¿Quién ha roído este árbol así?", a: ["Castor", "Jabalí", "Pájaro carpintero", "Ardilla"], x: "La forma de reloj de arena es típica del castor, con las virutas alrededor. Derriba árboles sobre todo para llegar a la corteza, las ramitas y los brotes: su comida." } } },
  { id: "d15", lvl: 2, type: "pic", right: 1, img: ["q-fi-mole"], t: { de: { q: "Wer hat diese Erdhügel in der Wiese aufgeworfen?", a: ["Wühlmaus", "Maulwurf", "Igel", "Dachs"], x: "Maulwurfshügel sind hoch und rund, der Gang führt senkrecht in der Mitte nach unten. Hügel von Wühlmäusen sind flacher, ihr Gang liegt seitlich." }, en: { q: "Who threw up these mounds of earth in the meadow?", a: ["Vole", "Mole", "Hedgehog", "Badger"], x: "Molehills are high and round, with the tunnel going straight down in the middle. Vole mounds are flatter and their tunnel is off to the side." }, fr: { q: "Qui a fait ces monticules de terre dans le pré ?", a: ["Campagnol", "Taupe", "Hérisson", "Blaireau"], x: "Les taupinières sont hautes et rondes, la galerie descend tout droit au milieu. Les monticules du campagnol sont plus plats, avec la galerie sur le côté." }, es: { q: "¿Quién ha levantado estos montículos de tierra en el prado?", a: ["Topillo", "Topo", "Erizo", "Tejón"], x: "Las toperas son altas y redondas, y el túnel baja recto por el centro. Los montículos del topillo son más planos y su túnel queda a un lado." } } },
  { id: "d16", lvl: 2, type: "pic", right: 2, img: ["q-fi-woodpecker"], t: { de: { q: "Wer hat dieses runde Loch in den Stamm gezimmert?", a: ["Eichhörnchen", "Waldkauz", "Buntspecht", "Kleiber"], x: "Spechte zimmern sich jedes Jahr neue Höhlen. Die alten werden zur Wohnung für viele andere: Meisen, Kleiber, Fledermäuse oder Eichhörnchen." }, en: { q: "Who carved this round hole into the trunk?", a: ["Squirrel", "Tawny owl", "Great spotted woodpecker", "Nuthatch"], x: "Woodpeckers carve new holes every year. The old ones become homes for many others: tits, nuthatches, bats or squirrels." }, fr: { q: "Qui a creusé ce trou rond dans le tronc ?", a: ["Écureuil", "Chouette hulotte", "Pic épeiche", "Sittelle"], x: "Les pics creusent de nouvelles loges chaque année. Les anciennes servent de logement à bien d’autres : mésanges, sittelles, chauves-souris ou écureuils." }, es: { q: "¿Quién ha hecho este agujero redondo en el tronco?", a: ["Ardilla", "Cárabo", "Pico picapinos", "Trepador azul"], x: "Los pájaros carpinteros excavan nidos nuevos cada año. Los viejos sirven de hogar a muchos otros: carboneros, trepadores, murciélagos o ardillas." } } },
  { id: "d17", lvl: 2, type: "pic", right: 2, img: ["q-fi-wasp"], t: { de: { q: "Woraus bauen Wespen so ein Nest?", a: ["Bienenwachs", "Lehm", "Zerkautem Holz", "Spinnenseide"], x: "Wespen raspeln Holz ab, kauen es mit Speichel durch und bauen daraus papierartige Wände. Wespen waren die ersten Papiermacher." }, en: { q: "What do wasps build a nest like this from?", a: ["Beeswax", "Clay", "Chewed wood", "Spider silk"], x: "Wasps scrape off wood, chew it with saliva and build paper-like walls from it. Wasps were the first paper makers." }, fr: { q: "Avec quoi les guêpes construisent-elles un tel nid ?", a: ["De la cire", "De l’argile", "Du bois mâché", "De la soie d’araignée"], x: "Les guêpes râpent du bois, le mâchent avec leur salive et en font des parois comme du papier. Les guêpes ont été les premières à fabriquer du papier." }, es: { q: "¿Con qué construyen las avispas un nido así?", a: ["Cera de abeja", "Barro", "Madera masticada", "Seda de araña"], x: "Las avispas raspan madera, la mastican con saliva y construyen paredes como de papel. Las avispas fueron las primeras en fabricar papel." } } },
  { id: "d18", lvl: 1, type: "pic", right: 1, img: ["q-fi-ants"], t: { de: { q: "Wer baut solche Hügel aus Nadeln und Zweigen?", a: ["Maulwurf", "Rote Waldameise", "Wildschwein", "Borkenkäfer"], x: "In einem großen Waldameisenhügel können bis zu einer Million Ameisen leben. Unter dem Hügel reicht das Nest oft genauso tief in die Erde." }, en: { q: "Who builds mounds like this from needles and twigs?", a: ["Mole", "Red wood ant", "Wild boar", "Bark beetle"], x: "Up to a million ants can live in a big wood ant mound. Beneath the mound, the nest often reaches just as deep into the ground." }, fr: { q: "Qui construit de tels dômes d’aiguilles et de brindilles ?", a: ["Taupe", "Fourmi rousse des bois", "Sanglier", "Scolyte"], x: "Jusqu’à un million de fourmis peuvent vivre dans une grande fourmilière. Sous le dôme, le nid s’enfonce souvent aussi profond dans le sol." }, es: { q: "¿Quién construye montículos así con agujas y ramitas?", a: ["Topo", "Hormiga roja de bosque", "Jabalí", "Escarabajo de la corteza"], x: "En un gran hormiguero de hormigas de bosque pueden vivir hasta un millón de hormigas. Bajo el montículo, el nido suele llegar igual de hondo en la tierra." } } },
  { id: "d19", lvl: 3, type: "pic", right: 1, img: ["q-fi-spittle"], t: { de: { q: "Was versteckt sich in diesem Schaum am Grashalm?", a: ["Spucke vom Kuckuck", "Larve einer Schaumzikade", "Eier einer Schnecke", "Ein Spinnennest"], x: "Die Larve der Schaumzikade bläst Luft in ihren Saft und baut sich so ein Schaumversteck – gegen Austrocknen und Feinde. Mit dem Kuckuck hat die „Kuckucksspucke“ nichts zu tun." }, en: { q: "What is hiding in this foam on the grass stem?", a: ["Cuckoo spit from a bird", "A froghopper larva", "Snail eggs", "A spider nest"], x: "The froghopper larva blows air into its sap and builds a foam hideout – against drying out and enemies. Despite the name “cuckoo spit”, cuckoos have nothing to do with it." }, fr: { q: "Qui se cache dans cette mousse sur la tige ?", a: ["De la salive de coucou", "Une larve de cercope", "Des œufs d’escargot", "Un nid d’araignée"], x: "La larve du cercope souffle de l’air dans sa sève et se fabrique une cachette de mousse – contre le dessèchement et les ennemis. Le « crachat de coucou » n’a rien à voir avec le coucou." }, es: { q: "¿Qué se esconde en esta espuma del tallo?", a: ["Saliva de cuco", "Una larva de cercópido", "Huevos de caracol", "Un nido de araña"], x: "La larva del cercópido sopla aire en su savia y se construye un escondite de espuma, contra la sequedad y los enemigos. La llamada «saliva de cuco» no tiene nada que ver con el cuco." } } },
  { id: "d20", lvl: 3, type: "pic", right: 1, img: ["q-fi-gall"], t: { de: { q: "Wer wohnt in dieser Kugel am Eichenblatt?", a: ["Raupe eines Falters", "Larve einer Gallwespe", "Junge Spinne", "Überwinternder Käfer"], x: "Die Gallwespe legt ihr Ei ins Blatt, die Eiche bildet darum diese „Galle“. Darin wohnt und frisst die Larve. Aus Galläpfeln machte man früher Tinte." }, en: { q: "Who lives in this ball on the oak leaf?", a: ["A moth caterpillar", "A gall wasp larva", "A young spider", "A beetle spending the winter"], x: "The gall wasp lays its egg in the leaf, and the oak grows this “gall” around it. The larva lives and feeds inside. Oak galls were once used to make ink." }, fr: { q: "Qui habite dans cette boule sur la feuille de chêne ?", a: ["Une chenille de papillon", "Une larve de cynips", "Une jeune araignée", "Un coléoptère qui hiverne"], x: "Le cynips pond son œuf dans la feuille, et le chêne forme autour cette « galle ». La larve y vit et s’y nourrit. On fabriquait autrefois de l’encre avec les galles." }, es: { q: "¿Quién vive en esta bola de la hoja de roble?", a: ["Una oruga de mariposa", "Una larva de avispa de las agallas", "Una araña joven", "Un escarabajo que pasa el invierno"], x: "La avispa de las agallas pone su huevo en la hoja y el roble forma a su alrededor esta «agalla». Dentro vive y come la larva. Antes se hacía tinta con las agallas." } } },
  { id: "d21", lvl: 2, type: "pic", right: 1, img: ["q-fi-pellet"], t: { de: { q: "Grau, fellig, mit kleinen Knochen: Was hast du unter dem Baum gefunden?", a: ["Kot vom Fuchs", "Gewölle einer Eule", "Nest einer Maus", "Haarballen einer Katze"], x: "Ein Gewölle: Fell und Knochen, die die Eule wieder hochgewürgt hat. Aus den winzigen Schädeln darin kann man sogar bestimmen, welche Mäusearten in der Gegend leben." }, en: { q: "Grey, furry, with tiny bones: what did you find under the tree?", a: ["Fox droppings", "An owl pellet", "A mouse nest", "A cat’s hairball"], x: "An owl pellet: fur and bones the owl coughed back up. From the tiny skulls inside you can even tell which kinds of mice live in the area." }, fr: { q: "Gris, poilu, avec de petits os : qu’as-tu trouvé sous l’arbre ?", a: ["Une crotte de renard", "Une pelote de réjection de chouette", "Un nid de souris", "Une boule de poils de chat"], x: "Une pelote de réjection : poils et os recrachés par la chouette. Grâce aux minuscules crânes, on peut même savoir quelles espèces de souris vivent dans le coin." }, es: { q: "Gris, peludo y con huesecillos: ¿qué has encontrado bajo el árbol?", a: ["Excremento de zorro", "Una egagrópila de búho", "Un nido de ratón", "Una bola de pelo de gato"], x: "Una egagrópila: pelo y huesos que el búho ha regurgitado. Por los diminutos cráneos se puede saber incluso qué especies de ratones viven en la zona." } } },
  { id: "c01", lvl: 2, type: "text", right: 1, t: { de: { q: "Welches dieser Tiere hat drei Herzen?", a: ["Krabbe", "Krake", "Hai", "Schnecke"], x: "Kraken haben zwei Kiemenherzen und ein Körperherz, das ihr blaues Blut durch den Körper pumpt." }, en: { q: "Which of these animals has three hearts?", a: ["Crab", "Octopus", "Shark", "Snail"], x: "Octopuses have two gill hearts and one main heart that pumps their blue blood around the body." }, fr: { q: "Lequel de ces animaux a trois cœurs ?", a: ["Crabe", "Pieuvre", "Requin", "Escargot"], x: "La pieuvre a deux cœurs branchiaux et un cœur principal qui pompe son sang bleu dans le corps." }, es: { q: "¿Cuál de estos animales tiene tres corazones?", a: ["Cangrejo", "Pulpo", "Tiburón", "Caracol"], x: "El pulpo tiene dos corazones branquiales y uno principal que bombea su sangre azul por el cuerpo." } } },
  { id: "c02", lvl: 1, type: "text", right: 3, t: { de: { q: "Wer hält einen echten Winterschlaf?", a: ["Eichhörnchen", "Reh", "Fuchs", "Igel"], x: "Im Winterschlaf sinkt die Körpertemperatur des Igels auf etwa 5 °C. Eichhörnchen halten nur Winterruhe." }, en: { q: "Which animal truly hibernates?", a: ["Squirrel", "Roe deer", "Fox", "Hedgehog"], x: "In hibernation a hedgehog's body temperature drops to about 5 °C. Squirrels only rest and wake often to eat." }, fr: { q: "Lequel de ces animaux hiberne vraiment ?", a: ["Écureuil", "Chevreuil", "Renard", "Hérisson"], x: "En hibernation, la température du hérisson descend à environ 5 °C. L'écureuil se réveille souvent pour manger." }, es: { q: "¿Cuál de estos animales hiberna de verdad?", a: ["Ardilla", "Corzo", "Zorro", "Erizo"], x: "Al hibernar, el erizo baja su temperatura a unos 5 °C. La ardilla solo descansa y despierta a menudo para comer." } } },
  { id: "c03", lvl: 1, type: "text", right: 0, t: { de: { q: "Welches Tier hat genau sechs Beine?", a: ["Marienkäfer", "Krake", "Schnecke", "Krabbe"], x: "Alle Insekten haben sechs Beine – auch der Marienkäfer. Krabben haben zehn Beine, Kraken acht Arme." }, en: { q: "Which animal has exactly six legs?", a: ["Ladybird", "Octopus", "Snail", "Crab"], x: "All insects have six legs, including the ladybird. Crabs have ten legs and octopuses eight arms." }, fr: { q: "Quel animal a exactement six pattes ?", a: ["Coccinelle", "Pieuvre", "Escargot", "Crabe"], x: "Tous les insectes ont six pattes, coccinelle comprise. Le crabe en a dix et la pieuvre a huit bras." }, es: { q: "¿Qué animal tiene exactamente seis patas?", a: ["Mariquita", "Pulpo", "Caracol", "Cangrejo"], x: "Todos los insectos tienen seis patas, también la mariquita. El cangrejo tiene diez y el pulpo ocho brazos." } } },
  { id: "c04", lvl: 2, type: "text", right: 1, t: { de: { q: "Wessen Skelett besteht nicht aus Knochen, sondern aus Knorpel?", a: ["Schildkröte", "Hai", "Pinguin", "Frosch"], x: "Haie sind Knorpelfische. Knorpel ist leichter und biegsamer als Knochen – wie in unserer Nase." }, en: { q: "Whose skeleton is made of cartilage instead of bone?", a: ["Turtle", "Shark", "Penguin", "Frog"], x: "Sharks are cartilaginous fish. Cartilage is lighter and more flexible than bone – like in our nose." }, fr: { q: "Quel animal a un squelette fait de cartilage et non d'os ?", a: ["Tortue", "Requin", "Manchot", "Grenouille"], x: "Le requin est un poisson cartilagineux. Le cartilage est plus léger et souple que l'os, comme dans notre nez." }, es: { q: "¿Qué animal tiene un esqueleto de cartílago en vez de hueso?", a: ["Tortuga", "Tiburón", "Pingüino", "Rana"], x: "El tiburón es un pez cartilaginoso. El cartílago es más ligero y flexible que el hueso, como el de la nariz." } } },
  { id: "c05", lvl: 1, type: "text", right: 3, t: { de: { q: "Welcher Vogel verdankt seine Farbe seiner Nahrung?", a: ["Papagei", "Adler", "Eule", "Flamingo"], x: "Flamingos fressen Algen und Kleinkrebse voller Carotinoide. Ohne diese Farbstoffe würden sie blass." }, en: { q: "Which bird gets its colour from its food?", a: ["Parrot", "Eagle", "Owl", "Flamingo"], x: "Flamingos eat algae and tiny shrimp full of carotenoids. Without these pigments they would turn pale." }, fr: { q: "Quel oiseau doit sa couleur à sa nourriture ?", a: ["Perroquet", "Aigle", "Chouette", "Flamant rose"], x: "Le flamant rose mange des algues et petites crevettes riches en caroténoïdes. Sans eux, il pâlirait." }, es: { q: "¿Qué ave debe su color a su alimento?", a: ["Loro", "Águila", "Búho", "Flamenco"], x: "El flamenco come algas y pequeños crustáceos con carotenoides. Sin esos pigmentos se volvería pálido." } } },
  { id: "c06", lvl: 2, type: "text", right: 0, t: { de: { q: "Welcher Vogel legt im Verhältnis zu seinem Körper das größte Ei?", a: ["Kiwi", "Strauß", "Haushuhn", "Kaiserpinguin"], x: "Ein Kiwi-Ei wiegt rund ein Fünftel so viel wie das Weibchen selbst. Das Straußenei ist zwar das größte Ei überhaupt, für den riesigen Strauß aber eher klein." }, en: { q: "Which bird lays the biggest egg compared to its body?", a: ["Kiwi", "Ostrich", "Chicken", "Emperor penguin"], x: "A kiwi egg weighs about a fifth as much as the female herself. The ostrich egg is the biggest egg of all, but quite small for such a huge bird." }, fr: { q: "Quel oiseau pond le plus gros œuf par rapport à son corps ?", a: ["Kiwi", "Autruche", "Poule", "Manchot empereur"], x: "Un œuf de kiwi pèse environ un cinquième du poids de la femelle. L’œuf d’autruche est le plus gros de tous, mais plutôt petit pour un oiseau aussi grand." }, es: { q: "¿Qué ave pone el huevo más grande en relación con su cuerpo?", a: ["Kiwi", "Avestruz", "Gallina", "Pingüino emperador"], x: "Un huevo de kiwi pesa alrededor de una quinta parte de lo que pesa la hembra. El de avestruz es el huevo más grande de todos, pero pequeño para un ave tan enorme." } } },
  { id: "c07", lvl: 3, type: "text", right: 2, t: { de: { q: "Welches Tier hat einen verlängerten Handgelenksknochen, der wie ein zusätzlicher Daumen wirkt?", a: ["Otter", "Eichhörnchen", "Panda", "Tiger"], x: "Der „Pseudodaumen“ des Pandas ist ein vergrößerter Handgelenksknochen. Damit hält er Bambus fest." }, en: { q: "Which animal has an enlarged wrist bone that works like an extra thumb?", a: ["Otter", "Squirrel", "Panda", "Tiger"], x: "The panda's 'pseudo-thumb' is an enlarged wrist bone. It helps the panda grip bamboo stems." }, fr: { q: "Quel animal possède un os du poignet allongé qui sert de pouce supplémentaire ?", a: ["Loutre", "Écureuil", "Panda", "Tigre"], x: "Le « faux pouce » du panda est un os du poignet agrandi. Il l'aide à tenir les tiges de bambou." }, es: { q: "¿Qué animal tiene un hueso de la muñeca alargado que funciona como un pulgar extra?", a: ["Nutria", "Ardilla", "Panda", "Tigre"], x: "El «falso pulgar» del panda es un hueso de la muñeca agrandado. Le sirve para sujetar el bambú." } } },
  { id: "c08", lvl: 2, type: "text", right: 0, t: { de: { q: "Welches Tier hat eine etwa 45 cm lange, dunkelblaue Zunge?", a: ["Giraffe", "Reh", "Tiger", "Panda"], x: "Die dunkle Farbe schützt die Giraffenzunge vermutlich vor Sonnenbrand, wenn sie Akazienblätter zupft." }, en: { q: "Which animal has a dark blue tongue about 45 cm long?", a: ["Giraffe", "Roe deer", "Tiger", "Panda"], x: "The dark colour probably protects the giraffe's tongue from sunburn while it plucks acacia leaves." }, fr: { q: "Quel animal a une langue bleu foncé d'environ 45 cm ?", a: ["Girafe", "Chevreuil", "Tigre", "Panda"], x: "Sa couleur sombre protégerait la langue de la girafe du soleil quand elle cueille des feuilles d'acacia." }, es: { q: "¿Qué animal tiene una lengua azul oscuro de unos 45 cm?", a: ["Jirafa", "Corzo", "Tigre", "Panda"], x: "Su color oscuro protegería la lengua de la jirafa del sol mientras arranca hojas de acacia." } } },
  { id: "c09", lvl: 2, type: "text", right: 3, t: { de: { q: "Bei welchem Tier ist auch die Haut unter dem Fell gestreift?", a: ["Fuchs", "Reh", "Eichhörnchen", "Tiger"], x: "Unter den dunklen Streifen ist auch die Haut des Tigers dunkel. Rasiert sähe man das Muster noch." }, en: { q: "Which animal has striped skin underneath its fur too?", a: ["Fox", "Roe deer", "Squirrel", "Tiger"], x: "A tiger's skin is dark under its dark stripes, so the pattern would still show if it were shaved." }, fr: { q: "Chez quel animal la peau sous le pelage est-elle aussi rayée ?", a: ["Renard", "Chevreuil", "Écureuil", "Tigre"], x: "Sous les rayures sombres du tigre, la peau est foncée : rasé, il garderait son motif." }, es: { q: "¿En qué animal también la piel bajo el pelaje tiene rayas?", a: ["Zorro", "Corzo", "Ardilla", "Tigre"], x: "Bajo las rayas oscuras del tigre la piel también es oscura: aunque lo afeitaran, se verían las rayas." } } },
  { id: "c10", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer kann beim Tauchen Ohren und Nasenlöcher verschließen?", a: ["Tiger", "Otter", "Fuchs", "Giraffe"], x: "Otter verschließen unter Wasser Ohren und Nase und können mehrere Minuten lang tauchen." }, en: { q: "Which animal can close its ears and nostrils when diving?", a: ["Tiger", "Otter", "Fox", "Giraffe"], x: "Otters seal their ears and nostrils underwater and can stay down for several minutes." }, fr: { q: "Quel animal peut fermer ses oreilles et ses narines en plongée ?", a: ["Tigre", "Loutre", "Renard", "Girafe"], x: "La loutre ferme oreilles et narines sous l'eau et peut plonger plusieurs minutes." }, es: { q: "¿Qué animal puede cerrar orejas y fosas nasales al bucear?", a: ["Tigre", "Nutria", "Zorro", "Jirafa"], x: "La nutria cierra orejas y nariz bajo el agua y puede bucear varios minutos." } } },
  { id: "c11", lvl: 3, type: "text", right: 3, t: { de: { q: "Wer hat über den Augen eine Drüse, die Salz aus Meerwasser ausscheidet?", a: ["Eule", "Otter", "Papagei", "Pinguin"], x: "Pinguine können Meerwasser trinken: Die Salzdrüse filtert das Salz, das dann über den Schnabel abtropft." }, en: { q: "Which animal has a gland above its eyes that removes salt from seawater?", a: ["Owl", "Otter", "Parrot", "Penguin"], x: "Penguins can drink seawater: a salt gland filters out the salt, which then drips off the beak." }, fr: { q: "Quel animal a au-dessus des yeux une glande qui élimine le sel de l'eau de mer ?", a: ["Chouette", "Loutre", "Perroquet", "Manchot"], x: "Le manchot peut boire de l'eau de mer : une glande filtre le sel, qui s'écoule par le bec." }, es: { q: "¿Qué animal tiene sobre los ojos una glándula que elimina la sal del agua de mar?", a: ["Búho", "Nutria", "Loro", "Pingüino"], x: "El pingüino puede beber agua de mar: una glándula filtra la sal, que luego gotea por el pico." } } },
  { id: "c12", lvl: 2, type: "text", right: 0, t: { de: { q: "Wer hat eine Raspelzunge mit Tausenden winziger Zähnchen?", a: ["Schnecke", "Schmetterling", "Schildkröte", "Biene"], x: "Die Raspelzunge (Radula) der Schnecke wirkt wie eine Feile. Abgenutzte Zähnchen wachsen ständig nach." }, en: { q: "Which animal has a rasping tongue with thousands of tiny teeth?", a: ["Snail", "Butterfly", "Turtle", "Bee"], x: "A snail's radula works like a file. Worn-out teeth are constantly replaced by new ones." }, fr: { q: "Quel animal a une langue râpeuse couverte de milliers de petites dents ?", a: ["Escargot", "Papillon", "Tortue", "Abeille"], x: "La radula de l'escargot fonctionne comme une lime. Les dents usées sont sans cesse remplacées." }, es: { q: "¿Qué animal tiene una lengua raspadora con miles de dientecillos?", a: ["Caracol", "Mariposa", "Tortuga", "Abeja"], x: "La rádula del caracol funciona como una lima. Los dientes gastados se reemplazan continuamente." } } },
  { id: "c13", lvl: 3, type: "text", right: 2, t: { de: { q: "Wer kann die schwachen elektrischen Felder seiner Beute spüren?", a: ["Krake", "Pinguin", "Hai", "Otter"], x: "Haie haben Lorenzinische Ampullen: Poren an der Schnauze, die den Strom der Muskeln versteckter Beute spüren." }, en: { q: "Which animal can sense the weak electric fields of its prey?", a: ["Octopus", "Penguin", "Shark", "Otter"], x: "Sharks have ampullae of Lorenzini: snout pores that detect electricity from the muscles of hidden prey." }, fr: { q: "Quel animal perçoit les faibles champs électriques de ses proies ?", a: ["Pieuvre", "Manchot", "Requin", "Loutre"], x: "Le requin a des ampoules de Lorenzini : des pores du museau qui captent l'électricité des proies cachées." }, es: { q: "¿Qué animal percibe los débiles campos eléctricos de sus presas?", a: ["Pulpo", "Pingüino", "Tiburón", "Nutria"], x: "El tiburón tiene ampollas de Lorenzini: poros del hocico que captan la electricidad de presas ocultas." } } },
  { id: "c14", lvl: 1, type: "text", right: 0, t: { de: { q: "Wer zeigt seinen Artgenossen mit einem Tanz, wo es Futter gibt?", a: ["Biene", "Schmetterling", "Marienkäfer", "Krabbe"], x: "Mit dem Schwänzeltanz teilt die Biene Richtung und Entfernung einer Futterquelle mit." }, en: { q: "Which animal uses a dance to tell others where to find food?", a: ["Bee", "Butterfly", "Ladybird", "Crab"], x: "With its waggle dance, a bee tells its nestmates the direction and distance of a food source." }, fr: { q: "Quel animal indique aux autres par une danse où trouver de la nourriture ?", a: ["Abeille", "Papillon", "Coccinelle", "Crabe"], x: "Par sa danse frétillante, l'abeille indique la direction et la distance d'une source de nourriture." }, es: { q: "¿Qué animal indica con un baile dónde hay comida?", a: ["Abeja", "Mariposa", "Mariquita", "Cangrejo"], x: "Con su danza del contoneo, la abeja comunica la dirección y la distancia de una fuente de alimento." } } },
  { id: "c15", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer schmeckt mit den Füßen?", a: ["Eule", "Schmetterling", "Frosch", "Eidechse"], x: "Schmetterlinge haben Geschmackssinneszellen an den Füßen. So prüfen Weibchen, ob eine Pflanze für ihre Eier taugt." }, en: { q: "Which animal tastes with its feet?", a: ["Owl", "Butterfly", "Frog", "Lizard"], x: "Butterflies have taste sensors on their feet. Females use them to check if a plant suits their eggs." }, fr: { q: "Quel animal goûte avec ses pattes ?", a: ["Chouette", "Papillon", "Grenouille", "Lézard"], x: "Le papillon a des capteurs du goût sur les pattes. La femelle vérifie ainsi si une plante convient à ses œufs." }, es: { q: "¿Qué animal saborea con las patas?", a: ["Búho", "Mariposa", "Rana", "Lagarto"], x: "La mariposa tiene sensores del gusto en las patas. Así la hembra comprueba si una planta sirve para sus huevos." } } },
  { id: "c16", lvl: 3, type: "text", right: 3, t: { de: { q: "Wer presst bei Gefahr bitteres, gelbes Blut aus seinen Beingelenken?", a: ["Biene", "Schmetterling", "Schnecke", "Marienkäfer"], x: "Dieses „Reflexbluten“ schreckt Fressfeinde ab: Die gelbe Flüssigkeit des Marienkäfers schmeckt bitter." }, en: { q: "Which animal squeezes bitter yellow blood from its leg joints when threatened?", a: ["Bee", "Butterfly", "Snail", "Ladybird"], x: "This 'reflex bleeding' deters predators: the ladybird's yellow fluid tastes bitter and smells bad." }, fr: { q: "Quel animal fait sortir un sang jaune et amer de ses articulations en cas de danger ?", a: ["Abeille", "Papillon", "Escargot", "Coccinelle"], x: "Ce « saignement réflexe » repousse les prédateurs : le liquide jaune de la coccinelle est amer." }, es: { q: "¿Qué animal expulsa sangre amarilla y amarga por las articulaciones de las patas ante un peligro?", a: ["Abeja", "Mariposa", "Caracol", "Mariquita"], x: "Este «sangrado reflejo» ahuyenta a los depredadores: el líquido amarillo de la mariquita es amargo." } } },
  { id: "c17", lvl: 1, type: "text", right: 2, t: { de: { q: "Wer kann bei Gefahr seinen Schwanz abwerfen?", a: ["Schildkröte", "Igel", "Eidechse", "Papagei"], x: "Der abgeworfene Eidechsenschwanz zappelt weiter und lenkt den Feind ab. Er wächst nach, aber kürzer." }, en: { q: "Which animal can shed its tail when in danger?", a: ["Turtle", "Hedgehog", "Lizard", "Parrot"], x: "A lizard's dropped tail keeps wriggling to distract the enemy. It grows back, but shorter." }, fr: { q: "Quel animal peut abandonner sa queue en cas de danger ?", a: ["Tortue", "Hérisson", "Lézard", "Perroquet"], x: "La queue du lézard continue de gigoter pour distraire l'ennemi. Elle repousse, mais plus courte." }, es: { q: "¿Qué animal puede soltar su cola ante un peligro?", a: ["Tortuga", "Erizo", "Lagarto", "Loro"], x: "La cola del lagarto sigue moviéndose y distrae al enemigo. Vuelve a crecer, pero más corta." } } },
  { id: "c18", lvl: 3, type: "text", right: 3, t: { de: { q: "Wer drückt beim Schlucken seine Augen nach innen, um die Beute hinunterzuschieben?", a: ["Eule", "Papagei", "Otter", "Frosch"], x: "Frösche ziehen beim Schlucken die Augäpfel ein. Diese drücken von oben auf den Bissen und schieben ihn in den Schlund." }, en: { q: "Which animal pulls its eyes inward when swallowing to push food down?", a: ["Owl", "Parrot", "Otter", "Frog"], x: "Frogs retract their eyeballs when swallowing. They press on the food from above and push it down the throat." }, fr: { q: "Quel animal enfonce ses yeux en avalant pour pousser sa proie vers le bas ?", a: ["Chouette", "Perroquet", "Loutre", "Grenouille"], x: "En avalant, la grenouille rentre ses yeux. Ils appuient sur la proie et la poussent dans la gorge." }, es: { q: "¿Qué animal hunde los ojos al tragar para empujar la comida?", a: ["Búho", "Loro", "Nutria", "Rana"], x: "Al tragar, la rana hunde los ojos. Estos presionan el bocado desde arriba y lo empujan a la garganta." } } },
  { id: "c19", lvl: 2, type: "text", right: 1, t: { de: { q: "Wessen Blut ist durch Kupfer bläulich gefärbt?", a: ["Hai", "Krabbe", "Frosch", "Pinguin"], x: "Krabben transportieren Sauerstoff mit Hämocyanin, das Kupfer enthält. Unser Blut ist durch Eisen rot." }, en: { q: "Whose blood is bluish because of copper?", a: ["Shark", "Crab", "Frog", "Penguin"], x: "Crabs carry oxygen with haemocyanin, which contains copper. Our blood is red because of iron." }, fr: { q: "Quel animal a un sang bleuté à cause du cuivre ?", a: ["Requin", "Crabe", "Grenouille", "Manchot"], x: "Le crabe transporte l'oxygène avec l'hémocyanine, qui contient du cuivre. Notre sang est rouge grâce au fer." }, es: { q: "¿Qué animal tiene la sangre azulada por el cobre?", a: ["Tiburón", "Cangrejo", "Rana", "Pingüino"], x: "El cangrejo transporta oxígeno con hemocianina, que contiene cobre. Nuestra sangre es roja por el hierro." } } },
  { id: "c20", lvl: 1, type: "text", right: 0, t: { de: { q: "Wer hat zehn Beine – die Scheren mitgezählt?", a: ["Krabbe", "Biene", "Krake", "Marienkäfer"], x: "Krabben gehören zu den Zehnfußkrebsen. Das vorderste Beinpaar ist zu kräftigen Scheren umgebaut." }, en: { q: "Which animal has ten legs, counting its claws?", a: ["Crab", "Bee", "Octopus", "Ladybird"], x: "Crabs are decapods ('ten-footed'). Their front pair of legs has become strong claws." }, fr: { q: "Quel animal a dix pattes, pinces comprises ?", a: ["Crabe", "Abeille", "Pieuvre", "Coccinelle"], x: "Le crabe est un décapode (« dix pieds »). Sa première paire de pattes forme de puissantes pinces." }, es: { q: "¿Qué animal tiene diez patas, contando las pinzas?", a: ["Cangrejo", "Abeja", "Pulpo", "Mariquita"], x: "El cangrejo es un decápodo («diez pies»). Su primer par de patas se ha convertido en fuertes pinzas." } } },
  { id: "c21", lvl: 1, type: "text", right: 0, t: { de: { q: "Wer passt durch ein Loch, das kaum größer ist als sein Schnabel?", a: ["Krake", "Hai", "Krabbe", "Schildkröte"], x: "Kraken haben keine Knochen. Nur ihr harter Schnabel bestimmt, durch welche Öffnung sie schlüpfen können." }, en: { q: "Which animal can squeeze through a hole barely bigger than its beak?", a: ["Octopus", "Shark", "Crab", "Turtle"], x: "Octopuses have no bones. Only their hard beak limits which openings they can slip through." }, fr: { q: "Quel animal peut passer par un trou à peine plus grand que son bec ?", a: ["Pieuvre", "Requin", "Crabe", "Tortue"], x: "La pieuvre n'a pas d'os. Seul son bec dur limite les ouvertures par lesquelles elle peut se faufiler." }, es: { q: "¿Qué animal cabe por un agujero apenas mayor que su pico?", a: ["Pulpo", "Tiburón", "Cangrejo", "Tortuga"], x: "El pulpo no tiene huesos. Solo su pico duro limita las aberturas por las que puede colarse." } } },
  { id: "c22", lvl: 3, type: "text", right: 3, t: { de: { q: "Bei welchem Vogel zeigen zwei Zehen nach vorn und zwei nach hinten?", a: ["Adler", "Flamingo", "Pinguin", "Papagei"], x: "Papageien haben Kletterfüße. Damit greifen sie Äste und halten ihr Futter wie mit einer Hand." }, en: { q: "Which bird has two toes pointing forward and two pointing back?", a: ["Eagle", "Flamingo", "Penguin", "Parrot"], x: "Parrots have zygodactyl feet to grip branches and hold food as if with a hand." }, fr: { q: "Chez quel oiseau deux doigts pointent vers l'avant et deux vers l'arrière ?", a: ["Aigle", "Flamant rose", "Manchot", "Perroquet"], x: "Le perroquet a des pieds zygodactyles : il agrippe les branches et tient sa nourriture comme une main." }, es: { q: "¿En qué ave dos dedos apuntan hacia delante y dos hacia atrás?", a: ["Águila", "Flamenco", "Pingüino", "Loro"], x: "El loro tiene patas zigodáctilas: se agarra a las ramas y sujeta la comida como con una mano." } } },
  { id: "c23", lvl: 2, type: "text", right: 2, t: { de: { q: "Welcher Vogel hat schwere, massive Knochen statt luftgefüllter?", a: ["Adler", "Eule", "Pinguin", "Papagei"], x: "Flugvögel haben hohle Knochen. Pinguine brauchen schwere Knochen, damit sie beim Tauchen nicht auftreiben." }, en: { q: "Which bird has heavy, solid bones instead of air-filled ones?", a: ["Eagle", "Owl", "Penguin", "Parrot"], x: "Flying birds have hollow bones. Penguins need heavy bones so they don't float up while diving." }, fr: { q: "Quel oiseau a des os lourds et pleins au lieu d'os remplis d'air ?", a: ["Aigle", "Chouette", "Manchot", "Perroquet"], x: "Les oiseaux volants ont des os creux. Le manchot a besoin d'os lourds pour ne pas remonter en plongée." }, es: { q: "¿Qué ave tiene huesos pesados y macizos en lugar de huecos?", a: ["Águila", "Búho", "Pingüino", "Loro"], x: "Las aves voladoras tienen huesos huecos. El pingüino necesita huesos pesados para no flotar al bucear." } } },
  { id: "c24", lvl: 2, type: "text", right: 0, t: { de: { q: "Welches dieser Säugetiere hat den höchsten Blutdruck?", a: ["Giraffe", "Tiger", "Bär", "Panda"], x: "Das Giraffenherz wiegt etwa 11 kg und muss das Blut rund 2 Meter hoch bis zum Kopf pumpen." }, en: { q: "Which of these mammals has the highest blood pressure?", a: ["Giraffe", "Tiger", "Bear", "Panda"], x: "A giraffe's heart weighs about 11 kg and must pump blood some 2 metres up to its head." }, fr: { q: "Lequel de ces mammifères a la pression artérielle la plus élevée ?", a: ["Girafe", "Tigre", "Ours", "Panda"], x: "Le cœur de la girafe pèse environ 11 kg et doit pomper le sang à près de 2 mètres jusqu'à la tête." }, es: { q: "¿Cuál de estos mamíferos tiene la presión arterial más alta?", a: ["Jirafa", "Tigre", "Oso", "Panda"], x: "El corazón de la jirafa pesa unos 11 kg y debe bombear la sangre unos 2 metros hasta la cabeza." } } },
  { id: "c25", lvl: 3, type: "text", right: 2, t: { de: { q: "Wer hat auffällige weiße Flecken auf der Rückseite der Ohren?", a: ["Panda", "Fuchs", "Tiger", "Bär"], x: "Die weißen Ohrflecken des Tigers dienen vermutlich als Signal für die Jungen, die der Mutter folgen." }, en: { q: "Which animal has striking white spots on the back of its ears?", a: ["Panda", "Fox", "Tiger", "Bear"], x: "A tiger's white ear spots probably act as a signal for cubs following their mother." }, fr: { q: "Quel animal a des taches blanches bien visibles à l'arrière des oreilles ?", a: ["Panda", "Renard", "Tigre", "Ours"], x: "Les taches blanches derrière les oreilles du tigre serviraient de repère aux petits qui suivent leur mère." }, es: { q: "¿Qué animal tiene llamativas manchas blancas detrás de las orejas?", a: ["Panda", "Zorro", "Tigre", "Oso"], x: "Las manchas blancas de las orejas del tigre servirían de señal a las crías que siguen a su madre." } } },
  { id: "c26", lvl: 3, type: "text", right: 3, t: { de: { q: "Wessen Neugeborenes wiegt nur etwa ein Neunhundertstel seiner Mutter?", a: ["Giraffe", "Tiger", "Otter", "Panda"], x: "Ein Pandababy wiegt bei der Geburt nur rund 100 g – etwa so viel wie eine Tafel Schokolade." }, en: { q: "Whose newborn weighs only about 1/900 of its mother?", a: ["Giraffe", "Tiger", "Otter", "Panda"], x: "A newborn panda weighs only about 100 g – roughly as much as a bar of chocolate." }, fr: { q: "Quel nouveau-né ne pèse qu'environ 1/900 du poids de sa mère ?", a: ["Girafe", "Tigre", "Loutre", "Panda"], x: "Un bébé panda pèse environ 100 g à la naissance, à peu près le poids d'une tablette de chocolat." }, es: { q: "¿Qué cría recién nacida pesa solo 1/900 de lo que pesa su madre?", a: ["Jirafa", "Tigre", "Nutria", "Panda"], x: "Un panda recién nacido pesa unos 100 g, más o menos lo que una tableta de chocolate." } } },
  { id: "c27", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer ist ein Sohlengänger und setzt beim Gehen die ganze Fußsohle auf?", a: ["Fuchs", "Bär", "Tiger", "Reh"], x: "Bären laufen wie wir auf der ganzen Sohle. Fuchs und Tiger sind Zehengänger, das Reh geht auf Hufen." }, en: { q: "Which animal walks flat-footed, placing its whole sole on the ground?", a: ["Fox", "Bear", "Tiger", "Roe deer"], x: "Bears walk on their whole soles like us. Foxes and tigers walk on their toes, roe deer on hooves." }, fr: { q: "Quel animal est plantigrade et pose toute la plante du pied en marchant ?", a: ["Renard", "Ours", "Tigre", "Chevreuil"], x: "L'ours marche sur toute la plante comme nous. Renard et tigre marchent sur les doigts, le chevreuil sur ses sabots." }, es: { q: "¿Qué animal es plantígrado y apoya toda la planta del pie al caminar?", a: ["Zorro", "Oso", "Tigre", "Corzo"], x: "El oso camina sobre toda la planta, como nosotros. Zorro y tigre apoyan los dedos; el corzo, las pezuñas." } } },
  { id: "c28", lvl: 1, type: "text", right: 0, t: { de: { q: "Welches Tier zählt zu den Raubtieren, frisst aber fast nur Pflanzen?", a: ["Panda", "Otter", "Tiger", "Fuchs"], x: "Der Panda gehört zu den Bären, frisst aber zu 99 % Bambus – bis zu 12 Stunden am Tag." }, en: { q: "Which animal belongs to the carnivores but eats almost only plants?", a: ["Panda", "Otter", "Tiger", "Fox"], x: "The panda is a bear, yet 99% of its diet is bamboo – it eats for up to 12 hours a day." }, fr: { q: "Quel animal fait partie des carnivores mais mange presque uniquement des plantes ?", a: ["Panda", "Loutre", "Tigre", "Renard"], x: "Le panda est un ours, mais il se nourrit à 99 % de bambou, jusqu'à 12 heures par jour." }, es: { q: "¿Qué animal pertenece a los carnívoros pero come casi solo plantas?", a: ["Panda", "Nutria", "Tigre", "Zorro"], x: "El panda es un oso, pero el 99 % de su dieta es bambú: come hasta 12 horas al día." } } },
  { id: "c29", lvl: 1, type: "text", right: 0, t: { de: { q: "Welcher Vogel sieht etwa vier- bis fünfmal schärfer als ein Mensch?", a: ["Adler", "Flamingo", "Eule", "Pinguin"], x: "Adler haben viel dichter gepackte Sehzellen als wir und erkennen Beute schon aus großer Höhe." }, en: { q: "Which bird sees about four to five times more sharply than a human?", a: ["Eagle", "Flamingo", "Owl", "Penguin"], x: "Eagles have far more densely packed visual cells than we do and spot prey from great heights." }, fr: { q: "Quel oiseau voit environ quatre à cinq fois plus net qu'un humain ?", a: ["Aigle", "Flamant rose", "Chouette", "Manchot"], x: "L'aigle a des cellules visuelles bien plus serrées que les nôtres et repère ses proies de très haut." }, es: { q: "¿Qué ave ve unas cuatro o cinco veces más nítido que un humano?", a: ["Águila", "Flamenco", "Búho", "Pingüino"], x: "El águila tiene células visuales mucho más densas que las nuestras y detecta presas desde gran altura." } } },
  { id: "c30", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer baut riesige Nester aus Ästen, die oft viele Jahre genutzt werden?", a: ["Eule", "Adler", "Flamingo", "Papagei"], x: "Adlerhorste werden jedes Jahr weiter ausgebaut und können über 2 m breit und sehr schwer werden." }, en: { q: "Which bird builds huge stick nests that are often used for many years?", a: ["Owl", "Eagle", "Flamingo", "Parrot"], x: "Eagles add to their nests (eyries) every year; they can grow over 2 m wide and very heavy." }, fr: { q: "Quel oiseau construit d'énormes nids de branches souvent utilisés pendant des années ?", a: ["Chouette", "Aigle", "Flamant rose", "Perroquet"], x: "L'aigle agrandit son aire chaque année ; elle peut dépasser 2 m de large et devenir très lourde." }, es: { q: "¿Qué ave construye enormes nidos de ramas que usa durante muchos años?", a: ["Búho", "Águila", "Flamenco", "Loro"], x: "El águila amplía su nido cada año; puede superar los 2 m de ancho y llegar a pesar muchísimo." } } },
  { id: "c31", lvl: 1, type: "text", right: 3, t: { de: { q: "Welcher Vogel fliegt fast lautlos?", a: ["Adler", "Papagei", "Flamingo", "Eule"], x: "Kammartig gezackte Federkanten verwirbeln die Luft leise – so hört die Maus die Eule nicht kommen." }, en: { q: "Which bird flies almost silently?", a: ["Eagle", "Parrot", "Flamingo", "Owl"], x: "Comb-like edges on its feathers soften the air flow, so a mouse can't hear the owl coming." }, fr: { q: "Quel oiseau vole presque sans bruit ?", a: ["Aigle", "Perroquet", "Flamant rose", "Chouette"], x: "Le bord en peigne de ses plumes adoucit le flux d'air : la souris n'entend pas arriver la chouette." }, es: { q: "¿Qué ave vuela casi en silencio?", a: ["Águila", "Loro", "Flamenco", "Búho"], x: "Los bordes en forma de peine de sus plumas suavizan el aire: el ratón no oye llegar al búho." } } },
  { id: "c32", lvl: 3, type: "text", right: 1, t: { de: { q: "Wer hat MEHR Halswirbel als der Mensch?", a: ["Giraffe", "Eule", "Tiger", "Otter"], x: "Eulen haben 14 Halswirbel. Giraffen haben trotz ihres langen Halses wie fast alle Säugetiere nur 7." }, en: { q: "Which animal has MORE neck vertebrae than a human?", a: ["Giraffe", "Owl", "Tiger", "Otter"], x: "Owls have 14 neck vertebrae. Despite its long neck, a giraffe has only 7, like almost all mammals." }, fr: { q: "Lequel a PLUS de vertèbres cervicales que l'humain ?", a: ["Girafe", "Chouette", "Tigre", "Loutre"], x: "La chouette en a 14. Malgré son long cou, la girafe n'en a que 7, comme presque tous les mammifères." }, es: { q: "¿Quién tiene MÁS vértebras cervicales que el ser humano?", a: ["Jirafa", "Búho", "Tigre", "Nutria"], x: "El búho tiene 14. Pese a su largo cuello, la jirafa solo tiene 7, como casi todos los mamíferos." } } },
  { id: "c33", lvl: 1, type: "text", right: 1, t: { de: { q: "Wer pflanzt unabsichtlich Bäume, weil er Vorräte vergräbt und vergisst?", a: ["Igel", "Eichhörnchen", "Reh", "Schnecke"], x: "Eichhörnchen vergraben im Herbst Nüsse und Samen. Vergessene Vorräte keimen und werden zu neuen Bäumen." }, en: { q: "Which animal plants trees by accident by burying and forgetting food?", a: ["Hedgehog", "Squirrel", "Roe deer", "Snail"], x: "Squirrels bury nuts and seeds in autumn. Forgotten stores sprout and grow into new trees." }, fr: { q: "Quel animal plante des arbres sans le vouloir en oubliant ses réserves enterrées ?", a: ["Hérisson", "Écureuil", "Chevreuil", "Escargot"], x: "L'écureuil enterre noix et graines en automne. Les réserves oubliées germent et deviennent des arbres." }, es: { q: "¿Qué animal planta árboles sin querer al enterrar y olvidar sus provisiones?", a: ["Erizo", "Ardilla", "Corzo", "Caracol"], x: "La ardilla entierra nueces y semillas en otoño. Las reservas olvidadas germinan y se vuelven árboles." } } },
  { id: "c34", lvl: 2, type: "text", right: 0, t: { de: { q: "Wessen Schneidezähne wachsen ein Leben lang nach?", a: ["Eichhörnchen", "Igel", "Fuchs", "Otter"], x: "Eichhörnchen sind Nagetiere. Ihre Nagezähne wachsen ständig und werden beim Nagen abgeschliffen." }, en: { q: "Whose front teeth keep growing throughout life?", a: ["Squirrel", "Hedgehog", "Fox", "Otter"], x: "Squirrels are rodents. Their incisors grow constantly and are worn down by gnawing." }, fr: { q: "Quel animal a des incisives qui poussent toute sa vie ?", a: ["Écureuil", "Hérisson", "Renard", "Loutre"], x: "L'écureuil est un rongeur. Ses incisives poussent sans cesse et s'usent en rongeant." }, es: { q: "¿Qué animal tiene incisivos que crecen toda la vida?", a: ["Ardilla", "Erizo", "Zorro", "Nutria"], x: "La ardilla es un roedor. Sus incisivos crecen sin parar y se desgastan al roer." } } },
  { id: "c35", lvl: 2, type: "text", right: 3, t: { de: { q: "Wer kann kopfüber einen Baumstamm hinunterlaufen?", a: ["Otter", "Igel", "Reh", "Eichhörnchen"], x: "Eichhörnchen drehen ihre Hinterfüße nach hinten und krallen sich so beim Abstieg kopfüber fest." }, en: { q: "Which animal can run head-first down a tree trunk?", a: ["Otter", "Hedgehog", "Roe deer", "Squirrel"], x: "Squirrels rotate their hind feet backwards so their claws can grip while climbing down head-first." }, fr: { q: "Quel animal peut descendre un tronc d'arbre la tête la première ?", a: ["Loutre", "Hérisson", "Chevreuil", "Écureuil"], x: "L'écureuil tourne ses pattes arrière vers l'arrière pour s'agripper en descendant la tête en bas." }, es: { q: "¿Qué animal puede bajar por un tronco cabeza abajo?", a: ["Nutria", "Erizo", "Corzo", "Ardilla"], x: "La ardilla gira sus patas traseras hacia atrás para agarrarse con las uñas al bajar cabeza abajo." } } },
  { id: "c36", lvl: 3, type: "text", right: 1, t: { de: { q: "Wer kaut manchmal fremde Stoffe zu Schaum und reibt ihn sich auf den Rücken?", a: ["Fuchs", "Igel", "Reh", "Eichhörnchen"], x: "Dieses „Selbstbespeicheln“ des Igels ist noch rätselhaft – vielleicht Schutz oder ein Duftsignal." }, en: { q: "Which animal sometimes chews strange substances into foam and spreads it on its back?", a: ["Fox", "Hedgehog", "Roe deer", "Squirrel"], x: "This 'self-anointing' by hedgehogs is still a mystery – maybe protection or a scent signal." }, fr: { q: "Quel animal mâche parfois des substances jusqu'à faire de la mousse et l'étale sur son dos ?", a: ["Renard", "Hérisson", "Chevreuil", "Écureuil"], x: "Cette « auto-onction » du hérisson reste un mystère : protection ou signal olfactif ?" }, es: { q: "¿Qué animal mastica a veces sustancias hasta hacer espuma y se la unta en el lomo?", a: ["Zorro", "Erizo", "Corzo", "Ardilla"], x: "Esta «autounción» del erizo sigue siendo un misterio: quizá protección o una señal de olor." } } },
  { id: "c37", lvl: 1, type: "text", right: 1, t: { de: { q: "Wer wirft jedes Jahr sein Geweih ab und bildet ein neues?", a: ["Giraffe", "Reh", "Panda", "Tiger"], x: "Der Rehbock wirft sein Geweih im Herbst ab. Das neue aus Knochen wächst unter einer Basthaut nach." }, en: { q: "Which animal sheds its antlers every year and grows new ones?", a: ["Giraffe", "Roe deer", "Panda", "Tiger"], x: "Roe bucks shed their antlers in autumn. New bony antlers grow back under a soft skin called velvet." }, fr: { q: "Quel animal perd ses bois chaque année et en refait de nouveaux ?", a: ["Girafe", "Chevreuil", "Panda", "Tigre"], x: "Le brocard perd ses bois en automne. Les nouveaux, en os, repoussent sous une peau appelée velours." }, es: { q: "¿Qué animal pierde su cornamenta cada año y le crece una nueva?", a: ["Jirafa", "Corzo", "Panda", "Tigre"], x: "El corzo macho pierde la cornamenta en otoño. La nueva, de hueso, crece bajo una piel llamada terciopelo." } } },
  { id: "c38", lvl: 2, type: "text", right: 0, t: { de: { q: "Welches Tier „bellt“ im Wald, wenn es sich erschreckt?", a: ["Reh", "Wildschwein", "Dachs", "Eichhörnchen"], x: "Rehe stoßen bei Gefahr laute, bellende Rufe aus – das „Schrecken“. Viele Spaziergänger denken dann an einen Hund." }, en: { q: "Which animal “barks” in the forest when it gets startled?", a: ["Roe deer", "Wild boar", "Badger", "Squirrel"], x: "Roe deer give loud, barking calls when alarmed. Many walkers think it’s a dog." }, fr: { q: "Quel animal « aboie » en forêt quand il est surpris ?", a: ["Chevreuil", "Sanglier", "Blaireau", "Écureuil"], x: "Le chevreuil pousse des cris forts, comme des aboiements, quand il sent un danger. Beaucoup de promeneurs pensent à un chien." }, es: { q: "¿Qué animal «ladra» en el bosque cuando se asusta?", a: ["Corzo", "Jabalí", "Tejón", "Ardilla"], x: "El corzo lanza fuertes gritos parecidos a ladridos cuando siente peligro. Muchos paseantes creen que es un perro." } } },
  { id: "c39", lvl: 2, type: "text", right: 2, t: { de: { q: "Wessen Panzer ist mit Wirbelsäule und Rippen verwachsen?", a: ["Krabbe", "Igel", "Schildkröte", "Schnecke"], x: "Eine Schildkröte kann ihren Panzer nie verlassen: Er besteht aus Knochen und ist fest mit dem Skelett verbunden." }, en: { q: "Whose shell is fused to its spine and ribs?", a: ["Crab", "Hedgehog", "Turtle", "Snail"], x: "A turtle can never leave its shell: it is made of bone and firmly joined to the skeleton." }, fr: { q: "Quel animal a une carapace soudée à sa colonne vertébrale et à ses côtes ?", a: ["Crabe", "Hérisson", "Tortue", "Escargot"], x: "La tortue ne peut jamais quitter sa carapace : elle est en os et soudée au squelette." }, es: { q: "¿Qué animal tiene el caparazón unido a la columna y las costillas?", a: ["Cangrejo", "Erizo", "Tortuga", "Caracol"], x: "La tortuga nunca puede salir de su caparazón: es de hueso y está unido al esqueleto." } } },
  { id: "c40", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer hat keine Zähne, sondern einen scharfen Hornschnabel?", a: ["Eidechse", "Schildkröte", "Hai", "Tiger"], x: "Schildkröten haben seit Millionen Jahren keine Zähne. Ihr Hornschnabel schneidet Pflanzen und Beute." }, en: { q: "Which animal has no teeth but a sharp horny beak?", a: ["Lizard", "Turtle", "Shark", "Tiger"], x: "Turtles have had no teeth for millions of years. Their horny beak cuts plants and prey." }, fr: { q: "Quel animal n'a pas de dents mais un bec corné tranchant ?", a: ["Lézard", "Tortue", "Requin", "Tigre"], x: "La tortue n'a plus de dents depuis des millions d'années. Son bec corné coupe plantes et proies." }, es: { q: "¿Qué animal no tiene dientes sino un pico córneo afilado?", a: ["Lagarto", "Tortuga", "Tiburón", "Tigre"], x: "La tortuga no tiene dientes desde hace millones de años. Su pico córneo corta plantas y presas." } } },
  { id: "c41", lvl: 2, type: "text", right: 2, t: { de: { q: "Wer ist ein Weichtier und damit mit dem Kraken verwandt?", a: ["Krabbe", "Marienkäfer", "Schnecke", "Schildkröte"], x: "Schnecken, Muscheln und Kraken gehören zu den Weichtieren. Krabben sind dagegen Krebstiere." }, en: { q: "Which animal is a mollusc and therefore related to the octopus?", a: ["Crab", "Ladybird", "Snail", "Turtle"], x: "Snails, clams and octopuses are all molluscs. Crabs, on the other hand, are crustaceans." }, fr: { q: "Quel animal est un mollusque, donc un parent de la pieuvre ?", a: ["Crabe", "Coccinelle", "Escargot", "Tortue"], x: "Escargots, moules et pieuvres sont des mollusques. Le crabe, lui, est un crustacé." }, es: { q: "¿Qué animal es un molusco y, por tanto, pariente del pulpo?", a: ["Cangrejo", "Mariquita", "Caracol", "Tortuga"], x: "Caracoles, almejas y pulpos son moluscos. El cangrejo, en cambio, es un crustáceo." } } },
  { id: "c42", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer stellt mit Drüsen am Hinterleib Wachs her?", a: ["Schmetterling", "Biene", "Marienkäfer", "Schnecke"], x: "Arbeiterinnen schwitzen Wachsplättchen aus Drüsen am Bauch aus und bauen daraus die Waben." }, en: { q: "Which animal makes wax with glands on its abdomen?", a: ["Butterfly", "Bee", "Ladybird", "Snail"], x: "Worker bees secrete wax flakes from glands on their abdomen and use them to build honeycomb." }, fr: { q: "Quel animal fabrique de la cire grâce à des glandes sur son abdomen ?", a: ["Papillon", "Abeille", "Coccinelle", "Escargot"], x: "Les ouvrières sécrètent des écailles de cire par des glandes du ventre et bâtissent ainsi leurs rayons." }, es: { q: "¿Qué animal produce cera con glándulas en el abdomen?", a: ["Mariposa", "Abeja", "Mariquita", "Caracol"], x: "Las obreras segregan escamas de cera por glándulas del abdomen y con ellas construyen los panales." } } },
  { id: "c43", lvl: 3, type: "text", right: 3, t: { de: { q: "Wer durchläuft eine Verwandlung mit Puppenstadium?", a: ["Frosch", "Krabbe", "Eidechse", "Marienkäfer"], x: "Marienkäfer entwickeln sich über Ei, Larve und Puppe zum Käfer. Kaulquappen werden ohne Puppe zum Frosch." }, en: { q: "Which animal goes through a metamorphosis with a pupal stage?", a: ["Frog", "Crab", "Lizard", "Ladybird"], x: "Ladybirds go from egg to larva to pupa to beetle. Tadpoles turn into frogs without a pupa." }, fr: { q: "Quel animal passe par une métamorphose avec un stade de nymphe ?", a: ["Grenouille", "Crabe", "Lézard", "Coccinelle"], x: "La coccinelle passe de l'œuf à la larve, à la nymphe puis à l'adulte. Le têtard devient grenouille sans nymphe." }, es: { q: "¿Qué animal pasa por una metamorfosis con fase de pupa?", a: ["Rana", "Cangrejo", "Lagarto", "Mariquita"], x: "La mariquita pasa de huevo a larva, pupa y adulto. El renacuajo se convierte en rana sin pupa." } } },
  { id: "c44", lvl: 2, type: "text", right: 2, t: { de: { q: "Wessen Flügel sind mit winzigen Schuppen bedeckt?", a: ["Biene", "Marienkäfer", "Schmetterling", "Papagei"], x: "Schmetterlinge heißen „Schuppenflügler“. Ihre Farben entstehen durch Tausende winzige Schuppen." }, en: { q: "Whose wings are covered with tiny scales?", a: ["Bee", "Ladybird", "Butterfly", "Parrot"], x: "Butterflies belong to the Lepidoptera, the 'scale wings'. Their colours come from thousands of tiny scales." }, fr: { q: "Quel animal a des ailes couvertes de minuscules écailles ?", a: ["Abeille", "Coccinelle", "Papillon", "Perroquet"], x: "Les papillons sont des lépidoptères, « ailes à écailles ». Leurs couleurs viennent de milliers d'écailles." }, es: { q: "¿Qué animal tiene las alas cubiertas de diminutas escamas?", a: ["Abeja", "Mariquita", "Mariposa", "Loro"], x: "Las mariposas son lepidópteros, «alas con escamas». Sus colores vienen de miles de escamas diminutas." } } },
  { id: "c45", lvl: 3, type: "text", right: 1, t: { de: { q: "Wer hat senkrechte Schlitzpupillen?", a: ["Tiger", "Fuchs", "Bär", "Otter"], x: "Füchse haben Schlitzpupillen wie Hauskatzen. Große Katzen wie der Tiger haben dagegen runde Pupillen." }, en: { q: "Which animal has vertical slit pupils?", a: ["Tiger", "Fox", "Bear", "Otter"], x: "Foxes have slit pupils like house cats. Big cats such as tigers, however, have round pupils." }, fr: { q: "Quel animal a des pupilles verticales en fente ?", a: ["Tigre", "Renard", "Ours", "Loutre"], x: "Le renard a des pupilles en fente comme le chat. Les grands félins comme le tigre ont des pupilles rondes." }, es: { q: "¿Qué animal tiene pupilas verticales en forma de rendija?", a: ["Tigre", "Zorro", "Oso", "Nutria"], x: "El zorro tiene pupilas de rendija como el gato. Los grandes felinos como el tigre las tienen redondas." } } },
  { id: "c46", lvl: 1, type: "text", right: 3, t: { de: { q: "Wer gehört zur Familie der Hunde?", a: ["Otter", "Panda", "Tiger", "Fuchs"], x: "Füchse gehören wie Wolf und Haushund zu den Hunden. Otter sind Marder, Pandas Bären, Tiger Katzen." }, en: { q: "Which animal belongs to the dog family?", a: ["Otter", "Panda", "Tiger", "Fox"], x: "Foxes are canids, like wolves and pet dogs. Otters are mustelids, pandas are bears and tigers are cats." }, fr: { q: "Quel animal appartient à la famille des chiens ?", a: ["Loutre", "Panda", "Tigre", "Renard"], x: "Le renard est un canidé comme le loup et le chien. La loutre est un mustélidé, le panda un ours, le tigre un félin." }, es: { q: "¿Qué animal pertenece a la familia de los perros?", a: ["Nutria", "Panda", "Tigre", "Zorro"], x: "El zorro es un cánido, como el lobo y el perro. La nutria es un mustélido, el panda un oso y el tigre un félido." } } },
  { id: "c47", lvl: 2, type: "text", right: 2, t: { de: { q: "Wer gehört zur Familie der Marder?", a: ["Fuchs", "Eichhörnchen", "Otter", "Panda"], x: "Otter sind ans Wasser angepasste Marder – verwandt mit Dachs, Iltis und Wiesel." }, en: { q: "Which animal belongs to the weasel family?", a: ["Fox", "Squirrel", "Otter", "Panda"], x: "Otters are mustelids adapted to water – relatives of badgers, polecats and weasels." }, fr: { q: "Quel animal appartient à la famille des mustélidés ?", a: ["Renard", "Écureuil", "Loutre", "Panda"], x: "La loutre est un mustélidé adapté à l'eau, parente du blaireau, du putois et de la belette." }, es: { q: "¿Qué animal pertenece a la familia de los mustélidos?", a: ["Zorro", "Ardilla", "Nutria", "Panda"], x: "La nutria es un mustélido adaptado al agua, pariente del tejón, el turón y la comadreja." } } },
  { id: "c48", lvl: 3, type: "text", right: 3, t: { de: { q: "Wessen Haut ist mit winzigen „Hautzähnchen“ bedeckt?", a: ["Eidechse", "Schildkröte", "Frosch", "Hai"], x: "Haihaut trägt Placoidschuppen, gebaut wie kleine Zähne. Gegen den Strich fühlt sie sich an wie Schleifpapier." }, en: { q: "Whose skin is covered with tiny 'skin teeth'?", a: ["Lizard", "Turtle", "Frog", "Shark"], x: "Shark skin has placoid scales built like tiny teeth. Stroked the wrong way it feels like sandpaper." }, fr: { q: "Quel animal a la peau couverte de minuscules « denticules » ?", a: ["Lézard", "Tortue", "Grenouille", "Requin"], x: "La peau du requin porte des écailles placoïdes, faites comme de petites dents. À rebrousse-poil, elle râpe." }, es: { q: "¿Qué animal tiene la piel cubierta de diminutos «dentículos»?", a: ["Lagarto", "Tortuga", "Rana", "Tiburón"], x: "La piel del tiburón tiene escamas placoideas, como dientes diminutos. A contrapelo parece papel de lija." } } },
  { id: "c49", lvl: 3, type: "text", right: 3, t: { de: { q: "Wer trinkt nicht mit dem Maul, sondern nimmt Wasser über die Haut auf?", a: ["Eidechse", "Schildkröte", "Igel", "Frosch"], x: "Frösche trinken nicht: Sie nehmen Wasser über die Haut auf, vor allem über eine dünne Stelle am Bauch." }, en: { q: "Which animal doesn't drink with its mouth but absorbs water through its skin?", a: ["Lizard", "Turtle", "Hedgehog", "Frog"], x: "Frogs don't drink: they soak up water through their skin, especially a thin patch on the belly." }, fr: { q: "Quel animal ne boit pas par la bouche mais absorbe l'eau par la peau ?", a: ["Lézard", "Tortue", "Hérisson", "Grenouille"], x: "La grenouille ne boit pas : elle absorbe l'eau par la peau, surtout par une zone fine du ventre." }, es: { q: "¿Qué animal no bebe por la boca sino que absorbe agua por la piel?", a: ["Lagarto", "Tortuga", "Erizo", "Rana"], x: "La rana no bebe: absorbe el agua por la piel, sobre todo por una zona fina del vientre." } } },
  { id: "c50", lvl: 1, type: "text", right: 2, t: { de: { q: "Welches dieser Tiere ist ein Reptil?", a: ["Frosch", "Krake", "Schildkröte", "Otter"], x: "Schildkröten sind Reptilien mit trockener, schuppiger Haut. Frösche sind Amphibien, Kraken Weichtiere." }, en: { q: "Which of these animals is a reptile?", a: ["Frog", "Octopus", "Turtle", "Otter"], x: "Turtles are reptiles with dry, scaly skin. Frogs are amphibians and octopuses are molluscs." }, fr: { q: "Lequel de ces animaux est un reptile ?", a: ["Grenouille", "Pieuvre", "Tortue", "Loutre"], x: "La tortue est un reptile à peau sèche et écailleuse. La grenouille est un amphibien, la pieuvre un mollusque." }, es: { q: "¿Cuál de estos animales es un reptil?", a: ["Rana", "Pulpo", "Tortuga", "Nutria"], x: "La tortuga es un reptil de piel seca y escamosa. La rana es un anfibio y el pulpo un molusco." } } },
];
